L4_1.m_bWaitClick = true
L4_1.m_fWaitTime = 0
L4_1.m_CharStrID = "COLLECTOR_NPC_NULL_FOOLSDAY"
L4_1.m_Pos = "C"
L4_1.m_Talk_KOREA = "콜록 콜록- 성공한 건가?"
L4_1.m_fTalkTime = 0.03
L4_1.m_Talk_JPN = "ゲホ、ゲホ……成功したのか？"
L4_1.m_Talk_ENG = "*Cough!* *Cough!* Did it work?"
L4_1.m_Talk_TWN = "咳咳，咳咳- 成功降落嗎？"
L4_1.m_Talk_THA = "*แค่ก!* *แค่ก!* ได้เรื่องมั้ยนะ?"
L4_1.m_Talk_VTN = "*Khụ!* *Khụ!* Có thành công không?"
L4_1.m_Talk_SCN = "咳咳、咳咳咳……成功了吗？"
L4_1.m_Talk_DEU = "*Hust, hust* Hat es funktioniert?"
L4_1.m_Talk_FRA = "Kof, kof ! Ça a marché ?"
L5_1 = {}
L5_1.m_CutScenKey_Talk = "FOOLSDAY_PART2_NODE1_EPILOGUE@5#Talk"
L5_1.m_CutScenProcessKey = 5
L5_1.m_CutScenID = 2700117
L5_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L5_1.m_bWaitClick = true
L5_1.m_fWaitTime = 0
L5_1.m_Face = "UNIT_HATE"
L5_1.m_CharStrID = "KNIGHT_REPLACER_UNIT_FOOLSDAY"
L5_1.m_Pos = "C"
L5_1.m_Talk_KOREA = "으윽… 충격으로 머리를 부딪힌 것 같은데."
L5_1.m_fTalkTime = 0.03
L5_1.m_Talk_JPN = "ううっ……衝撃で頭をぶつけたみたいだな。"
L5_1.m_Talk_ENG = "Urgh... I think I bumped my head."
L5_1.m_Talk_TWN = "呃…剛剛衝擊太大，害我好像撞到頭咧？"
L5_1.m_Talk_THA = "อึก... เหมือนหัวฉันจะกระแทกนะ"
L5_1.m_Talk_VTN = "Urgh... Hình như tôi bị u đầu rồi."
L5_1.m_Talk_SCN = "嘶……好像因为冲击撞到头部了。"
L5_1.m_Talk_DEU = "Urgh ... Ich glaube, ich habe mir beim Aufprall meinen Kopf gestoßen."
L5_1.m_Talk_FRA = "Urgh ... J'ai pris un sacré coup sur la tête."
L6_1 = {}
L6_1.m_CutScenKey_Talk = "FOOLSDAY_PART2_NODE1_EPILOGUE@6#Talk"
L6_1.m_CutScenProcessKey = 6
L6_1.m_CutScenID = 2700117
L6_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L6_1.m_bWaitClick = true
L6_1.m_fWaitTime = 0
L6_1.m_Face = "UNIT_SERIOUS"
L6_1.m_CharStrID = "KNIGHT_REPLACER_UNIT_FOOLSDAY"
L6_1.m_Pos = "C"
L6_1.m_Talk_KOREA = "어이, 네놈이 만들었다는 탈출장치. 제대로 작동한 거 맞아?"
L6_1.m_fTalkTime = 0.03
L6_1.m_Talk_JPN = "おい、てめえが作ったという脱出装置。ちゃんと作動したのか？"
L6_1.m_Talk_ENG = "Hey, that escape pod that you made. Are you sure it worked?"
L6_1.m_Talk_TWN = "喂，這是你們做的逃生裝置，確定有正常運作吧？"
L6_1.m_Talk_THA = "นี่ กระสวยลี้ภัยที่เธอทำน่ะ แน่ใจนะว่าใช้ได้?"
L6_1.m_Talk_VTN = "Này, đó là cái kén thoát hiểm mà cô đã phát minh ra mà. Cô có chắc là nó ra gì không thế?"
L6_1.m_Talk_SCN = "喂，你做的逃生装置，真的正常启动了吗？"
L6_1.m_Talk_DEU = "Hey, diese Fluchtkapsel, die du erfunden hast. Bist du dir wirklich sicher, dass sie funktioniert?"
L6_1.m_Talk_FRA = "Hé ! Ton truc là, ta capsule spatiale... Tu es sûre que ça a marché ?"
L7_1 = {}
L7_1.m_CutScenKey_Talk = "FOOLSDAY_PART2_NODE1_EPILOGUE@7#Talk"
L7_1.m_CutScenProcessKey = 7
L7_1.m_CutScenID = 2700117
L7_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L7_1.m_bWaitClick = true
L7_1.m_fWaitTime = 0
L7_1.m_CharStrID = "OROCHI_JAPAN_NULL_FOOLSDAY"
L7_1.m_Pos = "C"
L7_1.m_Talk_KOREA = "그 끈질긴 우주경찰 놈들에게서 도망칠 방법이 있다더니, 날 대체 어디로 데려온 것이냐?"
L7_1.m_fTalkTime = 0.03
L7_1.m_Talk_JPN = "あのしつこい宇宙警察の奴らから逃げる方法があると言っていたが、いったいどこへ連れて来たのだ？"
L7_1.m_Talk_ENG = "You told me that there is a way to run away from those tedious space cops, but where have you brought me to?"
L7_1.m_Talk_TWN = "說什麼有辦法可以躲避那些難纏的宇宙警察，結果到底把我帶到什麼地方來啦？"
L7_1.m_Talk_THA = "เจ้าบอกข้าว่ามีทางหนีจากพวกตำรวจอวกาศน่าเบื่อนั่น แล้วนี่เจ้าพาข้ามาที่ใดกัน?"
L7_1.m_Talk_VTN = "Ngươi nói là có cách để thoát khỏi lũ cảnh sát không gian dai như đỉa đó, nhưng ngươi đưa ta đi đâu đây?"
L7_1.m_Talk_SCN = "是你说有办法摆脱那些难缠的宇宙警察的，这到底是哪里？"
L7_1.m_Talk_DEU = "Du hast gesagt, es gebe einen Weg, diese nervtötenden Weltraumbullen abzuhängen ... Aber wohin zur Hölle hast du uns denn hier verschleppt?"
L7_1.m_Talk_FRA = "Tu nous a promis que grâce à lui, on pourrait échapper à ces pots de colle de policiers de l'espace. Mais on est où, là ?"
L8_1 = {}
L8_1.m_CutScenKey_Talk = "FOOLSDAY_PART2_NODE1_EPILOGUE@8#Talk"
L8_1.m_CutScenProcessKey = 8
L8_1.m_CutScenID = 2700117
L8_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L8_1.m_bWaitClick = true
L8_1.m_fWaitTime = 0
L8_1.m_CharStrID = "COLLECTOR_NPC_NULL_FOOLSDAY"
L8_1.m_Pos = "C"
L8_1.m_Talk_KOREA = "나도 몰라. 급하게 가동하느라 좌표를 설정할 시간도 없었으니까."
L8_1.m_fTalkTime = 0.03
L8_1.m_Talk_JPN = "俺にもわからないな。急いで起動させたせいで、座標を設定する時間すらなかった。"
L8_1.m_Talk_ENG = "I don’t know. I was rushing so much, I didn’t have time to set the coordinates."
L8_1.m_Talk_TWN = "我也不知道，剛剛啟動的時候情況很緊急，根本來不及設定座標。"
L8_1.m_Talk_THA = "ไม่รู้หรอกนะ ฉันก็รีบจัดๆ เลย ไม่ได้มีเวลาไปตั้งพิกัดหรอก"
L8_1.m_Talk_VTN = "Tôi không biết. Vội quá nên tôi chưa kịp cài đặt tọa độ."
L8_1.m_Talk_SCN = "我也不知道啊。因为是紧急启动的，我还没来得及设定坐标。"
L8_1.m_Talk_DEU = "Ich weiß es auch nicht. Ich habe mich so beeilt, dass ich keine Zeit hatte, die Koordinaten richtig einzugeben."
L8_1.m_Talk_FRA = "Aucune idée. Dans la précipitation, j'ai pas eu le temps de saisir des coordonnées précises."
L9_1 = {}
L9_1.m_CutScenKey_Talk = "FOOLSDAY_PART2_NODE1_EPILOGUE@9#Talk"
L9_1.m_CutScenProcessKey = 9
L9_1.m_CutScenID = 2700117
L9_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L9_1.m_bWaitClick = true
L9_1.m_fWaitTime = 0
L9_1.m_Face = "UNIT_SURPRISE"
L9_1.m_CharStrID = "KNIGHT_REPLACER_UNIT_FOOLSDAY"
L9_1.m_Pos = "C"
L9_1.m_Talk_KOREA = "킁킁, 어디서 탄내가 나는데?"
L9_1.m_fTalkTime = 0.03
L9_1.m_Talk_JPN = "クンクン、どこかで焦げた匂いがするが？"
L9_1.m_Talk_ENG = "*Sniff, sniff* Something’s burning."
L9_1.m_Talk_TWN = "嗅嗅，哪來的味道？"
L9_1.m_Talk_THA = "*ฟุดฟิด* กลิ่นอะไรไหม้ๆ"
L9_1.m_Talk_VTN = "*Ngửi, ngửi* Có mùi gì đó đang bốc cháy."
L9_1.m_Talk_SCN = "（嗅）哪里来的烧焦味儿？"
L9_1.m_Talk_DEU = "*Schnüffel, schnüffel* Irgendwas riecht hier verbrannt ... Woher kommt denn dieser Geruch?"
L9_1.m_Talk_FRA = "Snif, snif... ça sent le brûlé là, non ?"
