L11_1 = {}
L11_1.m_CutScenKey_Talk = "FOOLSDAY_PART2_NODE1_EPILOGUE@11#Talk"
L11_1.m_CutScenProcessKey = 11
L11_1.m_CutScenID = 2700117
L11_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L11_1.m_bWaitClick = true
L11_1.m_fWaitTime = 0
L11_1.m_Face = "UNIT_HATE"
L11_1.m_CharStrID = "COLLECTOR_NPC_NULL_FOOLSDAY"
L11_1.m_Pos = "C"
L11_1.m_Talk_KOREA = "아, 망할놈의 워프 장치가 또 고장 났군."
L11_1.m_fTalkTime = 0.03
L11_1.m_Talk_JPN = "あーあ、ポンコツワープ装置がまた壊れやがった。"
L11_1.m_Talk_ENG = "Oh, the damn warp machine is broken again."
L11_1.m_Talk_TWN = "可惡，這個爛東西的控制裝置又壞了。"
L11_1.m_Talk_THA = "เอ๊า ไอ้เครื่องวาร์ปบ้านั่นพังอีกแล้ว"
L11_1.m_Talk_VTN = "Ồ, cái máy dịch chuyển chết tiệt đó lại hỏng rồi."
L11_1.m_Talk_SCN = "啊，该死的传送装置又坏了。"
L11_1.m_Talk_DEU = "Oh, diese verdammte Warp-Maschine ist schon wieder kaputt."
L11_1.m_Talk_FRA = "Merde, le téléporteur est encore H.S."
L12_1 = {}
L12_1.m_CutScenKey_Talk = "FOOLSDAY_PART2_NODE1_EPILOGUE@12#Talk"
L12_1.m_CutScenProcessKey = 12
L12_1.m_CutScenID = 2700117
L12_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L12_1.m_bWaitClick = true
L12_1.m_fWaitTime = 0
L12_1.m_Face = "UNIT_SURPRISE"
L12_1.m_CharStrID = "KNIGHT_REPLACER_UNIT_FOOLSDAY"
L12_1.m_Pos = "C"
L12_1.m_Crash = 30
L12_1.m_Talk_KOREA = "뭣?! 그럼 돌아갈 방법이 없다는 거야?"
L12_1.m_fTalkTime = 0.03
L12_1.m_Talk_JPN = "はあ！？　となると、戻る方法がないのか？"
L12_1.m_Talk_ENG = "What?! Does that mean that there’s no way of going back?"
L12_1.m_Talk_TWN = "什麼？！我們沒辦法回去的意思嗎？"
L12_1.m_Talk_THA = "หา?! ก็แปลว่าเรากลับไปไม่ได้แล้วเหรอ?"
L12_1.m_Talk_VTN = "Cái gì cơ?! Thế tức là không có cách nào quay lại sao?"
L12_1.m_Talk_SCN = "什么？！那我们是回不去了吗？"
L12_1.m_Talk_DEU = "Was?! Bedeutet das etwa, dass es keinen Weg zurück gibt?"
L12_1.m_Talk_FRA = "Quoi ?! Ça veut dire qu'on est bloquées ici ?"
L13_1 = {}
L13_1.m_CutScenKey_Talk = "FOOLSDAY_PART2_NODE1_EPILOGUE@13#Talk"
L13_1.m_CutScenProcessKey = 13
L13_1.m_CutScenID = 2700117
L13_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L13_1.m_bWaitClick = true
L13_1.m_fWaitTime = 0
L13_1.m_CharStrID = "OROCHI_JAPAN_NULL_FOOLSDAY"
L13_1.m_Pos = "C"
L13_1.m_Talk_KOREA = "고작 한 번 사용한 걸로 망가지다니. 하여간 고철을 좋아하는 것 치고 제대로 완성할 줄 아는 것이 없구나."
L13_1.m_fTalkTime = 0.03
L13_1.m_Talk_JPN = "一度使ったくらいで壊れるとは。まったく、くず鉄好きの割にまともなものは作れんのだな。"
L13_1.m_Talk_ENG = "Breaking down after a single use? Should've known better from a junk collector like you."
L13_1.m_Talk_TWN = "才用一次就壞掉，說什麼喜歡廢鐵，結果根本一點辦法也沒有。"
L13_1.m_Talk_THA = "ใช้ครั้งเดียวก็พังแล้วงั้นหรือ? กับคนเก็บขยะอย่างเจ้า ข้าเองก็ควรรู้อยู่แล้วแท้ๆ"
L13_1.m_Talk_VTN = "Mới dùng một lần đã hỏng sao? Đáng lẽ ta không nên tin vào một kẻ thích sưu tập phế liệu như cô."
L13_1.m_Talk_SCN = "居然用一次就坏了。呵，果然，你这个废铁收藏家的称号真是名副其实。"
L13_1.m_Talk_DEU = "Nach nur einmaliger Benutzung ist sie kaputt. Ich hätte echt nichts anderes erwarten dürfen von einer Schrott-Sammlerin wie dir."
L13_1.m_Talk_FRA = "Comment ça, H.S. ? Après une seule utilisation ? Pour une collectionneuse, tu n'as pas l'air d'y connaître grand chose."
L14_1 = {}
L14_1.m_CutScenKey_Talk = "FOOLSDAY_PART2_NODE1_EPILOGUE@14#Talk"
L14_1.m_CutScenProcessKey = 14
L14_1.m_CutScenID = 2700117
L14_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L14_1.m_bWaitClick = true
L14_1.m_fWaitTime = 0
L14_1.m_Face = "UNIT_IDLE"
L14_1.m_CharStrID = "COLLECTOR_NPC_NULL_FOOLSDAY"
L14_1.m_Pos = "C"
L14_1.m_Talk_KOREA = "아아, 뭐가 이렇게 잔말들이 많아? 싫으면 거기 남아서 정의집행이나 당하시던가."
L14_1.m_fTalkTime = 0.03
L14_1.m_Talk_JPN = "ああ、ごちゃごちゃうるさい。イヤならそこに残って警察につかまったらどうだ？"
L14_1.m_Talk_ENG = "Stop complaining! You could've just stayed and let justice be served upon your pathetic selves."
L14_1.m_Talk_TWN = "喂喂，廢話那麼多，有意見的話你們怎麼不留在那直接被原地逮捕？"
L14_1.m_Talk_THA = "หยุดบ่นกันซะทีน่า! อยู่เฉยๆ รอรับความยุติธรรมไปเถอะพวกน่าสมเพชอย่างพวกเธอน่ะ"
L14_1.m_Talk_VTN = "Đừng có than vãn nữa! Lẽ ra cô đã phải ở lại đó để chịu phán xét cho cái tính bệnh hoạn đó rồi."
L14_1.m_Talk_SCN = "啊啊，废话那么多？不喜欢的话，你们就留在那儿等着被正义审判吧。"
L14_1.m_Talk_DEU = "Hör auf dich zu beschweren! Wenn es dir nicht gefällt, dann hättest du ja dort bleiben und Gerechtigkeit walten lassen können."
L14_1.m_Talk_FRA = "Vous allez arrêter de pleurer, oui ? Sans moi vous seriez déjà en train de croupir derrière les barreaux, je vous signale !"
L15_1 = {}
L15_1.m_CutScenKey_Talk = "FOOLSDAY_PART2_NODE1_EPILOGUE@15#Talk"
L15_1.m_CutScenProcessKey = 15
L15_1.m_CutScenID = 2700117
L15_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L15_1.m_bWaitClick = true
L15_1.m_fWaitTime = 0
L15_1.m_Face = "UNIT_PRIDE"
L15_1.m_CharStrID = "COLLECTOR_NPC_NULL_FOOLSDAY"
L15_1.m_Pos = "C"
L15_1.m_Talk_KOREA = "그러고보니 그 강소영이란 우주경찰 녀석, 널 보면서 만년 묵은 뱀으로 술을 담그면 기가 막히겠다고 했었지 아마?"
L15_1.m_fTalkTime = 0.03
L15_1.m_Talk_JPN = "そういえばあのマエカワ・ナツミという宇宙警察、お前を見ながら一万年生きた蛇で作った酒はうまそうだとか言ってたよな？"
L15_1.m_Talk_ENG = "Come to think of it, that space cop named Kang Soyoung... She said something about brewing liquor with a snake that’s old as time itself, no?"
L15_1.m_Talk_TWN = "話說回來，那個叫姜素英的宇宙警察應該是說要把你抓去泡蛇酒喝掉吧？"
L15_1.m_Talk_THA = "จะว่าไป ตำรวจอวกาศที่ชื่อคัง โซยองนั่น... เธอพูดอะไรสักอย่างเรื่องเมื่อก่อนเข้าเอางูดองเหล้ากันรึเปล่านะ?"
L15_1.m_Talk_VTN = "Đúng rồi, con bé cảnh sát không gian tên là Kang Soyoung đó...Cô ta nói gì về việc ngâm rượu rắn già ấy phải không nhỉ?"
L15_1.m_Talk_SCN = "对了，那个叫樱井爱理的宇宙警察好像说过，想用你这条万年老蛇泡酒喝吧？"
L15_1.m_Talk_DEU = "Wenn ich so darüber nachdenke, hat diese Weltraumpolizistin namens Kang Soyoung dich angesehen und gemeint, dass sie mal Lust darauf hätte, eine 10.000 Jahre alte Schlange in Schnaps einzulegen, nicht wahr?"
L15_1.m_Talk_FRA = "Maintenant que j'y pense cette flic là, Kang Soyoung ... Elle parlait pas de faire un alcool à base de sang de serpent millénaire ?"
L16_1 = {}
L16_1.m_CutScenKey_Talk = "FOOLSDAY_PART2_NODE1_EPILOGUE@16#Talk"
L16_1.m_CutScenProcessKey = 16
L16_1.m_CutScenID = 2700117
L16_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L16_1.m_bWaitClick = true
L16_1.m_fWaitTime = 0
L16_1.m_Face = "UNIT_HATE"
L16_1.m_CharStrID = "OROCHI_JAPAN_NULL_FOOLSDAY"
L16_1.m_Pos = "C"
L16_1.m_Crash = 20
L16_1.m_Talk_KOREA = "아직도 생각만 하면 소름이 끼치는군."
L16_1.m_fTalkTime = 0.03
L16_1.m_Talk_JPN = "いまだに思い出すだけでぞっとする。"
L16_1.m_Talk_ENG = "I still get goosebumps when I think about it."
L16_1.m_Talk_TWN = "想到我就頭皮發麻。"
L16_1.m_Talk_THA = "นึกถึงทีไร ข้ายังขนลุกทุกที"
L16_1.m_Talk_VTN = "Ta vẫn nổi da gà khi nghĩ về điều đó."
L16_1.m_Talk_SCN = "现在想想还是觉得不寒而栗。"
L16_1.m_Talk_DEU = "Ich bekomme immer noch Gänsehaut, wenn ich nur daran nachdenke."
L16_1.m_Talk_FRA = "Rien que d'y penser, j'en ai encore la chair de poule."
L17_1 = {}
L17_1.m_CutScenKey_Talk = "FOOLSDAY_PART2_NODE1_EPILOGUE@17#Talk"
L17_1.m_CutScenProcessKey = 17
L17_1.m_CutScenID = 2700117
L17_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L17_1.m_bWaitClick = true
L17_1.m_fWaitTime = 0
L17_1.m_CharStrID = "OROCHI_JAPAN_NULL_FOOLSDAY"
L17_1.m_Pos = "C"
L17_1.m_Talk_KOREA = "난 인간의 마음을 읽을 줄 알지만… 그 눈빛은 진심이었어."
L17_1.m_fTalkTime = 0.03
L17_1.m_Talk_JPN = "我は人間の心を読むことができるが……あの目は本気であった。"
L17_1.m_Talk_ENG = "I can read human minds... And she wasn’t joking when she said it."
L17_1.m_Talk_TWN = "雖然我會讀人類的心思…但她的眼神，是認真的。"
L17_1.m_Talk_THA = "ข้าอ่านใจมนุษย์ได้... และตอนที่นางพูด นางไม่ได้ล้อเล่น"
L17_1.m_Talk_VTN = "Ta đọc được tâm trí con người...Và cô ta không hề đùa khi nói thế đâu."
L17_1.m_Talk_SCN = "我能读懂人心……她当时那个眼神是认真的。"
L17_1.m_Talk_DEU = "Ich kann die Gedanken von Menschen lesen ... und sie meinte es ernst, als sie das gesagt hat."
L17_1.m_Talk_FRA = "Je peux lire le cœur des humains... et je peux te dire qu'elle était très sérieuse."
L18_1 = {}
L18_1.m_CutScenKey_Talk = "FOOLSDAY_PART2_NODE1_EPILOGUE@18#Talk"
L18_1.m_CutScenProcessKey = 18
L18_1.m_CutScenID = 2700117
L18_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L18_1.m_bWaitClick = true
L18_1.m_fWaitTime = 0
L18_1.m_Face = "UNIT_DESPAIR"
L18_1.m_CharStrID = "KNIGHT_REPLACER_UNIT_FOOLSDAY"
L18_1.m_Pos = "C"
L18_1.m_Talk_KOREA = "하아, 배고프구만. 난 밥이나 먹으러 가련다."
L18_1.m_fTalkTime = 0.03
L18_1.m_Talk_JPN = "はあ、腹減ったなあ。アタシは飯でも食いに行くぞ。"
L18_1.m_Talk_ENG = "*Sigh...* I’m hungry. Might as well get something to eat."
L18_1.m_Talk_TWN = "唉唷，肚子好餓，我要去找東西吃。"
L18_1.m_Talk_THA = "*เฮ้อ...* หิวแล้วล่ะ เราควรหาอะไรกินกันนะ"
L18_1.m_Talk_VTN = "*Thở dài...* Tôi đói rã cả họng ra. Phải tìm cái gì đó ăn thôi."
L18_1.m_Talk_SCN = "啊——好饿啊。我要去吃饭——"
L18_1.m_Talk_DEU = "Ahh, ich habe Hunger. Ich werde mir etwas zu essen suchen."
L18_1.m_Talk_FRA = "*Soupir* J'ai faim. Je vais manger un bout, moi."
L19_1 = {}
L19_1.m_CutScenKey_Talk = "FOOLSDAY_PART2_NODE1_EPILOGUE@19#Talk"
L19_1.m_CutScenProcessKey = 19
L19_1.m_CutScenID = 2700117
L19_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L19_1.m_bWaitClick = true
L19_1.m_fWaitTime = 0
L19_1.m_Face = "UNIT_IDLE"
L19_1.m_CharStrID = "OROCHI_JAPAN_NULL_FOOLSDAY"
L19_1.m_Pos = "C"
L19_1.m_Talk_KOREA = "무식한 녀석이 팔자걱정도 없구나. 여기가 어딘 줄 알고 함부로 발길을 옮기는 것이냐?"
L19_1.m_fTalkTime = 0.03
L19_1.m_Talk_JPN = "愚か者は先の心配もないのだな。ここがどこかもわからないのにむやみに動くつもりなのか？"
L19_1.m_Talk_ENG = "Look who’s making herself at home already. You don’t even know the area here!"
L19_1.m_Talk_TWN = "頭腦簡單的傢伙果然是天不怕地不怕。你以為這裡是哪裡，竟然敢輕易移動腳步？"
L19_1.m_Talk_THA = "ดูเอาเถิดว่าใครทำตัวเหมือนอยู่บ้านเสียแล้ว เจ้าไม่รู้จักที่นี่ด้วยซ้ำ!"
L19_1.m_Talk_VTN = "Xem ai thoải mái chưa kìa. Ngươi còn không biết đây là chốn nào sao!"
L19_1.m_Talk_SCN = "哼，真是无知者无畏啊。一无所知的陌生之地，竟然也敢随便乱走？"
L19_1.m_Talk_DEU = "Wie unbekümmert du doch bist. Du kennst die Gegend hier doch nicht einmal!"
L19_1.m_Talk_FRA = "Mais oui bien sûr, fais comme chez toi. Et où crois-tu que nous sommes, exactement ?"
L20_1 = {}
L20_1.m_CutScenKey_Talk = "FOOLSDAY_PART2_NODE1_EPILOGUE@20#Talk"
L20_1.m_CutScenProcessKey = 20
L20_1.m_CutScenID = 2700117
L20_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L20_1.m_bWaitClick = true
L20_1.m_fWaitTime = 0
L20_1.m_CharStrID = "KNIGHT_REPLACER_UNIT_FOOLSDAY"
L20_1.m_Pos = "C"
L20_1.m_Talk_KOREA = "우리가 살던 동네랑 별 차이 없어 보이는데, 아무 식당이나 들어가면 되는 거 아닌가?"
L20_1.m_fTalkTime = 0.03
L20_1.m_Talk_JPN = "アタシたちが住んでいた街とあんま変わんないようだけど、適当にどこかの店に入ればいいんじゃないか？"
L20_1.m_Talk_ENG = "It doesn’t look that different from our side of town. Just get inside any restaurant."
L20_1.m_Talk_TWN = "這裡看起來跟我們住的地方附近差不多啊，不是隨便找間餐廳進去就好嗎？"
L20_1.m_Talk_THA = "มันก็ดูไม่ต่างจากเมืองฟากที่เราอยู่นี่ เข้าร้านอาหารไปสักร้านเถอะ"
L20_1.m_Talk_VTN = "Nó trông chẳng khác gì mấy so với thị trấn nơi chúng ta sống. Cứ vào bất kỳ nhà hàng nào cũng được."
L20_1.m_Talk_SCN = "这里看起来跟我们生活的地方没多大区别啊，随便找一家餐厅不就行了吗？"
L20_1.m_Talk_DEU = "Es sieht ein bisschen wie unsere Nachbarschaft aus. Wollen wir einfach mal in irgendein Restaurant reingehen?"
L20_1.m_Talk_FRA = "Bah, ça a pas l'air si différent de mon quartier, ici. N'importe quel restaurant fera l'affaire."
L21_1 = {}
L21_1.m_CutScenKey_Talk = "FOOLSDAY_PART2_NODE1_EPILOGUE@21#Talk"
L21_1.m_CutScenProcessKey = 21
L21_1.m_CutScenID = 2700117
L21_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L21_1.m_bWaitClick = true
L21_1.m_fWaitTime = 0
L21_1.m_CharStrID = "OROCHI_JAPAN_NULL_FOOLSDAY"
L21_1.m_Pos = "C"
L21_1.m_Talk_KOREA = "어리석군. 언제 어디서 우주경찰 녀석들이 다시 나타날지도 모르는데…"
L21_1.m_fTalkTime = 0.03
L21_1.m_Talk_JPN = "愚かな。いつどこから宇宙警察がまた現れるやも知れぬというのに……"
L21_1.m_Talk_ENG = "Fool. Those space cops could barge in any second..."
L21_1.m_Talk_TWN = "蠢東西，宇宙警察不知道什麼時候又會冒出來…"
L21_1.m_Talk_THA = "ช่างโง่เง่า พวกตำรวจอวกาศโผล่มาได้ทุกเมื่อ..."
L21_1.m_Talk_VTN = "Ngu ngốc. Đám cảnh sát không gian đó có thể ập vào bất cứ lúc nào..."
L21_1.m_Talk_SCN = "蠢货。在宇宙警察随时都可能找来的当下……"
L21_1.m_Talk_DEU = "Hast du sie noch alle?! Diese Weltraumbullen könnten jederzeit wieder auftauchen ..."
L21_1.m_Talk_FRA = "Imbécile. La police de l'espace pourrait débarquer d'une minute à l'autre, et tu..."
L22_1 = {}
L22_1.m_CutScenKey_Talk = "FOOLSDAY_PART2_NODE1_EPILOGUE@22#Talk"
L22_1.m_CutScenProcessKey = 22
L22_1.m_CutScenID = 2700117
L22_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L22_1.m_bWaitClick = true
L22_1.m_fWaitTime = 0
L22_1.m_CharStrID = "COLLECTOR_NPC_NULL_FOOLSDAY"
L22_1.m_Pos = "C"
L22_1.m_Talk_KOREA = "같이 가자. 대충 끼니 때우고 주변 좀 둘러봐야겠네."
L22_1.m_fTalkTime = 0.03
L22_1.m_Talk_JPN = "一緒に行こう。適当に食事でもして周りを見回ってみる。"
L22_1.m_Talk_ENG = "Take me with you. I should look around after getting some food."
L22_1.m_Talk_TWN = "一起去吧，先吃點東西再觀察一下周圍。"
L22_1.m_Talk_THA = "ฉันไปด้วย หาอะไรกินแล้วลองดูรอบๆ กันเถอะ"
L22_1.m_Talk_VTN = "Đi cùng đi. Chúng ta có thể đi ngắm nghía qua một chút sau khi ăn chút gì đó."
L22_1.m_Talk_SCN = "一起吧。吃点东西，然后在周围打探一下。"
L22_1.m_Talk_DEU = "Lass uns zusammen gehen. Wir sollten uns hier mal ein wenig umsehen, nachdem wir etwas gegessen haben."
L23_1 = "Je viens avec toi. Ça sera l'occasion de faire un peu de repérage."
L22_1.m_Talk_FRA = L23_1
