L24_1.m_Pos = "C"
L25_1 = "이놈들…! 날 혼자 두고 어딜 가는 것이냐!"
L24_1.m_Talk_KOREA = L25_1
L24_1.m_fTalkTime = 0.03
L25_1 = "こやつら……！　我を一人残してどこへ行くのだ！"
L24_1.m_Talk_JPN = L25_1
L25_1 = "You idiots...! Don’t leave me here alone!"
L24_1.m_Talk_ENG = L25_1
L25_1 = "你們二個…！是要扔下我去哪！"
L24_1.m_Talk_TWN = L25_1
L25_1 = "พวกโง่นี่...! อย่าทิ้งข้าไว้คนเดียวสิ!"
L24_1.m_Talk_THA = L25_1
L25_1 = "Hai ngươi...! Đừng có để ta ở đây một mình chứ!"
L24_1.m_Talk_VTN = L25_1
L25_1 = "你、你们两个……！扔下我一个人要去哪里！"
L24_1.m_Talk_SCN = L25_1
L25_1 = "Sagt mal, spinnt ihr?! Ihr könnt mich hier doch nicht allein zurücklassen!"
L24_1.m_Talk_DEU = L25_1
L25_1 = "Comment osez-vous...! Ne me laissez pas seule ici !"
