L28_1 = "C_L_M_I"
L27_1.m_Pos = L28_1
L28_1 = "아아, 간만에 배부르게 먹었네."
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "ああ、久々に腹いっぱい食ったな。"
L27_1.m_Talk_JPN = L28_1
L28_1 = "Aah, now that’s what I call a good meal."
L27_1.m_Talk_ENG = L28_1
L28_1 = "噢～好久沒吃這麼飽咧。"
L27_1.m_Talk_TWN = L28_1
L28_1 = "อาห์ แบบนี้สิของอร่อย"
L27_1.m_Talk_THA = L28_1
L28_1 = "Aah, ăn thế mới gọi là ăn chứ."
L27_1.m_Talk_VTN = L28_1
L28_1 = "嗝，吃得好饱啊。"
L27_1.m_Talk_SCN = L28_1
L28_1 = "Ahhh, es ist schon eine Weile her, dass ich so satt war."
L27_1.m_Talk_DEU = L28_1
L28_1 = "Ah ! C'était ce que j'appelle un bon repas."
L27_1.m_Talk_FRA = L28_1
