L28_1.m_CharStrID = "COLLECTOR_NPC_NULL_FOOLSDAY"
L28_1.m_Pos = "C"
L29_1 = "이쪽 세계도 제법 요리 수준이 괜찮군."
L28_1.m_Talk_KOREA = L29_1
L28_1.m_fTalkTime = 0.03
L29_1 = "こっちの世界も料理はなかなかだな。"
L28_1.m_Talk_JPN = L29_1
L29_1 = "The culinary industry in this world isn’t so bad after all."
L28_1.m_Talk_ENG = L29_1
L29_1 = "看來這個世界的東西也蠻不錯吃的。"
L28_1.m_Talk_TWN = L29_1
L29_1 = "อุตสาหกรรมอาหารที่นี่ไม่เลวเลยแฮะ"
L28_1.m_Talk_THA = L29_1
L29_1 = "Chất lượng đồ ăn ở chỗ này cuộc cũng không tệ lắm."
L28_1.m_Talk_VTN = L29_1
L29_1 = "这个世界的烹饪水平也不错呢。"
L28_1.m_Talk_SCN = L29_1
L29_1 = "Das Kochkunst dieser Welt kann sich wirklich sehen lassen. Ich habe schon lange nicht mehr so gut gegessen."
L28_1.m_Talk_DEU = L29_1
L29_1 = "La bouffe est pas si mal, ici."
L28_1.m_Talk_FRA = L29_1
