L31_1 = "FOOLSDAY_PART2_NODE1_EPILOGUE@30#Talk"
L30_1.m_CutScenKey_Talk = L31_1
L30_1.m_CutScenProcessKey = 30
L30_1.m_CutScenID = 2700117
L30_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L30_1.m_bWaitClick = true
L30_1.m_fWaitTime = 0
L30_1.m_Face = "UNIT_PRIDE"
L31_1 = "HARIM_NPC_FOOLSDAY_NULL"
L30_1.m_CharStrID = L31_1
L31_1 = "L_M_I"
L30_1.m_Pos = L31_1
L31_1 = "그렇죠? 얼마 전에 유미나란 분이 다녀가신 뒤로 저희 세상에도 맛있는 요리들이 엄~청 많아졌다고요."
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "ですよね？　この前ヤナギ・ミナって人が立ち寄ってから、僕たちの世界にも美味しい料理がすごく増えたんですよ。"
L30_1.m_Talk_JPN = L31_1
L31_1 = "Indeed! There have been tons of improvements in our cuisine after a foreigner called Yoo Mina visited."
L30_1.m_Talk_ENG = L31_1
L31_1 = "是不是？之前有個叫劉米娜的人來過後，我們的世界好吃的東西就變超～多的。"
L30_1.m_Talk_TWN = L31_1
L31_1 = "ใช่เลยค่ะ! ครัวเราพัฒนาไปเยอะเลยนะคะ หลังจากชาวต่างจักรวาลที่ชื่อ ยู มีนา มาอยู่ที่นี่"
L30_1.m_Talk_THA = L31_1
L31_1 = "Đúng là thế! Ẩm thực của chúng ta đã có sự tiến bộ to lớn sau khi cái người tên Yoo Mina đó tới."
L30_1.m_Talk_VTN = L31_1
L31_1 = "是吧！不久前那个叫刘米娜的女孩子来过之后，我们的世界就多了很多美食。"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Nicht wahr? Vor Kurzem hat uns jemand namens Yoo Mina besucht und dank ihr gibt es jetzt unzählige neue Speisen in unserer lokalen Küche."
L30_1.m_Talk_DEU = L31_1
L31_1 = "N'est-ce pas ? Depuis la visite de Yoo Mina, nous avons pu apporter une quantité d'améliorations à nos techniques culinaires."
L30_1.m_Talk_FRA = L31_1
L31_1 = {}
L32_1 = "FOOLSDAY_PART2_NODE1_EPILOGUE@31#Talk"
L31_1.m_CutScenKey_Talk = L32_1
L32_1 = 31
L31_1.m_CutScenProcessKey = L32_1
L31_1.m_CutScenID = 2700117
L31_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L31_1.m_bWaitClick = true
L31_1.m_fWaitTime = 0
L31_1.m_Face = "UNIT_PRIDE"
L32_1 = "SORIM_NPC_FOOLSDAY_NULL"
L31_1.m_CharStrID = L32_1
L32_1 = "R_M_I"
L31_1.m_Pos = L32_1
L32_1 = "치킨도, 탕수육도, 전부 그 사람에게 만드는 법을 전수받았다. 우리 직장에선 그녀를 영웅으로 추앙하고 있지."
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "チキンも、酢豚も、全部あの人から作り方を教えてもらった。職場ではみんな彼女を英雄と仰いでる。"
L31_1.m_Talk_JPN = L32_1
L32_1 = "Fried Chicken, Sweet and Sour Pork... Many things we learned from her. We honor her as a hero in our company."
L31_1.m_Talk_ENG = L32_1
L32_1 = "炸雞和糖醋肉都是跟那個人學的，在我們業界裡都把她奉為英雄欸。"
L31_1.m_Talk_TWN = L32_1
L32_1 = "ไก่ทอด หมูผัดเปรี้ยวหวาน... เราได้เรียนรู้จากเธอหลายอย่าง เราให้เกียรติเธอเป็นฮีโร่ของบริษัทเราเลยล่ะ"
L31_1.m_Talk_THA = L32_1
L32_1 = "Gà chiên, thịt lợn chua ngọt...Chúng ta đã học được rất nhiều thứ từ cô ấy. Chúng ta tôn sùng cô ấy là anh hùng của công ty này."
L31_1.m_Talk_VTN = L32_1
L32_1 = "炸鸡和糖醋肉的做法都是她教的。米娜是我们公司的英雄！"
L31_1.m_Talk_SCN = L32_1
L32_1 = "Gebratenes Hühnchen, süß-saures Schweinefleisch ... Sie hat uns all diese Gerichte beigebracht. An unserem Arbeitsplatz wird sie als Heldin verehrt."
L31_1.m_Talk_DEU = L32_1
L32_1 = "Poulet frit, porc aigre-doux... Son passage nous a permis d'étendre notre carte vers des horizons insoupçonnés. C'est une véritable héroïne à nos yeux."
L31_1.m_Talk_FRA = L32_1
L32_1 = {}
