L34_1 = "FOOLSDAY_PART2_NODE1_EPILOGUE@33#Talk"
L33_1.m_CutScenKey_Talk = L34_1
L34_1 = 33
L33_1.m_CutScenProcessKey = L34_1
L33_1.m_CutScenID = 2700117
L33_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L33_1.m_bWaitClick = true
L33_1.m_fWaitTime = 0
L33_1.m_Face = "UNIT_SURPRISE"
L33_1.m_CharStrID = "KNIGHT_REPLACER_UNIT_FOOLSDAY"
L33_1.m_Pos = "C"
L33_1.m_Crash = 20
L34_1 = "뭣? 고작 한 사람이 그 엄청난 메뉴들을 전부 개발했다고? 그 녀석… 신이냐?!"
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "は？　たった一人であの数のメニューを全部開発しただって？　そいつ……神かよ！？"
L33_1.m_Talk_JPN = L34_1
L34_1 = "What? All those recipes from a single person? Is she... a god?"
L33_1.m_Talk_ENG = L34_1
L34_1 = "什麼？這麼厲害的菜單都是她一個人開發的嗎？那傢伙…是神嗎？！"
L33_1.m_Talk_TWN = L34_1
L34_1 = "หา? สูตรทั้งหมดนั่นมาจากคนคนเดียวเหรอ? เธอเป็น... พระเจ้ารึไง?"
L33_1.m_Talk_THA = L34_1
L34_1 = "Cái gì cơ? Bằng đấy công thức do một người nghĩ ra sao? Cô ấy có phải... thần không thế?"
L33_1.m_Talk_VTN = L34_1
L34_1 = "哦？那这些菜品都是她一个人开发的？那家伙……是神仙吗？！"
L33_1.m_Talk_SCN = L34_1
L34_1 = "Was? All diese Rezepte stammen von einer einzelnen Person? Ist sie etwa ... eine Göttin?"
L33_1.m_Talk_DEU = L34_1
L34_1 = "Quoi ? Tu veux dire que tous les plats sur ta carte proviennent d'une seule et même personne ? C'est qui, cette fille... une déesse ?"
L33_1.m_Talk_FRA = L34_1
L34_1 = {}
L35_1 = "FOOLSDAY_PART2_NODE1_EPILOGUE@34#Talk"
L34_1.m_CutScenKey_Talk = L35_1
L35_1 = 34
L34_1.m_CutScenProcessKey = L35_1
L34_1.m_CutScenID = 2700117
L34_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L34_1.m_bWaitClick = true
L34_1.m_fWaitTime = 0
L34_1.m_CharStrID = "COLLECTOR_NPC_NULL_FOOLSDAY"
L34_1.m_Pos = "C"
L35_1 = "아무래도, 다른 세계선에서 이쪽을 다녀간 게 우리가 처음이 아닌 모양이군."
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "どうやら他の世界線からこっちに立ち寄ったのは俺たちが最初じゃないようだな。"
L34_1.m_Talk_JPN = L35_1
L35_1 = "It sounds like we’re not the first ones to stumble upon this universe."
L34_1.m_Talk_ENG = L35_1
L35_1 = "看來我們並不是第一個從其他世界來到這裡的人。"
L34_1.m_Talk_TWN = L35_1
L35_1 = "เหมือนเราจะไม่ใช่พวกแรกที่มาจักรวาลนี้นะ"
L34_1.m_Talk_THA = L35_1
L35_1 = "Có vẻ như chúng ta không phải là người đầu tiên tình cờ tới vũ trụ này."
L34_1.m_Talk_VTN = L35_1
L35_1 = "看来我们不是第一批到这个世界的人。"
L34_1.m_Talk_SCN = L35_1
L35_1 = "Anscheinend sind wir nicht die ersten, die diesen Ort von einer anderen Welt aus besuchen."
L34_1.m_Talk_DEU = L35_1
L35_1 = "Il semble que nous ne sommes pas les premières à visiter ce monde."
L34_1.m_Talk_FRA = L35_1
L35_1 = {}
L36_1 = "FOOLSDAY_PART2_NODE1_EPILOGUE@35#Talk"
L35_1.m_CutScenKey_Talk = L36_1
L36_1 = 35
L35_1.m_CutScenProcessKey = L36_1
L35_1.m_CutScenID = 2700117
L35_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L35_1.m_bWaitClick = true
L35_1.m_fWaitTime = 0
L35_1.m_Face = "UNIT_PRIDE"
L35_1.m_CharStrID = "COLLECTOR_NPC_NULL_FOOLSDAY"
L35_1.m_Pos = "C"
L36_1 = "다시 돌아갈 방법을 의외로 쉽게 찾을지도 모르겠어."
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "戻る方法は意外と簡単に見つかるかもしれない。"
L35_1.m_Talk_JPN = L36_1
L36_1 = "Perhaps it wouldn’t be so hard to find out a way to go back after all."
L35_1.m_Talk_ENG = L36_1
L36_1 = "或許回去的方法比想像中還容易找到呢。"
L35_1.m_Talk_TWN = L36_1
L36_1 = "บางทีสุดท้ายอาจหาทางกลับไม่ยากนักก็ได้"
L35_1.m_Talk_THA = L36_1
L36_1 = "Có lẽ tìm đường quay lại cũng không quá khó."
L35_1.m_Talk_VTN = L36_1
L36_1 = "说不定很快就能找到回去的办法。"
L35_1.m_Talk_SCN = L36_1
L36_1 = "Vielleicht wäre es doch nicht so schwer, einen Weg zurück zu finden."
L35_1.m_Talk_DEU = L36_1
L36_1 = "C'est encourageant. On trouvera peut-être un moyen de rentrer chez nous, après tout."
L35_1.m_Talk_FRA = L36_1
L36_1 = {}
L37_1 = "FOOLSDAY_PART2_NODE1_EPILOGUE@36#Talk"
L36_1.m_CutScenKey_Talk = L37_1
L37_1 = 36
L36_1.m_CutScenProcessKey = L37_1
L36_1.m_CutScenID = 2700117
L36_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L36_1.m_bWaitClick = true
L36_1.m_fWaitTime = 0
L37_1 = "UNIT_LAUGH"
L36_1.m_Face = L37_1
L36_1.m_CharStrID = "OROCHI_JAPAN_NULL_FOOLSDAY"
L36_1.m_Pos = "C"
L37_1 = "남는 게 시간인데 급할 필요 없지. 그 우주경찰 녀석들이 늙어 죽을 때까지 잠시 여기 머무르는 것도 나쁘지 않겠구나."
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "時間なら有り余っている、急ぐ必要はなかろう。あの宇宙警察のやつらが老いて死ぬまでしばらくここに留まるのも悪くないな。"
L36_1.m_Talk_JPN = L37_1
L37_1 = "No need to rush. We have all the time we need. It wouldn’t be so bad staying here for a while, until those mortal space cops grow old and die."
L36_1.m_Talk_ENG = L37_1
L37_1 = "接下來就是時間問題，不需要著急。在那個宇宙警察老死前，暫時留在這裡好像也不錯。"
L36_1.m_Talk_TWN = L37_1
L37_1 = "ไม่ต้องรีบไปหรอก เรามีเวลามาเท่าที่ต้องการอยู่แล้ว อยู่ที่นี่กันสักพักก็คงไม่เลวหรอก รอให้พวกตำรวจอวกาศนั่นแก่ตายไปเอง"
L36_1.m_Talk_THA = L37_1
L37_1 = "Không cần phải vội. Chúng ta có đủ thời gian mà. Ở đây một thời gian không tệ đâu, cứ chờ cho đến khi mấy tên cảnh sát không gian chết giẫm đó già rồi ngủm đi."
L36_1.m_Talk_VTN = L37_1
L37_1 = "呵呵，我们有的是时间，所以不用着急。暂时待在这里，等到那些宇宙警察老死也是不错的选择。"
L36_1.m_Talk_SCN = L37_1
L37_1 = "Wir haben noch Zeit, also kein Grund zur Eile. Es würde auch nicht schaden, eine Weile hier zu bleiben, bis diese Weltraumbullen an Altersschwäche sterben."
L36_1.m_Talk_DEU = L37_1
L37_1 = "Nul besoin de se hâter, nous avons tout le temps qu'il faut.Nous pourrions rester ici quelques temps, à l'ombre, jusqu'à ce que les policiers de l'espace meurent de vieillesse."
L36_1.m_Talk_FRA = L37_1
L37_1 = {}
L38_1 = "FOOLSDAY_PART2_NODE1_EPILOGUE@37#Talk"
L37_1.m_CutScenKey_Talk = L38_1
L38_1 = 37
L37_1.m_CutScenProcessKey = L38_1
L37_1.m_CutScenID = 2700117
L37_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L37_1.m_bWaitClick = true
L37_1.m_fWaitTime = 0
L37_1.m_Face = "UNIT_HATE"
L37_1.m_CharStrID = "COLLECTOR_NPC_NULL_FOOLSDAY"
L37_1.m_Pos = "C"
L38_1 = "웃기지 마. 우리가 너처럼 천년만년 사는 이무긴 줄 알아?"
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "ふざけるな。俺らがお前のように千年も万年も生きられる大蛇だと思ってるのか？"
L37_1.m_Talk_JPN = L38_1
L38_1 = "You’ve got to be kidding me. Not everyone is a half-immortal serpent like you."
L37_1.m_Talk_ENG = L38_1
L38_1 = "說什麼笑話，你以為我們跟你這條蟒蛇一樣可以活到千萬年嗎？"
L37_1.m_Talk_TWN = L38_1
L38_1 = "ล้อเล่นละเธอ ทุกคนไม่ได้เป็นงูที่กึ่งความอมตะอย่างเธอนะ"
L37_1.m_Talk_THA = L38_1
L38_1 = "Đừng có đùa tôi đấy chứ. Không phải ai cũng là một con rắn bán bất tử như cô."
L37_1.m_Talk_VTN = L38_1
L38_1 = "别搞笑了。你以为我们像你一样是能活千年万年的蛇妖吗？"
L37_1.m_Talk_SCN = L38_1
L38_1 = "Das soll doch wohl ein Scherz sein, oder? Im Gegensatz zu einer Riesenschlange wie dir, leben wir leider nicht Tausende von Jahren!"
L37_1.m_Talk_DEU = L38_1
L38_1 = "Tu te fous de qui, là ? Tout le monde n'est pas un serpent immortel comme toi, je te signale !"
L37_1.m_Talk_FRA = L38_1
L38_1 = {}
L39_1 = "FOOLSDAY_PART2_NODE1_EPILOGUE@38#Talk"
L38_1.m_CutScenKey_Talk = L39_1
L39_1 = 38
L38_1.m_CutScenProcessKey = L39_1
L38_1.m_CutScenID = 2700117
L38_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L38_1.m_bWaitClick = true
L38_1.m_fWaitTime = 0
L38_1.m_Face = "UNIT_HATE"
L38_1.m_CharStrID = "OROCHI_JAPAN_NULL_FOOLSDAY"
L38_1.m_Pos = "C"
L38_1.m_Crash = 30
L39_1 = "뭣이? 이무기…?! 날 그런 저급한 존재와 비교하다니…"
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "何？　大蛇……！？　我をあんな下等な存在と比べるとは……"
L38_1.m_Talk_JPN = L39_1
L39_1 = "Serpent, you say? How dare you compare me with such a lowly being?"
L38_1.m_Talk_ENG = L39_1
L39_1 = "什麼？蟒蛇…？！竟然拿那種低賤的東西來跟我比較…"
L38_1.m_Talk_TWN = L39_1
L39_1 = "งูเหรอ? กล้าดียังไงมาเทียบข้าเป็นสิ่งมีชีวิตชั้นต่ำนั่น?"
L38_1.m_Talk_THA = L39_1
L39_1 = "Rắn ư? Sao ngươi dám so sánh ta với con vật thấp kém như vậy?"
L38_1.m_Talk_VTN = L39_1
L39_1 = "蛇……蛇妖？！你居然敢把我和蛇妖那种东西混为一谈！？"
L38_1.m_Talk_SCN = L39_1
L39_1 = "Wie bitte? Riesenschlange? Wie kannst du es wagen, mich mit einem so primitiven Wesen zu vergleichen?"
L38_1.m_Talk_DEU = L39_1
L39_1 = "Un serpent ? Comment oses-tu me comparer avec une créature aussi vulgaire ?"
L38_1.m_Talk_FRA = L39_1
L39_1 = {}
