L40_1.m_Pos = L41_1
L41_1 = {}
L42_1 = "FOOLSDAY_PART2_NODE1_EPILOGUE@41#Talk"
L41_1.m_CutScenKey_Talk = L42_1
L42_1 = 41
L41_1.m_CutScenProcessKey = L42_1
L41_1.m_CutScenID = 2700117
L41_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L41_1.m_bWaitClick = true
L41_1.m_fWaitTime = 0
L41_1.m_Face = "UNIT_IDLE"
L41_1.m_CharStrID = "KNIGHT_REPLACER_UNIT_FOOLSDAY"
L42_1 = "R_M_I"
L41_1.m_Pos = L42_1
L42_1 = "그런데 오로치, 넌 아까부터 뭘 마시고 있는 거야? 좀전까지 음식에 독이 들었을 지 모른다며 온갖 호들갑을 떨더니만."
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "てかオロチ、てめえさっきから何飲んでんだ？　ちょっと前までは食べ物に毒が入ってるかもしれないって騒いでたくせに。"
L41_1.m_Talk_JPN = L42_1
L42_1 = "Orochi, what is it that you’re drinking? You’re the one who went paranoid about the food being poisoned."
L41_1.m_Talk_ENG = L42_1
L42_1 = "大蛇，你是在喝什麼？你剛不是還在那邊說什麼食物可能會有毒嗎？　"
L41_1.m_Talk_TWN = L42_1
L42_1 = "โอโรจิ ดื่มอะไรของเธออยู่น่ะ? เธอเป็นพวกนอยๆ ว่าจะมียาพิษในอาหารไม่ใช่เหรอ?"
L41_1.m_Talk_THA = L42_1
L42_1 = "Orochi, cô đang uống gì đấy? Không phải cô hoang tưởng thức ăn có độc sao?"
L41_1.m_Talk_VTN = L42_1
L42_1 = "喂，大蛇，你在喝什么呢？刚才不是还咋咋呼呼地说食物可能有毒吗。"
L41_1.m_Talk_SCN = L42_1
L42_1 = "Orochi, was trinkst du da gerade eigentlich? Du bist doch diejenige, die so paranoid war, dass jemand unser Essen vergiften könnte."
L41_1.m_Talk_DEU = L42_1
L42_1 = "Au fait Orochi, qu'est-ce que tu bois depuis tout à l'heure ? C'est pas toi qui était parano sur ces histoires d'empoisonnement ? "
L41_1.m_Talk_FRA = L42_1
L42_1 = {}
L43_1 = "FOOLSDAY_PART2_NODE1_EPILOGUE@42#Talk"
L42_1.m_CutScenKey_Talk = L43_1
L43_1 = 42
L42_1.m_CutScenProcessKey = L43_1
L42_1.m_CutScenID = 2700117
L42_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L42_1.m_bWaitClick = true
L42_1.m_fWaitTime = 0
L42_1.m_CharStrID = "OROCHI_JAPAN_NULL_FOOLSDAY"
L43_1 = "L"
L42_1.m_Pos = L43_1
L43_1 = "버블티라는 것이다. 양서류의 알 같은 것이 잔뜩 들어있길래 주문했다만, 의외로 쫄깃한 떡 맛이 나더구나."
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "タピオカティーというものだ。両生類の卵のようなものがぎっしり入っているから頼んでみたのだが、予想とは違ってモッチリとした餅の味だな。"
L42_1.m_Talk_JPN = L43_1
L43_1 = "It’s called Bubble Tea. I ordered it because of its seemingly contained amphibian eggs, but they turned out to be a sort of chewy rice cake."
L42_1.m_Talk_ENG = L43_1
L43_1 = "說是珍珠奶茶，我看裡面好像有很多兩棲類的蛋才點的，結果口感反而是像年糕一樣QQ的。"
L42_1.m_Talk_TWN = L43_1
L43_1 = "มันเรียกว่าชานมไข่มุก ข้าสั่งมาเพราะดูเหมือนมีไข่กบในนั้นน่ะ แต่กลายเป็นว่าเหมือนเค้กข้าวหนึบๆ มากกว่า"
L42_1.m_Talk_THA = L43_1
L43_1 = "Nó tên là Trà Sữa Trân Châu. Ta đã gọi nó vì tưởng nó có trứng lưỡng cư, nhưng hóa ra chúng chỉ là bánh gạo dai thôi."
L42_1.m_Talk_VTN = L43_1
L43_1 = "呼呼，这是珍珠奶茶。我是因为里面有很多两栖动物的卵才点的，没想到嚼起来会像年糕那样劲道。"
L42_1.m_Talk_SCN = L43_1
L43_1 = "Es heißt Bubble Tea. Ich habe es bestellt, weil es viele Amphibieneier zu enthalten schien, aber überraschenderweise schmeckt es nach zähen Reiskuchen."
L42_1.m_Talk_DEU = L43_1
L43_1 = "Ça s'appelle du bubble tea. Je croyais que ça contenait des œufs d'amphibiens mais apparemment ce sont juste des minuscules gâteaux de riz. C'est un peu décevant ? "
L42_1.m_Talk_FRA = L43_1
L43_1 = {}
L44_1 = "FOOLSDAY_PART2_NODE1_EPILOGUE@43#Talk"
L43_1.m_CutScenKey_Talk = L44_1
L44_1 = 43
L43_1.m_CutScenProcessKey = L44_1
L43_1.m_CutScenID = 2700117
L43_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L43_1.m_bWaitClick = true
L43_1.m_fWaitTime = 0
L44_1 = "UNIT_LAUGH"
L43_1.m_Face = L44_1
L43_1.m_CharStrID = "OROCHI_JAPAN_NULL_FOOLSDAY"
L44_1 = "L"
L43_1.m_Pos = L44_1
L44_1 = "네놈도 특별히 한 입 줄까?"
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "特別に貴様にも一口やろうか？"
L43_1.m_Talk_JPN = L44_1
L44_1 = "I shall allow you to take a sip, if you wish."
L43_1.m_Talk_ENG = L44_1
L44_1 = "我特地允許你們喝一口看看，要嗎？"
L43_1.m_Talk_TWN = L44_1
L44_1 = "ถ้าเจ้าอยากลองสักอึกข้าก็ยินดีนะ"
L43_1.m_Talk_THA = L44_1
L44_1 = "Ta cho phép ngươi uống thử đấy, nếu muốn."
L43_1.m_Talk_VTN = L44_1
L44_1 = "你要喝一口吗？"
L43_1.m_Talk_SCN = L44_1
L44_1 = "Ich werde dir einen Schluck genehmigen, falls du es auch mal probieren möchtest."
L43_1.m_Talk_DEU = L44_1
L44_1 = "Je t'autorise à prendre une gorgée, si tu le souhaites."
L43_1.m_Talk_FRA = L44_1
L44_1 = {}
L45_1 = "FOOLSDAY_PART2_NODE1_EPILOGUE@44#Talk"
L44_1.m_CutScenKey_Talk = L45_1
L45_1 = 44
L44_1.m_CutScenProcessKey = L45_1
L44_1.m_CutScenID = 2700117
L44_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L44_1.m_bWaitClick = true
L44_1.m_fWaitTime = 0
L44_1.m_Face = "UNIT_DESPAIR"
L44_1.m_CharStrID = "KNIGHT_REPLACER_UNIT_FOOLSDAY"
L45_1 = "R"
L44_1.m_Pos = L45_1
L45_1 = "으윽, 누가 뱀여자 아니랄까봐. 그딴 표현을 써서 식욕이 뚝 떨어졌잖아."
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "げっ、さすがヘビ女。そういうこと言うと食欲がなくなるだろ。"
L44_1.m_Talk_JPN = L45_1
L45_1 = "Ugh, stop speaking, you serpent. Your word made me lose my appetite."
L44_1.m_Talk_ENG = L45_1
L45_1 = "呃，怕人家不知道你是蛇女嗎？被你說成那樣誰還想喝？"
L44_1.m_Talk_TWN = L45_1
L45_1 = "อึก แค่พูดถึงงู... ฉันก็กินอะไรไม่ลงแล้ว"
L44_1.m_Talk_THA = L45_1
L45_1 = "Haiz, nói về rắn...Cô ấy làm tôi hết muốn ăn rồi."
L44_1.m_Talk_VTN = L45_1
L45_1 = "呃，生怕别人不知道你是蛇女似的。你这么一说，瞬间就没食欲了。"
L44_1.m_Talk_SCN = L45_1
L45_1 = "Urgh, so was kann auch nur von einer Schlangenfrau wie dir kommen. Wegen dir habe ich meinen Appetit verloren."
L44_1.m_Talk_DEU = L45_1
L45_1 = "Beurk, c'est pas un serpent pour rien. Super, j'ai perdu l'appétit maintenant."
L44_1.m_Talk_FRA = L45_1
L45_1 = {}
L46_1 = "FOOLSDAY_PART2_NODE1_EPILOGUE@45#Talk"
L45_1.m_CutScenKey_Talk = L46_1
L46_1 = 45
L45_1.m_CutScenProcessKey = L46_1
L45_1.m_CutScenID = 2700117
L45_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L45_1.m_bWaitClick = true
L45_1.m_fWaitTime = 0
L45_1.m_Face = "UNIT_IDLE"
L45_1.m_CharStrID = "OROCHI_JAPAN_NULL_FOOLSDAY"
L46_1 = "L"
L45_1.m_Pos = L46_1
L46_1 = "쫄깃한 떡… 이라는 표현 말이냐?"
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "モッチリとした餅……という表現のことか？"
L45_1.m_Talk_JPN = L46_1
L46_1 = "The chewy rice cake, you mean...?"
L45_1.m_Talk_ENG = L46_1
L46_1 = "像年糕一樣QQ的…不行嗎？"
L45_1.m_Talk_TWN = L46_1
L46_1 = "เจ้าหมายถึงเค้กข้าวหนึบๆ นะเหรอ...?"
L45_1.m_Talk_THA = L46_1
L46_1 = "Ý ngươi là bánh gạo dai sao...?"
L45_1.m_Talk_VTN = L46_1
L46_1 = "呼呼，什么？是年糕……让你没食欲了？"
L45_1.m_Talk_SCN = L46_1
L46_1 = "Weil ich die zähen Reiskuchen erwähnt habe ...?"
L45_1.m_Talk_DEU = L46_1
L46_1 = "Pourquoi donc ? Tu n'aimes pas les gâteaux de riz ?"
L45_1.m_Talk_FRA = L46_1
