L47_1.m_CutScenKey_Talk = L48_1
L48_1 = 47
L47_1.m_CutScenProcessKey = L48_1
L47_1.m_CutScenID = 2700117
L47_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L47_1.m_bWaitClick = true
L47_1.m_fWaitTime = 0
L47_1.m_Face = "UNIT_SERIOUS"
L47_1.m_CharStrID = "KNIGHT_REPLACER_UNIT_FOOLSDAY"
L48_1 = "R"
L47_1.m_Pos = L48_1
L48_1 = "어이, 기계광. 혼자 어딜 가는 거야?"
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L48_1 = "おい、機械オタク。一人でどこ行くんだ？"
L47_1.m_Talk_JPN = L48_1
L48_1 = "Hey, machine freak! Where do you think you’re going?"
L47_1.m_Talk_ENG = L48_1
L48_1 = "喂，機械狂你是要去哪裡？"
L47_1.m_Talk_TWN = L48_1
L48_1 = "เฮ้ย ยัยบ้าเครื่องจักร! จะไปไหนของเธอน่ะ?"
L47_1.m_Talk_THA = L48_1
L48_1 = "Này, ả mê máy móc chết tiệt! Cô nghĩ mình đang đi đâu cơ chứ?"
L47_1.m_Talk_VTN = L48_1
L48_1 = "喂，机械迷，你一个人要去哪里？"
L47_1.m_Talk_SCN = L48_1
L48_1 = "Hey, Maschinenfreak! Wohin gehst du denn so ganz alleine?"
L47_1.m_Talk_DEU = L48_1
L48_1 = "Hé, la mécano ! Où est-ce que tu vas comme ça ?"
L47_1.m_Talk_FRA = L48_1
