L50_1 = "FOOLSDAY_PART2_NODE1_EPILOGUE@49#Talk"
L49_1.m_CutScenKey_Talk = L50_1
L50_1 = 49
L49_1.m_CutScenProcessKey = L50_1
L49_1.m_CutScenID = 2700117
L49_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L49_1.m_bWaitClick = true
L49_1.m_fWaitTime = 0
L49_1.m_CharStrID = "COLLECTOR_NPC_NULL_FOOLSDAY"
L49_1.m_Pos = "C"
L50_1 = "워프가 고장 났으니 쓸만한 정비소를 찾아야지. 이 망할 수갑도 풀 겸."
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "ワープが壊れたから適当な整備工場を探さないと。このウザい手錠も外さなきゃいけないし。"
L49_1.m_Talk_JPN = L50_1
L50_1 = "With the warp machine broken, I have to look for a workshop that I could use... Maybe take off these darn handcuffs while I’m at it."
L49_1.m_Talk_ENG = L50_1
L50_1 = "控制裝置壞了當然要找看看有沒有維修站，順便也把這個礙事的手銬解開。"
L49_1.m_Talk_TWN = L50_1
L50_1 = "ก็เครื่องวาร์ปพังแบบนี้ ฉันก็ต้องไปหาเวิร์กช็อปที่ให้ใช้ได้นะสิ... บางทีอาจได้เอาไอ้กุญแจมือบ้านี่ออกด้วย"
L49_1.m_Talk_THA = L50_1
L50_1 = "Vì máy dịch chuyển bị hỏng, tôi phải tìm xưởng để sửa ...Có lẽ phải tháo mấy chiếc còng tay chết tiệt này khi tôi làm việc."
L49_1.m_Talk_VTN = L50_1
L50_1 = "传送装置坏了，我得找个维修站修理，顺便解开这个破手铐。"
L49_1.m_Talk_SCN = L50_1
L50_1 = "Da die Warp-Maschine kaputt ist, muss ich nach einer ordentlichen Werkstatt suchen ... Vielleicht könnte ich dort auch diese verdammten Handschellen loswerden."
L49_1.m_Talk_DEU = L50_1
L50_1 = "Puisque le téléporteur est en panne, il faut que je trouve un atelier pour effectuer les réparations. Et tant que j'y suis, pour enlever ces foutues menottes."
L49_1.m_Talk_FRA = L50_1
L50_1 = {}
