L50_1.m_CharStrID = "KNIGHT_REPLACER_UNIT_FOOLSDAY"
L50_1.m_Pos = "C"
L51_1 = "내가 그 수갑 부숴줄까?"
L50_1.m_Talk_KOREA = L51_1
L50_1.m_fTalkTime = 0.03
L51_1 = "その手錠、アタシが壊してやろうか？"
L50_1.m_Talk_JPN = L51_1
L51_1 = "You want me to break them for you?"
L50_1.m_Talk_ENG = L51_1
L51_1 = "還是我直接幫你把手銬弄壞？"
L50_1.m_Talk_TWN = L51_1
L51_1 = "ฉันเอาออกให้มั้ยล่ะ?"
L50_1.m_Talk_THA = L51_1
L51_1 = "Cô có muốn tôi phá nó giúp không?"
L50_1.m_Talk_VTN = L51_1
L51_1 = "简单啊，要不要我帮你把那手铐砸烂？"
L50_1.m_Talk_SCN = L51_1
L51_1 = "Soll ich die Handschellen für dich aufbrechen?"
L50_1.m_Talk_DEU = L51_1
L51_1 = "Tu veux que je les brise pour toi ?"
