L1_1.m_Pos = "C"
L2_1 = "됐어. 힘조절 안 되는 녀석한테 내 손목을 맡기고 싶지 않아."
L1_1.m_Talk_KOREA = L2_1
L1_1.m_fTalkTime = 0.03
L2_1 = "いいよ。力加減もできないやつに手首を任せたくはない。"
L1_1.m_Talk_JPN = L2_1
L2_1 = "Nope. I don’t feel comfortable trusting some lunatic like you who can’t control her own powers."
L1_1.m_Talk_ENG = L2_1
L2_1 = "不必，我不想把我的手腕交給一個不懂得拿捏力道的人。"
L1_1.m_Talk_TWN = L2_1
L2_1 = "ไม่ละ จะเชื่อใจคนบ้าที่ควบคุมพลังไม่ได้อย่างเธอมันก็ไม่ค่อยสบายใจ"
L1_1.m_Talk_THA = L2_1
L2_1 = "Không. Tôi cảm thấy không thoải mái khi tin một kẻ điên như cô có thể kiểm soát nổi sức mạnh của chính mình."
L1_1.m_Talk_VTN = L2_1
L2_1 = "算了。我可不想把自己的手腕交给不会控制力道的家伙。"
L1_1.m_Talk_SCN = L2_1
L2_1 = "Passt schon. Ich fühle mich nicht wohl dabei, mein Handgelenk jemandem anzuvertrauen, der seine Kraft nicht unter Kontrolle hat."
L1_1.m_Talk_DEU = L2_1
L2_1 = "Non. Tu ne sais même pas contrôler tes propres pouvoirs, aucune chance que je fasse confiance à une tarée comme toi."
L1_1.m_Talk_FRA = L2_1
