L4_1 = "FOOLSDAY_PART2_NODE1_EPILOGUE@53#Talk"
L3_1.m_CutScenKey_Talk = L4_1
L4_1 = 53
L3_1.m_CutScenProcessKey = L4_1
L3_1.m_CutScenID = 2700117
L3_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L3_1.m_bWaitClick = true
L3_1.m_fWaitTime = 0
L3_1.m_CharStrID = "KNIGHT_REPLACER_UNIT_FOOLSDAY"
L3_1.m_Pos = "C"
L4_1 = "저 녀석… 정말로 혼자 갔네."
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "あいつ……マジで一人で行きやがった。"
L3_1.m_Talk_JPN = L4_1
L4_1 = "That dummy... She really did go by herself."
L3_1.m_Talk_ENG = L4_1
L4_1 = "她…還真的給我自己去。"
L3_1.m_Talk_TWN = L4_1
L4_1 = "ยัยโง่นั่น... ไปจริงๆ ด้วยแฮะ"
L3_1.m_Talk_THA = L4_1
L4_1 = "Chết tiệt... Cô ta thực sự đã đi một mình."
L3_1.m_Talk_VTN = L4_1
L4_1 = "她……真的一个人走了。"
L3_1.m_Talk_SCN = L4_1
L4_1 = "Unglaublich ... Sie ist wirklich ganz alleine losgezogen."
L3_1.m_Talk_DEU = L4_1
L4_1 = "Cette espèce de... elle est vraiment partie toute seule."
L3_1.m_Talk_FRA = L4_1
L4_1 = {}
L5_1 = "FOOLSDAY_PART2_NODE1_EPILOGUE@54#Talk"
L4_1.m_CutScenKey_Talk = L5_1
L5_1 = 54
L4_1.m_CutScenProcessKey = L5_1
L4_1.m_CutScenID = 2700117
L4_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L4_1.m_bWaitClick = true
L4_1.m_fWaitTime = 0
L5_1 = "UNIT_LAUGH"
L4_1.m_Face = L5_1
L4_1.m_CharStrID = "OROCHI_JAPAN_NULL_FOOLSDAY"
L4_1.m_Pos = "C"
L5_1 = "잘 됐다. 어차피 기계는 알아서 고쳐질 테니 굳이 몰려다닐 필요는 없지."
L4_1.m_Talk_KOREA = L5_1
L4_1.m_fTalkTime = 0.03
L5_1 = "ちょうどいい。どうせ機械はやつが直すはずだから、群れる必要はあるまい。"
L4_1.m_Talk_JPN = L5_1
L5_1 = "Even better. The machine will be fixed in time. There’s no point in moving as a group."
L4_1.m_Talk_ENG = L5_1
L5_1 = "有什麼關係？反正她自己會把東西修好，沒必要非得團體行動吧？"
L4_1.m_Talk_TWN = L5_1
L5_1 = "ยิ่งดีเลยสิ จะได้ซ่อมเครื่องจักรนั่นมันเวลา ไปกันเป็นกลุ่มก้อนก็หามีประโยชน์อันใดไม่"
L4_1.m_Talk_THA = L5_1
L5_1 = "Càng tốt. Cỗ máy sẽ được sửa chữa kịp thời. Không cần đi đâu cũng có nhau đâu."
L4_1.m_Talk_VTN = L5_1
L5_1 = "走了正好。反正修机器是她的活儿，整天跟她在一起也太没意思了。"
L4_1.m_Talk_SCN = L5_1
L5_1 = "Nun gut. Da sie sich sowieso allein um die Reparatur der Maschine kümmern will, gibt es keinen Grund gemeinsam rumzuhängen."
L4_1.m_Talk_DEU = L5_1
L5_1 = "C'est pour le mieux. Les machines se réparent seules avec le temps, inutile de concentrer tous nos efforts dessus."
L4_1.m_Talk_FRA = L5_1
L5_1 = {}
L6_1 = "FOOLSDAY_PART2_NODE1_EPILOGUE@55#Talk"
L5_1.m_CutScenKey_Talk = L6_1
L6_1 = 55
L5_1.m_CutScenProcessKey = L6_1
L5_1.m_CutScenID = 2700117
L5_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L5_1.m_bWaitClick = true
L5_1.m_fWaitTime = 0
L5_1.m_CharStrID = "OROCHI_JAPAN_NULL_FOOLSDAY"
L5_1.m_Pos = "C"
L6_1 = "그나저나 저쪽에 오락실이라는 곳이 있던데, 무얼 하는지 구경이나 해보겠느냐?"
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "それよりあそこにゲームセンターというところがあるのだが、何をするところなのか見てみようではないか。"
L5_1.m_Talk_JPN = L6_1
L6_1 = "Anyways, I saw an interesting place by the name of \"arcade\" over there. Would you like to see what it’s about?"
L5_1.m_Talk_ENG = L6_1
L6_1 = "不過那邊好像有個叫遊戲場的地方，去看看那裡是在幹嘛的吧？"
L5_1.m_Talk_TWN = L6_1
L6_1 = "ว่าแต่ ข้าเห็นที่ที่น่าสนใจอยู่ตรงนั้น ชื่อ “อาร์เคด” เจ้าอยากไปดูหรือไม่ว่ามันคืออะไร?"
L5_1.m_Talk_THA = L6_1
L6_1 = "À, ta thấy nơi thú vị tên là \"trò chơi điện tử\" ở đó. Người muốn đi xem không?"
L5_1.m_Talk_VTN = L6_1
L6_1 = "总之，那边有个叫“游戏厅”的地方，我想你一定感兴趣的吧？"
L5_1.m_Talk_SCN = L6_1
L6_1 = "Übrigens, dort drüben gibt es eine Spielhalle, wollen wir sie uns einmal anschauen?"
L5_1.m_Talk_DEU = L6_1
L6_1 = "Au fait... c'est quoi ce panneau, là-bas ? « Salle d'arcade » ? Et si on allait voir ce que c'est ?"
L5_1.m_Talk_FRA = L6_1
L6_1 = {}
L7_1 = "FOOLSDAY_PART2_NODE1_EPILOGUE@56#Talk"
L6_1.m_CutScenKey_Talk = L7_1
L7_1 = 56
L6_1.m_CutScenProcessKey = L7_1
L6_1.m_CutScenID = 2700117
L6_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L6_1.m_bWaitClick = true
L6_1.m_fWaitTime = 0
L6_1.m_Face = "UNIT_DESPAIR"
L6_1.m_CharStrID = "KNIGHT_REPLACER_UNIT_FOOLSDAY"
L6_1.m_Pos = "C"
L7_1 = "아깐 함부로 움직이지 말자더니 금방 느슨해졌구만."
L6_1.m_Talk_KOREA = L7_1
L6_1.m_fTalkTime = 0.03
L7_1 = "さっきはむやみに動くなと言ったくせに、もう気を緩めるんだな。"
L6_1.m_Talk_JPN = L7_1
L7_1 = "You scolded us to not go anywhere... But looks like you switched sides."
L6_1.m_Talk_ENG = L7_1
L7_1 = "剛剛是誰說不要輕易移動的，才過多久而已就忘啦？"
L6_1.m_Talk_TWN = L7_1
L7_1 = "เมื่อกี้เธอยังด่าพวกเราอยู่เลยว่าไม่ให้ไปไหน... แต่ท่าทางจะเปลี่ยนใจแล้วนะ"
L6_1.m_Talk_THA = L7_1
L7_1 = "Cô đã mắng chúng tôi không được đi đâu...Nhưng giờ thì chính cô lại đổi phe rồi."
L6_1.m_Talk_VTN = L7_1
L7_1 = "嘁……刚才是谁说别让我乱走啊，心口不一的家伙？"
L6_1.m_Talk_SCN = L7_1
L7_1 = "Vorhin hast du noch gemeint, dass wir nicht unnötig umherlaufen sollten ... Du scheinst deine Meinung ja recht schnell zu ändern."
L6_1.m_Talk_DEU = L7_1
L7_1 = "C'est pas toi qui nous disais d'être vigilantes, tout à l'heure ? Faudrait savoir."
L6_1.m_Talk_FRA = L7_1
L7_1 = {}
L8_1 = "FOOLSDAY_PART2_NODE1_EPILOGUE@57#Talk"
L7_1.m_CutScenKey_Talk = L8_1
L8_1 = 57
L7_1.m_CutScenProcessKey = L8_1
L7_1.m_CutScenID = 2700117
L7_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L7_1.m_bWaitClick = true
L7_1.m_fWaitTime = 0
L7_1.m_CharStrID = "OROCHI_JAPAN_NULL_FOOLSDAY"
L7_1.m_Pos = "C"
L8_1 = "이쪽 세계의 인간들은 전부 생긴 게 몽실몽실해서 딱히 위협이 될 것 같진 않더구나."
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "この世界の人間はみなふっくらしていて、別に脅威的ではなさそうだった。"
L7_1.m_Talk_JPN = L8_1
L8_1 = "The humans in this world look harmless. They’re all so plump."
L7_1.m_Talk_ENG = L8_1
L8_1 = "那是因為這個世界的人類全都長得圓圓的，感覺沒什麼威脅性。"
L7_1.m_Talk_TWN = L8_1
L8_1 = "ก็มนุษย์ในดินแดนนี้ดูไม่มีอันตรายอันใดนี่ ออกจะจ้ำม่ำซ้ำบอบบาง"
L7_1.m_Talk_THA = L8_1
L8_1 = "Con người ở chỗ này trông có vẻ vô hại. Chúng đều rất bụ bẫm và yếu ớt."
L7_1.m_Talk_VTN = L8_1
L8_1 = "那是因为这个世界的人长得都软乎乎的，好像没什么威胁。"
L7_1.m_Talk_SCN = L8_1
L8_1 = "Die Menschen in dieser Welt sehen alle recht harmlos aus, also scheinen sie keine besondere Bedrohung darzustellen."
L7_1.m_Talk_DEU = L8_1
L8_1 = "Les humains de ce monde semblent inoffensifs. Ils sont tous doux et moelleux."
L7_1.m_Talk_FRA = L8_1
L8_1 = {}
L9_1 = "FOOLSDAY_PART2_NODE1_EPILOGUE@58#Talk"
L8_1.m_CutScenKey_Talk = L9_1
L9_1 = 58
L8_1.m_CutScenProcessKey = L9_1
L8_1.m_CutScenID = 2700117
L8_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L8_1.m_bWaitClick = true
L8_1.m_fWaitTime = 0
L8_1.m_CharStrID = "OROCHI_JAPAN_NULL_FOOLSDAY"
L8_1.m_Pos = "C"
L9_1 = "게다가…"
L8_1.m_Talk_KOREA = L9_1
L8_1.m_fTalkTime = 0.03
L9_1 = "それに……"
L8_1.m_Talk_JPN = L9_1
L9_1 = "Besides..."
L8_1.m_Talk_ENG = L9_1
L9_1 = "而且…"
L8_1.m_Talk_TWN = L9_1
L9_1 = "แล้วก็..."
L8_1.m_Talk_THA = L9_1
L9_1 = "Bên cạnh đó..."
L8_1.m_Talk_VTN = L9_1
L9_1 = "而且……"
L8_1.m_Talk_SCN = L9_1
L9_1 = "Außerdem ..."
L8_1.m_Talk_DEU = L9_1
L9_1 = "D'ailleurs..."
L8_1.m_Talk_FRA = L9_1
L9_1 = {}
L10_1 = "FOOLSDAY_PART2_NODE1_EPILOGUE@59#Talk"
L9_1.m_CutScenKey_Talk = L10_1
L10_1 = 59
L9_1.m_CutScenProcessKey = L10_1
L9_1.m_CutScenID = 2700117
L9_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L9_1.m_bWaitClick = true
L9_1.m_fWaitTime = 0
L9_1.m_Face = "UNIT_PRIDE"
L9_1.m_CharStrID = "OROCHI_JAPAN_NULL_FOOLSDAY"
L9_1.m_Pos = "C"
L10_1 = "이 세계가 더 마음에 들게 된다면, 굳이 돌아가지 않고 우리가 이곳을 취하면 되지 않겠느냐?"
L9_1.m_Talk_KOREA = L10_1
L9_1.m_fTalkTime = 0.03
L10_1 = "この世界が気に入ったなら、無理に帰らずに我々がここを占有してしまえばよかろう。"
L9_1.m_Talk_JPN = L10_1
L10_1 = "If we come to favor this world, why not conquer it instead of going back?"
L9_1.m_Talk_ENG = L10_1
L10_1 = "要是喜歡上這個世界的話，那也不是非回去不可，只需要把這個地方拿下不就好？"
L9_1.m_Talk_TWN = L10_1
L10_1 = "หากพวกเราเกิดชอบดินแดนนี้ขึ้นมา ทำไมไม่ยึดครองมันไว้แทนที่จะกลับไปกันเล่า?"
L9_1.m_Talk_THA = L10_1
L10_1 = "Nếu chúng ta thích nơi này, sao không chinh phục nó thay vì quay trở về chứ?"
L9_1.m_Talk_VTN = L10_1
L10_1 = "如果这里还不错的话，比起回到原来的地方，直接把这个世界占了岂不是更好？"
L9_1.m_Talk_SCN = L10_1
L10_1 = "Wenn uns diese Welt so gut gefällt, warum erobern wir sie nicht einfach, anstatt in unsere zurückzukehren?"
L9_1.m_Talk_DEU = L10_1
L10_1 = "Si ce monde est si agréable, pourquoi ne pas rester ici et le conquérir ?"
L9_1.m_Talk_FRA = L10_1
L10_1 = {}
