L12_1 = "FOOLSDAY_PART2_NODE1_EPILOGUE@61#Talk"
L11_1.m_CutScenKey_Talk = L12_1
L12_1 = 61
L11_1.m_CutScenProcessKey = L12_1
L11_1.m_CutScenID = 2700117
L11_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L11_1.m_bWaitClick = true
L11_1.m_fWaitTime = 0
L11_1.m_Face = "UNIT_PRIDE"
L11_1.m_CharStrID = "KNIGHT_REPLACER_UNIT_FOOLSDAY"
L11_1.m_Pos = "C"
L12_1 = "큭큭, 벌써 여길 접수할 생각부터 하다니. 역시 현상수배 넘버 원은 수준이 다르구만."
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "ククッ、すでにここをいただくつもりでいるとは。やっぱ指名手配ナンバー1はレベルが違うな。"
L11_1.m_Talk_JPN = L12_1
L12_1 = "Hah hah, we just got here and you’re already thinking of taking over this world? I guess that’s what makes you most wanted"
L11_1.m_Talk_ENG = L12_1
L12_1 = "呃，竟然已經想到要拿下這裡，頭號通緝犯的想法果然不一樣。"
L11_1.m_Talk_TWN = L12_1
L12_1 = "ฮี่ฮี่ฮี่ เราเพิ่งมาถึงแต่เธอไปทางจะยึดครองอะไรๆ ซะแล้วเหรอ? แบบนี้สินะเขาเลยหมายหัวเธอกันที่สุด"
L11_1.m_Talk_THA = L12_1
L12_1 = "Kehehe, chúng ta vừa mới tới đây mà cô đã nghĩ đến việc chiếm đoạt nó sao? Chắc đó lý do cô bị truy nã cao nhất"
L11_1.m_Talk_VTN = L12_1
L12_1 = "咳咳，你居然这么快就想到这一层了，头号悬赏通缉犯果然就是不一样。"
L11_1.m_Talk_SCN = L12_1
L12_1 = "Hehehe, wir sind gerade erst hier angekommen und du denkst schon über eine Eroberung nach? Die Spitzenposition auf der Fahndungsliste der meistgesuchten Kriminellen hast du dir wirklich verdient."
L11_1.m_Talk_DEU = L12_1
L12_1 = "Hé hé, on débarque à peine et tu as déjà la folie des grandeurs ? Pas étonnant qu'il y ait une prime sur ta tête."
L11_1.m_Talk_FRA = L12_1
L12_1 = {}
L13_1 = "FOOLSDAY_PART2_NODE1_EPILOGUE@62#Talk"
L12_1.m_CutScenKey_Talk = L13_1
L13_1 = 62
L12_1.m_CutScenProcessKey = L13_1
L12_1.m_CutScenID = 2700117
L12_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L12_1.m_bWaitClick = true
L12_1.m_fWaitTime = 0
L12_1.m_CharStrID = "KNIGHT_REPLACER_UNIT_FOOLSDAY"
L12_1.m_Pos = "C"
L13_1 = "그래. 덕분에 다시 떠올랐어. 우린 극악무도한 우주대악당이라는 걸."
L12_1.m_Talk_KOREA = L13_1
L12_1.m_fTalkTime = 0.03
L13_1 = "ああ。おかげで思い出したよ。アタシたちは極悪非道な宇宙大悪党だということをね。"
L12_1.m_Talk_JPN = L13_1
L13_1 = "Yes. You reminded us that we are the Atrocious Space Supervillains."
L12_1.m_Talk_ENG = L13_1
L13_1 = "沒錯，拜你所賜我又再次想起來，我們可是十惡不赦的宇宙大反派欸！"
L12_1.m_Talk_TWN = L13_1
L13_1 = "นั่นสินะ เธอทำให้นึกขึ้นได้เลยว่าเราคือวายร้ายอวกาศใจโหด"
L12_1.m_Talk_THA = L13_1
L13_1 = "Ừ. Cô nhắc tôi mới nhớ rằng chúng ta là Siêu Phản Diện Không Gian Hung Tàn đấy."
L12_1.m_Talk_VTN = L13_1
L13_1 = "托你的福，我才想起来我们可是穷凶极恶的宇宙大恶棍呢。"
L12_1.m_Talk_SCN = L13_1
L13_1 = "Aber du hast schon recht. Dank dir ist mir gerade wieder eingefallen, dass wir ja nicht umsonst die grausamen Weltraumschurken genannt werden."
L12_1.m_Talk_DEU = L13_1
L13_1 = "Merci pour la piqûre de rappel. On est des criminelles recherchées, j'ai failli oublier."
L12_1.m_Talk_FRA = L13_1
L13_1 = {}
L14_1 = "FOOLSDAY_PART2_NODE1_EPILOGUE@63#Talk"
L13_1.m_CutScenKey_Talk = L14_1
L14_1 = 63
L13_1.m_CutScenProcessKey = L14_1
L13_1.m_CutScenID = 2700117
L13_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L13_1.m_bWaitClick = true
L13_1.m_fWaitTime = 0
L14_1 = "FX_CUTSCEN_NOISE_RUSTLE_04"
L13_1.m_StartFXSoundName = L14_1
L13_1.m_CharStrID = "KNIGHT_REPLACER_UNIT_FOOLSDAY"
L13_1.m_Pos = "C"
L13_1.m_Crash = 20
L14_1 = "까짓 거 즐겨주지! 이세계 정복!"
L13_1.m_Talk_KOREA = L14_1
L13_1.m_fTalkTime = 0.03
L14_1 = "楽しんでやろうじゃないか！　異世界征服！"
L13_1.m_Talk_JPN = L14_1
L14_1 = "All right, let’s do it! Conquerors of this world!"
L13_1.m_Talk_ENG = L14_1
L14_1 = "盡情享樂！征服世界！"
L13_1.m_Talk_TWN = L14_1
L14_1 = "เอาสิ ลุยกันเลย! เหล่าผู้พิชิตจักรวาล!"
L13_1.m_Talk_THA = L14_1
L14_1 = "Được rồi, làm thôi! Chinh phạt cái thế giới này nào!"
L13_1.m_Talk_VTN = L14_1
L14_1 = "好吧！去征服这个世界吧！就从这个游戏厅开始！"
L13_1.m_Talk_SCN = L14_1
L14_1 = "Also gut, lass es uns ein bisschen Spaß haben! Erobern wir diese Welt!"
L13_1.m_Talk_DEU = L14_1
L14_1 = "Ok, je suis avec toi ! Allons conquérir ce monde !"
L13_1.m_Talk_FRA = L14_1
