L20_1 = "FOOLSDAY_PART2_NODE1_EPILOGUE@69#Talk"
L19_1.m_CutScenKey_Talk = L20_1
L20_1 = 69
L19_1.m_CutScenProcessKey = L20_1
L19_1.m_CutScenID = 2700117
L19_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L19_1.m_bWaitClick = true
L19_1.m_fWaitTime = 0
L19_1.m_CharStrID = "OROCHI_JAPAN_NULL_FOOLSDAY"
L20_1 = "R"
L19_1.m_Pos = L20_1
L20_1 = "슬슬 포기하거라. 지금까지 헛돈만 날리고 있지 않느냐?"
L19_1.m_Talk_KOREA = L20_1
L19_1.m_fTalkTime = 0.03
L20_1 = "そろそろ諦めるがよい。金の無駄使いではないか。"
L19_1.m_Talk_JPN = L20_1
L20_1 = "It’s time you gave up. You are simply wasting money."
L19_1.m_Talk_ENG = L20_1
L20_1 = "你還是放棄吧，你這樣跟把錢扔水裡有什麼兩樣？"
L19_1.m_Talk_TWN = L20_1
L20_1 = "ถึงเวลาต้องยอมแพ้แล้ว เจ้ามีแต่เสียเงินไปเปล่าๆนะ"
L19_1.m_Talk_THA = L20_1
L20_1 = "Đã tới lúc phải từ bỏ rồi. Ngươi chỉ phí tiền thôi."
L19_1.m_Talk_VTN = L20_1
L20_1 = "还是放弃吧。你都浪费多少钱了？"
L19_1.m_Talk_SCN = L20_1
L20_1 = "Es ist langsam aber sicher Zeit, aufzugeben. Du hast bisher nur dein Geld verschwendet."
L19_1.m_Talk_DEU = L20_1
L20_1 = "Et si tu en restais là ? Plutôt que de gaspiller ton argent bêtement ?"
L19_1.m_Talk_FRA = L20_1
L20_1 = {}
L21_1 = "FOOLSDAY_PART2_NODE1_EPILOGUE@70#Talk"
L20_1.m_CutScenKey_Talk = L21_1
L21_1 = 70
L20_1.m_CutScenProcessKey = L21_1
L20_1.m_CutScenID = 2700117
L20_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L20_1.m_bWaitClick = true
L20_1.m_fWaitTime = 0
L20_1.m_Face = "UNIT_SERIOUS"
L21_1 = "FX_CUTSCEN_NOISE_RUSTLE_04"
L20_1.m_StartFXSoundName = L21_1
L21_1 = "KNIGHT_REPLACER_BACK_FOOLSDAY"
L20_1.m_CharStrID = L21_1
L21_1 = "L"
L20_1.m_Pos = L21_1
L20_1.m_Crash = 30
L21_1 = "시끄러! 난 내가 갖기로 한 건 무조건 갖는다!"
L20_1.m_Talk_KOREA = L21_1
L20_1.m_fTalkTime = 0.03
L21_1 = "うるさい！　アタシは欲しいものは絶対手に入れる！"
L20_1.m_Talk_JPN = L21_1
L21_1 = "Shut up! If I want something, I get it!"
L20_1.m_Talk_ENG = L21_1
L21_1 = "不用你管！只要是我想要的東西，我就一定要得到！"
L20_1.m_Talk_TWN = L21_1
L21_1 = "เงียบเลยนะ! ถ้าฉันอยากได้อะไรก็ต้องได้!"
L20_1.m_Talk_THA = L21_1
L21_1 = "Im đi! Nếu tôi muốn cái gì, tôi sẽ tự mình lấy nó!"
L20_1.m_Talk_VTN = L21_1
L21_1 = "你闭嘴！我想要的东西就没有得不到的！"
L20_1.m_Talk_SCN = L21_1
L21_1 = "Halt die Klappe! Wenn ich etwas will, dann kriege ich es auch!"
L20_1.m_Talk_DEU = L21_1
L21_1 = "La ferme ! J'obtiens tout ce que je veux, compris ?"
L20_1.m_Talk_FRA = L21_1
L21_1 = {}
L22_1 = "FOOLSDAY_PART2_NODE1_EPILOGUE@71#Talk"
L21_1.m_CutScenKey_Talk = L22_1
L22_1 = 71
L21_1.m_CutScenProcessKey = L22_1
L21_1.m_CutScenID = 2700117
L21_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L21_1.m_bWaitClick = true
L21_1.m_fWaitTime = 0
L21_1.m_CharStrID = "OROCHI_JAPAN_NULL_FOOLSDAY"
L22_1 = "R"
L21_1.m_Pos = L22_1
L22_1 = "그것 참 악당다운 대답이긴 하구나."
L21_1.m_Talk_KOREA = L22_1
L21_1.m_fTalkTime = 0.03
L22_1 = "非常に悪党らしい返事ではあるな。"
L21_1.m_Talk_JPN = L22_1
L22_1 = "That sounds like a greedy villain indeed."
L21_1.m_Talk_ENG = L22_1
L22_1 = "這倒是很像反派會說的話。"
L21_1.m_Talk_TWN = L22_1
L22_1 = "ฟังดูเป็นวายร้ายจอมละโมบโดยแท้"
L21_1.m_Talk_THA = L22_1
L22_1 = "Quả là ra dáng một kẻ phản diện tham lam."
L21_1.m_Talk_VTN = L22_1
L22_1 = "这个回答可真有恶棍的气势。"
L21_1.m_Talk_SCN = L22_1
L22_1 = "Du klingst echt wie eine gierige Schurkin."
L21_1.m_Talk_DEU = L22_1
L22_1 = "Quelle avidité... bien digne d'un méchant de films grand public."
L21_1.m_Talk_FRA = L22_1
L22_1 = {}
L23_1 = "FOOLSDAY_PART2_NODE1_EPILOGUE@72#Talk"
L22_1.m_CutScenKey_Talk = L23_1
L23_1 = 72
L22_1.m_CutScenProcessKey = L23_1
L22_1.m_CutScenID = 2700117
L22_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L22_1.m_bWaitClick = true
L22_1.m_fWaitTime = 0
L23_1 = "UNIT_LAUGH"
L22_1.m_Face = L23_1
L22_1.m_CharStrID = "OROCHI_JAPAN_NULL_FOOLSDAY"
L23_1 = "R"
L22_1.m_Pos = L23_1
L23_1 = "그 갖고 싶다는 게 고작 뽑기인형이라는 것만 제외하면 말이지."
L22_1.m_Talk_KOREA = L23_1
L22_1.m_fTalkTime = 0.03
L23_1 = "その欲しいものがたかがクレーンゲームのぬいぐるみだということを除くけば。"
L22_1.m_Talk_JPN = L23_1
L23_1 = "Disregarding the fact that what you want is a lousy plushie doll."
L22_1.m_Talk_ENG = L23_1
L23_1 = "雖然你想要的只是抓娃娃機裡的娃娃。"
L22_1.m_Talk_TWN = L23_1
L23_1 = "เว้นแต่ความจริงคือ ที่เจ้ากำลังต้องการนั้นเพียงตุ๊กตายัดนุ่นชั้นต่ำ"
L22_1.m_Talk_THA = L23_1
L23_1 = "Dù thực tế tất cả những gì ngươi muốn chỉ là một con búp bê nhồi bông xấu xí."
L22_1.m_Talk_VTN = L23_1
L23_1 = "不过，这个娃娃跟你的反派形象可不匹配。"
L22_1.m_Talk_SCN = L23_1
L23_1 = "Wenn man mal davon absieht, dass das, was du willst, nur eine lausige kleine Puppe ist."
L22_1.m_Talk_DEU = L23_1
L23_1 = "Tout ça pour une peluche minable... et moche, en plus."
L22_1.m_Talk_FRA = L23_1
L23_1 = {}
L24_1 = "FOOLSDAY_PART2_NODE1_EPILOGUE@73#Talk"
L23_1.m_CutScenKey_Talk = L24_1
L24_1 = 73
L23_1.m_CutScenProcessKey = L24_1
L23_1.m_CutScenID = 2700117
L23_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L23_1.m_bWaitClick = true
L23_1.m_fWaitTime = 0
L24_1 = "KNIGHT_REPLACER_BACK_FOOLSDAY"
L23_1.m_CharStrID = L24_1
L24_1 = "L"
L23_1.m_Pos = L24_1
L24_1 = "고, 고작?! 인형을 갖고 싶어하면 악당이 아니라는 거냐?!"
L23_1.m_Talk_KOREA = L24_1
L23_1.m_fTalkTime = 0.03
L24_1 = "た、たかが！？　ぬいぐるみを欲しがるやつは悪党じゃないってのか！？"
L23_1.m_Talk_JPN = L24_1
L24_1 = "L-lousy?! Are you saying that villains aren't supposed to like dolls?"
L23_1.m_Talk_ENG = L24_1
L24_1 = "只是？！你的意思是反派不能想要娃娃嗎？！"
L23_1.m_Talk_TWN = L24_1
L24_1 = "ชะ-ชั้นต่ำเหรอ?! เธอจะบอกว่าวายร้ายไม่ควรชอบตุ๊กตาเหรอ?"
L23_1.m_Talk_THA = L24_1
L24_1 = "X-xấu xí?! Ý cô là kẻ phản diện thì không được thích búp bê à?"
L23_1.m_Talk_VTN = L24_1
L24_1 = "不匹配？！难道恶棍就不能要娃娃吗？！"
L23_1.m_Talk_SCN = L24_1
L24_1 = "L-lausig?! Willst du damit etwa sagen, dass Schurken keine Puppen mögen dürfen?!"
L23_1.m_Talk_DEU = L24_1
L24_1 = "M-Minable ?! Qu'est-ce que tu insinues, là ? Que les méchants n'ont pas le droit d'aimer les peluches ?"
L23_1.m_Talk_FRA = L24_1
L24_1 = {}
L25_1 = "FOOLSDAY_PART2_NODE1_EPILOGUE@74#Talk"
L24_1.m_CutScenKey_Talk = L25_1
L25_1 = 74
L24_1.m_CutScenProcessKey = L25_1
L24_1.m_CutScenID = 2700117
L24_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L24_1.m_bWaitClick = true
L24_1.m_fWaitTime = 0
L24_1.m_CharStrID = "OROCHI_JAPAN_NULL_FOOLSDAY"
L25_1 = "R"
L24_1.m_Pos = L25_1
L25_1 = "그냥… 야생마처럼 생겨 먹은 네놈도 그런 면이 있다는 게 의외라서 말이다."
L24_1.m_Talk_KOREA = L25_1
L24_1.m_fTalkTime = 0.03
L25_1 = "ただ……野生馬のような貴様にそういう面があるということが意外でな。"
L24_1.m_Talk_JPN = L25_1
L25_1 = "Rather... it’s that you don’t look like one to enjoy the dainty things in life."
L24_1.m_Talk_ENG = L25_1
L25_1 = "我只是…沒想到在你狂野不羈的形象之下，竟然有顆赤子之心。"
L24_1.m_Talk_TWN = L25_1
L25_1 = "ออกไปทาง... เจ้าดูไม่เหมือนคนผู้ชอบสิ่งสวยงามในชีวิตมากกว่า"
L24_1.m_Talk_THA = L25_1
L25_1 = "Chỉ là…không ngờ ngươi lại là kẻ thích mấy thứ bánh bèo đó."
L24_1.m_Talk_VTN = L25_1
L25_1 = "我只是……没想到你长成这样居然也会喜欢娃娃。"
L24_1.m_Talk_SCN = L25_1
L25_1 = "Nun ja ... Es ist nur überraschend, dass jemand, der so ungezähmt aussieht wie du, auch so eine Seite besitzt."
L24_1.m_Talk_DEU = L25_1
L25_1 = "Non, simplement... quand on te regarde, c'est difficile d'imaginer que tu as un tel péché mignon."
L24_1.m_Talk_FRA = L25_1
L25_1 = {}
