L28_1.m_CharStrID = "OROCHI_JAPAN_NULL_FOOLSDAY"
L29_1 = "R"
L28_1.m_Pos = L29_1
L29_1 = "그런 나약한 집게로 인형을 집으려 애쓰다니, 규칙에 참으로 순종적이구나."
L28_1.m_Talk_KOREA = L29_1
L28_1.m_fTalkTime = 0.03
L29_1 = "そのように軟弱な道具でぬいぐるみを取ろうと躍起になるとは、実に規則に忠実なものだ。"
L28_1.m_Talk_JPN = L29_1
L29_1 = "You seem very servile, trying to catch that thing with such a shabby claw."
L28_1.m_Talk_ENG = L29_1
L29_1 = "竟然這麼認真地用那個鬆鬆的爪子要抓娃娃，你還真是守規矩呢。"
L28_1.m_Talk_TWN = L29_1
L29_1 = "เห็นเจ้าพยายามจับสิ่งนั้นด้วยกรงเล็บโกโรโกโสนั่น ดูแล้วช่างสิ้นคิด"
L28_1.m_Talk_THA = L29_1
L29_1 = "Trông ngươi cố gắng dùng cái móng gắp này để lấy thứ đó thật hèn quá."
L28_1.m_Talk_VTN = L29_1
L29_1 = "居然费尽心思地用那个摇摇欲坠的夹子去抓娃娃，你真是太循规蹈矩了。"
L28_1.m_Talk_SCN = L29_1
L29_1 = "Wie brav du doch versuchst, eine Puppe mit einem so schwachen Greifer herauszuholen."
L28_1.m_Talk_DEU = L29_1
L29_1 = "Tu vas vraiment te borner à utiliser cette stupide grue jusqu'au bout ? Quel ennui."
L28_1.m_Talk_FRA = L29_1
L29_1 = {}
L30_1 = "FOOLSDAY_PART2_NODE1_EPILOGUE@79#Talk"
L29_1.m_CutScenKey_Talk = L30_1
L30_1 = 79
L29_1.m_CutScenProcessKey = L30_1
L29_1.m_CutScenID = 2700117
L29_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L29_1.m_bWaitClick = true
L29_1.m_fWaitTime = 0
L29_1.m_Face = "UNIT_SERIOUS"
L30_1 = "KNIGHT_REPLACER_BACK_FOOLSDAY"
L29_1.m_CharStrID = L30_1
L30_1 = "L"
L29_1.m_Pos = L30_1
L30_1 = "뭐? 갑자기 그게 무슨 소리야?"
L29_1.m_Talk_KOREA = L30_1
L29_1.m_fTalkTime = 0.03
L30_1 = "は？　いきなりなに言ってんだよ？"
L29_1.m_Talk_JPN = L30_1
L30_1 = "What? What are you talking about?"
L29_1.m_Talk_ENG = L30_1
L30_1 = "什麼意思？你在說什麼？"
L29_1.m_Talk_TWN = L30_1
L30_1 = "หา? พูดอะไรของเธอนั่น?"
L29_1.m_Talk_THA = L30_1
L30_1 = "Cái gì? Cô có ý gì?"
L29_1.m_Talk_VTN = L30_1
L30_1 = "什么？你什么意思？"
L29_1.m_Talk_SCN = L30_1
L30_1 = "Häh? Was meinst du denn damit?"
L29_1.m_Talk_DEU = L30_1
L30_1 = "Hein ? Qu'est-ce que tu veux dire ?"
L29_1.m_Talk_FRA = L30_1
L30_1 = {}
L31_1 = "FOOLSDAY_PART2_NODE1_EPILOGUE@80#Talk"
L30_1.m_CutScenKey_Talk = L31_1
L31_1 = 80
L30_1.m_CutScenProcessKey = L31_1
L30_1.m_CutScenID = 2700117
L30_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L30_1.m_bWaitClick = true
L30_1.m_fWaitTime = 0
L30_1.m_CharStrID = "OROCHI_JAPAN_NULL_FOOLSDAY"
L31_1 = "R"
L30_1.m_Pos = L31_1
L31_1 = "악당이면 악당답게, 집게로 인형을 뽑아야 한다는 인간들의 룰 따위는 부숴도 되지 않느냔 말이다."
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "悪党なら悪党らしく、道具でぬいぐるみを取るという人間のルールなど、守らずともよいのではないか。"
L30_1.m_Talk_JPN = L31_1
L31_1 = "You’re a villain. That alone is a reason to obtain what you want without abiding by the rules."
L30_1.m_Talk_ENG = L31_1
L31_1 = "我的意思是身為反派就要像個反派，用爪子抓娃娃是人類的規矩，反派何須遵守。"
L30_1.m_Talk_TWN = L31_1
L31_1 = "เจ้าเป็นวายร้าย ลำพังเหตุผลข้อนั้นก็เพียงพอให้เอาของที่อยากได้มาโดยไม่ทำตามกฎแล้ว"
L30_1.m_Talk_THA = L31_1
L31_1 = "Cô là kẻ phản diện. Đủ lý do để lấy bất cứ thứ gì cô muốn mà chẳng cần phải để tâm tới luật lệ."
L30_1.m_Talk_VTN = L31_1
L31_1 = "恶棍就要有恶棍的样子，必须用夹子抓娃娃是人类定的规矩，你完全可以不遵守。"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Du bist eine Schurkin, also musst du dich auch wie eine Schurkin verhalten! Also hör auf dich an die Regeln der Menschen zu halten und mit diesem schwachen Greifer nach einer Puppe zu schnappen."
L30_1.m_Talk_DEU = L31_1
L31_1 = "Tu es une criminelle, non ? Qu'est-ce qui t'oblige de te conformer aux règles ?"
L30_1.m_Talk_FRA = L31_1
L31_1 = {}
L32_1 = "FOOLSDAY_PART2_NODE1_EPILOGUE@81#Talk"
L31_1.m_CutScenKey_Talk = L32_1
L32_1 = 81
L31_1.m_CutScenProcessKey = L32_1
L31_1.m_CutScenID = 2700117
L31_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L31_1.m_bWaitClick = true
L31_1.m_fWaitTime = 0
L31_1.m_Face = "UNIT_IDLE"
L32_1 = "KNIGHT_REPLACER_BACK_FOOLSDAY"
L31_1.m_CharStrID = L32_1
L32_1 = "L"
L31_1.m_Pos = L32_1
L32_1 = "어라? 그러고보니 내가 왜 정정당당하게 인형뽑기를 하고 있었지?"
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "あれ？　そういえばアタシはなんで正々堂々とクレーンゲームをしてるんだ？"
L31_1.m_Talk_JPN = L32_1
L32_1 = "Huh? Come to think of it, why was I trying to get this fair and square?"
L31_1.m_Talk_ENG = L32_1
L32_1 = "喔？聽你這麼一說，我幹嘛這麼乖，用這種正當方法在抓娃娃？"
L31_1.m_Talk_TWN = L32_1
L32_1 = "เอ๋? จะว่าไป นี่ฉันกำลังพยายามเอามันมาอย่างยุติธรรมและถูกต้องเหรอเนี่ย?"
L31_1.m_Talk_THA = L32_1
L32_1 = "Chậc? Nghĩ kỹ thì sao tôi lại cố gắng khiến nó công bằng làm gì nhỉ?"
L31_1.m_Talk_VTN = L32_1
L32_1 = "哎呀？听你这么一说还真是，我为什么要规规矩矩地抓娃娃呢？"
L31_1.m_Talk_SCN = L32_1
L32_1 = "Hä? Wenn ich so darüber nachdenke, frage ich mich auch, warum ich denn eigentlich so fair und ehrlich gespielt habe?!"
L31_1.m_Talk_DEU = L32_1
L32_1 = "Ah ? Tu marques un point, là. Qu'est-ce que je m'emmerde à essayer de gagner avec cette machine ?"
L31_1.m_Talk_FRA = L32_1
L32_1 = {}
L33_1 = "FOOLSDAY_PART2_NODE1_EPILOGUE@82#Talk"
L32_1.m_CutScenKey_Talk = L33_1
L33_1 = 82
L32_1.m_CutScenProcessKey = L33_1
L32_1.m_CutScenID = 2700117
L32_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L32_1.m_bWaitClick = true
L32_1.m_fWaitTime = 0
L32_1.m_Face = "UNIT_PRIDE"
L33_1 = "KNIGHT_REPLACER_BACK_FOOLSDAY"
L32_1.m_CharStrID = L33_1
L33_1 = "L"
L32_1.m_Pos = L33_1
L33_1 = "좋아. 당장 안으로 가서 인형들 전부 꺼내 올 테니 거기서 누가 오는지 망 좀 보고 있으라고."
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "よし。今すぐ中に入ってぬいぐるみを全部取って来るから、誰か来ないか見張ってな。"
L32_1.m_Talk_JPN = L33_1
L33_1 = "All right. I’ll get inside and grab all of those dolls. You stay there and keep an eye on people, in case anyone walks over."
L32_1.m_Talk_ENG = L33_1
L33_1 = "好，我現在就進去把娃娃全都撈出來，你幫我把個風。"
L32_1.m_Talk_TWN = L33_1
L33_1 = "เอาล่ะ งั้นฉันจะมุดเข้าไปเอาตุ๊กตาพวกนั้นมาให้หมด เธออยู่ที่นี่คอยดูต้นทางไว้นะ เผื่อมีใครเดินมา"
L32_1.m_Talk_THA = L33_1
L33_1 = "Được rồi. Tôi sẽ vào bên trong và lấy hết số búp bê đó. Cô ở đây và chú ý người ta, đề phòng ai đó lẻn vào."
L32_1.m_Talk_VTN = L33_1
L33_1 = "好！我现在就进去把娃娃都拿出来。喂，你在那边帮我望风。"
L32_1.m_Talk_SCN = L33_1
L33_1 = "Also gut. Ich werde hineinkrabbeln und mir all diese Puppen schnappen. Du hältst solange die Augen offen und sagst mit Bescheid, falls jemand kommt."
L32_1.m_Talk_DEU = L33_1
L33_1 = "Tu as raison, je vais m'infiltrer dans la cage pour la dévaliser de l'intérieur. Reste ici pour monter la garde et pour éviter des coups d'œil indiscrets."
L32_1.m_Talk_FRA = L33_1
L33_1 = {}
