L38_1 = "끄응… 조금만… 더 들어가면…!"
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "ぐぬぬ……もうちょっと……入れれば……！"
L37_1.m_Talk_JPN = L38_1
L38_1 = "Ngh... Just a little more...!"
L37_1.m_Talk_ENG = L38_1
L38_1 = "唔…只要…再進去一點…！"
L37_1.m_Talk_TWN = L38_1
L38_1 = "อึก... อีกนิดเดียว...!"
L37_1.m_Talk_THA = L38_1
L38_1 = "Ngh...Chỉ một chút nữa thôi...!"
L37_1.m_Talk_VTN = L38_1
L38_1 = "呃嗯……再……进去一点点……！"
L37_1.m_Talk_SCN = L38_1
L38_1 = "Argh ... Wenn ich nur noch ein bisschen weiter reinkomme ...!"
L37_1.m_Talk_DEU = L38_1
