L40_1 = "됐다! 안까지 들어오는데 성공했어!"
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "よし！　中に入るまでは成功したぞ！"
L39_1.m_Talk_JPN = L40_1
L40_1 = "I did it! I made it inside!"
L39_1.m_Talk_ENG = L40_1
L40_1 = "終於！我終於爬到裡面啦！"
L39_1.m_Talk_TWN = L40_1
L40_1 = "ได้แล้ว! ฉันเข้ามาได้แล้ว!"
L39_1.m_Talk_THA = L40_1
L40_1 = "Tôi đã làm được! Tôi vào bên trong rồi!"
L39_1.m_Talk_VTN = L40_1
L40_1 = "好了！进来了！"
L39_1.m_Talk_SCN = L40_1
L40_1 = "Juhuu! Ich habe es nach drinnen geschafft!"
L39_1.m_Talk_DEU = L40_1
L40_1 = "Ça y est ! Je suis à l'intérieur !"
