L42_1 = "뭔가 심상치 않은 기운이 다가오고 있어. 숨어라."
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "何か尋常でない気配が近づいてきている。隠れろ。"
L41_1.m_Talk_JPN = L42_1
L42_1 = "I feel something sinister approaching. Hide."
L41_1.m_Talk_ENG = L42_1
L42_1 = "不太對勁，好像有什麼東西靠近，躲起來！"
L41_1.m_Talk_TWN = L42_1
L42_1 = "ข้าสังหรณ์ว่ามีเรื่องไม่ดีเกิดขึ้น ซ่อนก่อน"
L41_1.m_Talk_THA = L42_1
L42_1 = "Ta cảm nhận được điềm xấu đang tới gần. Trốn đi."
L41_1.m_Talk_VTN = L42_1
L42_1 = "有股不寻常的气息正在靠近，快躲起来。"
L41_1.m_Talk_SCN = L42_1
L42_1 = "Ich habe das Gefühl, dass sich etwas Unheimliches nähert. Versteck dich!"
L41_1.m_Talk_DEU = L42_1
L42_1 = "Je sens une aura sinistre s'approcher. Quelque chose arrive, allons nous cacher."
L41_1.m_Talk_FRA = L42_1
