L43_1.m_CharStrID = "KNIGHT_REPLACER_UNIT_FOOLSDAY"
L44_1 = "뭣? 잠깐, 여기서 대체 어떻게 숨으라는 거야!"
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "は？　ちょ、ここでいったいどうやって隠れろっていうんだ！"
L43_1.m_Talk_JPN = L44_1
L44_1 = "What? Wait, how do you expect me to hide in here?!"
L43_1.m_Talk_ENG = L44_1
L44_1 = "什麼？拜託，這邊是要怎麼躲啦！"
L43_1.m_Talk_TWN = L44_1
L44_1 = "หา? เดี๋ยวสิ เธอจะให้ฉันซ่อนในนี้เหรอ?"
L43_1.m_Talk_THA = L44_1
L44_1 = "Cái gì? Chờ đã, chỗ này thì trốn ở đâu được?!"
L43_1.m_Talk_VTN = L44_1
L44_1 = "什么？等等，在这里面你让我怎么躲！"
L43_1.m_Talk_SCN = L44_1
L44_1 = "Was? Warte mal, wo zur Hölle soll ich mich denn hier verstecken?!"
L43_1.m_Talk_DEU = L44_1
L44_1 = "Hein ? Attends, comment tu veux que je me cache là-dedans ?"
L43_1.m_Talk_FRA = L44_1
L44_1 = {}
