L44_1.m_Pos = "C"
L45_1 = "그거야 네놈이 알아서 잘 해야지."
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "それは貴様が考えることだな。"
L44_1.m_Talk_JPN = L45_1
L45_1 = "That’s up to you to figure out."
L44_1.m_Talk_ENG = L45_1
L45_1 = "那是你的問題，自己想辦法。"
L44_1.m_Talk_TWN = L45_1
L45_1 = "แล้วแต่เจ้าจะนึกเอา"
L44_1.m_Talk_THA = L45_1
L45_1 = "Cái đó ngươi phải tự tìm đi."
L44_1.m_Talk_VTN = L45_1
L45_1 = "你自己看着办。"
L44_1.m_Talk_SCN = L45_1
L45_1 = "Die Lösung dieses Problems überlasse ich ganz allein dir."
L44_1.m_Talk_DEU = L45_1
L45_1 = "Ça, c'est ton problème."
L44_1.m_Talk_FRA = L45_1
