L47_1 = "喂，你說的是人話…！"
L46_1.m_Talk_TWN = L47_1
L47_1 = "เฮ่ย อย่าพูดจาไร้สาระ...!"
L46_1.m_Talk_THA = L47_1
L47_1 = "Này, đừng có ngớ ngẩn thế chứ...!"
