L49_1.m_CharStrID = L50_1
L49_1.m_Pos = "C"
L50_1 = "낯선 그림체로군. 주인장이 이번에 새로 들여왔다는 인형인가?"
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "見慣れぬ絵柄じゃな。店主が今度新しく仕入れたというぬいぐるみか？"
