L7_1 = "시종, 네가 이걸 한 번 뽑아보겠느냐?"
L6_1.m_Talk_KOREA = L7_1
L6_1.m_fTalkTime = 0.03
L7_1 = "僕よ、其方がこれを引いてみるか？"
L6_1.m_Talk_JPN = L7_1
L7_1 = "Why don’t you try to pull this one out, servant?"
L6_1.m_Talk_ENG = L7_1
L7_1 = "僕人，這你抓得到嗎？"
L6_1.m_Talk_TWN = L7_1
L7_1 = "ทำไมไม่ลองคีบตัวนี้ออกมาล่ะ เจ้าข้ารับใช้"
L6_1.m_Talk_THA = L7_1
