L9_1 = "FOOLSDAY_PART2_NODE1_EPILOGUE@108#Talk"
L8_1.m_CutScenKey_Talk = L9_1
L9_1 = 108
L8_1.m_CutScenProcessKey = L9_1
L8_1.m_CutScenID = 2700117
L8_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L8_1.m_bWaitClick = true
L8_1.m_fWaitTime = 0
L9_1 = "DOMA_FALLEN_NULL_NULL"
L8_1.m_CharStrID = L9_1
L9_1 = "호오… 확실히 다른 인형보다 값어치는 있어보입니다만, 터무니없이 무거워 보이는군요."
L8_1.m_Talk_KOREA = L9_1
L8_1.m_fTalkTime = 0.03
L9_1 = "ほう……確かに他のぬいぐるみよりは値打ちはありそうですが、とてつもなく重そうですね。"
L8_1.m_Talk_JPN = L9_1
L9_1 = "Hmm... It does look more valuable than the rest of the dolls. However, it also looks incredibly heavy."
L8_1.m_Talk_ENG = L9_1
L9_1 = "喔呵… 確實看起來比其他娃娃貴的感覺，可是重量感覺也不輕。"
L8_1.m_Talk_TWN = L9_1
L9_1 = "อืม... มันดูแพงกว่าตัวอื่นๆ เชียวนะครับ แต่ถึงอย่างนั้นก็ดูหนักมากทีเดียว"
L8_1.m_Talk_THA = L9_1
L9_1 = "Hmm... Trông nó giá trị hơn những con búp bê khác. Tuy nhiên, nó trông cũng nặng lắm đây.."
L8_1.m_Talk_VTN = L9_1
L9_1 = "吼吼……看起来确实比其他娃娃更稀有，不过似乎也重得离谱。"
L8_1.m_Talk_SCN = L9_1
L9_1 = "Hmm ... Sie sieht zwar wertvoller als die anderen Puppen aus, aber auch deutlich schwerer."
L8_1.m_Talk_DEU = L9_1
L9_1 = "Hmm... Cette poupée semble de meilleure facture que les autres, mais elle est aussi extrêmement lourde."
L8_1.m_Talk_FRA = L9_1
L9_1 = {}
L10_1 = "FOOLSDAY_PART2_NODE1_EPILOGUE@109#Talk"
L9_1.m_CutScenKey_Talk = L10_1
L10_1 = 109
L9_1.m_CutScenProcessKey = L10_1
L9_1.m_CutScenID = 2700117
L9_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L9_1.m_bWaitClick = true
L9_1.m_fWaitTime = 0
L10_1 = "DOMA_FALLEN_NULL_NULL"
L9_1.m_CharStrID = L10_1
L10_1 = "값비싸기 때문에 이목을 끌지만 막상 얻는 것은 거의 불가능한, 전형적인 미끼 상품이죠."
L9_1.m_Talk_KOREA = L10_1
L9_1.m_fTalkTime = 0.03
L10_1 = "高値に見えて人目を引きますが、手に入れることは不可能に近い、典型的なおとり商品でございます。"
L9_1.m_Talk_JPN = L10_1
L10_1 = "A typical bait prize, which looks flashy but is almost impossible to get."
L9_1.m_Talk_ENG = L10_1
L10_1 = "這應該是用來吸引客人目光的誘餌，實際上根本抓不起來。"
L9_1.m_Talk_TWN = L10_1
L10_1 = "ก็รางวัลล่อใจทั่วไป ดูหวือหวาแต่ว่าแทบไม่มีทางเอามาได้เลย"
L9_1.m_Talk_THA = L10_1
L10_1 = "Phần thưởng bẫy giá điển hình, dù trông hào nhoáng nhưng thực tế lại chẳng ra gì."
L9_1.m_Talk_VTN = L10_1
L10_1 = "因为其高昂的价格引人注目，但又几乎不可能得到，是典型的诱饵商品呢。"
L9_1.m_Talk_SCN = L10_1
L10_1 = "Es ist ein klassisches Köderprodukt, das direkt ins Auge springt, aber fast unmöglich zu bekommen ist."
L9_1.m_Talk_DEU = L10_1
L10_1 = "Un appât typique pour ce genre de machines. Le prix ultime, tape-à-l'œil mais presque impossible à obtenir."
L9_1.m_Talk_FRA = L10_1
L10_1 = {}
