L13_1 = 112
L12_1.m_CutScenProcessKey = L13_1
L12_1.m_CutScenID = 2700117
L12_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L12_1.m_bWaitClick = true
L12_1.m_fWaitTime = 0
L13_1 = "DOMA_FALLEN_NULL_NULL"
L12_1.m_CharStrID = L13_1
L13_1 = "주인님께서 원하신다면야. 이 도마에게 맡겨주시길."
L12_1.m_Talk_KOREA = L13_1
L12_1.m_fTalkTime = 0.03
L13_1 = "我が主のお望みとあれば、このドマにお任せを。"
L12_1.m_Talk_JPN = L13_1
L13_1 = "Your wishes are my command, Mistress. Please leave it to me."
L12_1.m_Talk_ENG = L13_1
L13_1 = "只要是主人想要的，儘管包在多馬身上。"
L12_1.m_Talk_TWN = L13_1
L13_1 = "ประสงค์ของท่านคือคำบัญชาของผมครับนายหญิง เชื่อมือโดมะผู้นี้เถิด"
L12_1.m_Talk_THA = L13_1
L13_1 = "Mọi mong ước của cô đều là mệnh lệnh với tôi, Cô chủ à. Cứ để Doma lo."
L12_1.m_Talk_VTN = L13_1
L13_1 = "主人想要的话，就交给多马吧。"
L12_1.m_Talk_SCN = L13_1
L13_1 = "Mitnichten. Ihr Wunsch ist mein Befehl, Herrin. Überlassen Sie es nur Doma."
L12_1.m_Talk_DEU = L13_1
L13_1 = "Vos désirs sont des ordres, Maîtresse. Je m'en occupe."
L12_1.m_Talk_FRA = L13_1
