L15_1.m_CharStrID = L16_1
L16_1 = "제아무리 뽑기 힘든 상품이라도 노릴 수 있는 약점은 존재하는 법."
L15_1.m_Talk_KOREA = L16_1
L15_1.m_fTalkTime = 0.03
L16_1 = "いかに入手困難な商品であろうとも、隙は必ず存在するものです。"
L15_1.m_Talk_JPN = L16_1
L16_1 = "No matter how tough the target might be... there always lies a weak spot."
L15_1.m_Talk_ENG = L16_1
L16_1 = "再怎麼難抓的商品也有它的弱點。"
L15_1.m_Talk_TWN = L16_1
L16_1 = "ไม่ว่าเป้าหมายจะแข็งแกร่งเพียงใด... อย่างไรก็ต้องมีจุดอ่อนเสมอ"
L15_1.m_Talk_THA = L16_1
L16_1 = "Cho dù mục tiêu có khó khăn thế nào...luôn có điểm yếu."
L15_1.m_Talk_VTN = L16_1
L16_1 = "再难抓的商品也有可以下手的弱点。"
L15_1.m_Talk_SCN = L16_1
L16_1 = "Egal wie schwierig es auch aussehen mag, es gibt immer einen Trick."
L15_1.m_Talk_DEU = L16_1
L16_1 = "Même l'ennemi le plus redoutable a toujours un point faible..."
L15_1.m_Talk_FRA = L16_1
