L17_1 = "DOMA_FALLEN_NULL_NULL"
L16_1.m_CharStrID = L17_1
L17_1 = "가령 이런 눈꺼풀 같은 홈부분에 집게를 걸친다면…"
L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "例えば、この瞼のような部分にアームをひっかければ……"
L16_1.m_Talk_JPN = L17_1
L17_1 = "For instance, the eyelid could be an excellent place to hook the claw..."
L16_1.m_Talk_ENG = L17_1
L17_1 = "譬如說用爪子去鉤眼皮的部分…"
L16_1.m_Talk_TWN = L17_1
L17_1 = "ตัวอย่างเช่น จุดที่เหมาะจะคีบที่สุด ก็คือตรงเปลือกตา..."
L16_1.m_Talk_THA = L17_1
L17_1 = "Ví dụ như mí mắt có thể là một địa điểm tuyệt vời để móc móng vuốt vào..."
L16_1.m_Talk_VTN = L17_1
L17_1 = "如果用夹子勾住像眼皮一样凹陷的部分……"
L16_1.m_Talk_SCN = L17_1
L17_1 = "Zum Beispiel könnte das Augenlid ein ausgezeichneter Ort sein, um den Greifer einzuhaken ..."
L16_1.m_Talk_DEU = L17_1
L17_1 = "Peut-être qu'en attrapant cette peluche par la paupière, je pourrais..."
L16_1.m_Talk_FRA = L17_1
