L23_1[L24_1] = true
L23_1.m_Crash = 30
L24_1 = "이 자식! 감히 내 눈을 찔러?! 짓밟아주지!"
L23_1.m_Talk_KOREA = L24_1
L23_1.m_fTalkTime = 0.03
L24_1 = "てめぇ！　よくもアタシの目を突っついてくれたな！　踏みつぶしてやる！"
L23_1.m_Talk_JPN = L24_1
L24_1 = "You idiot! How dare you poke my eye! I’ll crush you!"
L23_1.m_Talk_ENG = L24_1
L24_1 = "你這臭小子！想鉤我的眼皮？！當心我打爆你！"
L23_1.m_Talk_TWN = L24_1
L24_1 = "ไอ้ควายเอ๊ย! กล้าทิ่มตาฉันเหรอ! แม่จะขยี้ให้แหลกเลย!"
L23_1.m_Talk_THA = L24_1
L24_1 = "Đồ ngốc! Sao mi dám chọc vào mắt ta! Ta sẽ nghiền nát mi!"
L23_1.m_Talk_VTN = L24_1
L24_1 = "你这家伙！竟敢戳我的眼睛？！我要踩扁你！"
L23_1.m_Talk_SCN = L24_1
L24_1 = "Du Idiot! Wie kannst du es wagen, mir ins Auge zu stechen! Ich werde dich zerquetschen!"
L23_1.m_Talk_DEU = L24_1
L24_1 = "Ça va pas la tête ? Comment oses-tu t'en prendre à mon œil comme ça ? Je vais t'écraser !"
L23_1.m_Talk_FRA = L24_1
