L26_1.m_Crash = 20
L27_1 = "뭐야? 이거 왜 안 깨져?"
L26_1.m_Talk_KOREA = L27_1
L26_1.m_fTalkTime = 0.03
L27_1 = "何だ？　これ、なんで割れないんだ？"
L26_1.m_Talk_JPN = L27_1
L27_1 = "Huh? Why won’t this break?"
L26_1.m_Talk_ENG = L27_1
L27_1 = "搞什麼？怎麼不會破？"
L26_1.m_Talk_TWN = L27_1
L27_1 = "หา? ทำไมไม่พังล่ะ?"
L26_1.m_Talk_THA = L27_1
L27_1 = "Huh? Sao thứ này không vỡ ra chứ?"
L26_1.m_Talk_VTN = L27_1
L27_1 = "啊？这东西为什么打不碎？"
L26_1.m_Talk_SCN = L27_1
L27_1 = "Hä? Warum zerbricht es denn nicht?"
L26_1.m_Talk_DEU = L27_1
L27_1 = "Euh ? Pourquoi j'arrive pas à casser la vitre ?"
L26_1.m_Talk_FRA = L27_1
