L29_1 = "FOOLSDAY_PART2_NODE1_EPILOGUE@128#Talk"
L28_1.m_CutScenKey_Talk = L29_1
L29_1 = 128
L28_1.m_CutScenProcessKey = L29_1
L28_1.m_CutScenID = 2700117
L28_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L28_1.m_bWaitClick = true
L28_1.m_fWaitTime = 0
L29_1 = "DOMA_FALLEN_NULL_NULL"
L28_1.m_CharStrID = L29_1
L29_1 = "후후, 그 기계를 부수고 나오는 건 어려울 겁니다."
L28_1.m_Talk_KOREA = L29_1
L28_1.m_fTalkTime = 0.03
L29_1 = "ふふ、その機械を壊して出てくるのは難しいでしょう。"
L28_1.m_Talk_JPN = L29_1
L29_1 = "Ha ha, it won’t be easy trying to break through that glass."
L28_1.m_Talk_ENG = L29_1
L29_1 = "呵呵，你想破壞這台機器從裡面爬出來應該有困難。"
L28_1.m_Talk_TWN = L29_1
L29_1 = "ฮ่าฮ่า จะทำลายกระจกนั่นน่ะไม่ง่ายนะครับ"
L28_1.m_Talk_THA = L29_1
L29_1 = "Ha ha, Phá vỡ tấm kính đó chẳng dễ chút nào đâu."
L28_1.m_Talk_VTN = L29_1
L29_1 = "呵呵，想打碎那个机器可不容易哦。"
L28_1.m_Talk_SCN = L29_1
L29_1 = "Haha, es wird nicht einfach sein, dieses Glas zu durchbrechen."
L28_1.m_Talk_DEU = L29_1
L29_1 = "Hu hu. Ces machines ne se brisent pas si facilement."
L28_1.m_Talk_FRA = L29_1
L29_1 = {}
L30_1 = "FOOLSDAY_PART2_NODE1_EPILOGUE@129#Talk"
L29_1.m_CutScenKey_Talk = L30_1
L30_1 = 129
L29_1.m_CutScenProcessKey = L30_1
L29_1.m_CutScenID = 2700117
L29_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L29_1.m_bWaitClick = true
L29_1.m_fWaitTime = 0
L30_1 = "DOMA_FALLEN_NULL_NULL"
L29_1.m_CharStrID = L30_1
L30_1 = "이 오락실의 단골인 저희 주인님께서 게임에서 지고 화가 날 때마다 기물을 부수다보니, 가게주인분이 세계최고의 방벽제조사인 ‘더 월’에 의뢰를 맡겨 제작한 특수유리니까요."
L29_1.m_Talk_KOREA = L30_1
L29_1.m_fTalkTime = 0.03
L30_1 = "このゲームセンターの常連である我が主が、ゲームに負けるたびに怒って機械を壊したせいで、店主が世界一の防壁製造会社「ザ・ウォール」に依頼して作らせた特殊ガラスですから。"
L29_1.m_Talk_JPN = L30_1
L30_1 = "As a regular customer of this arcade, my mistress used to break the machines whenever she would lose or fail. So the owner of the shop decided to make special orders to \"The Wall\", the leading company for barricades and bulletproof glass."
L29_1.m_Talk_ENG = L30_1
L30_1 = "我們主人可是這間遊戲場的常客，每次主人輸掉遊戲發火時都會攻擊機台，但店家說這是委託世界頂尖護盾製造商‘壁壘’製作的特殊玻璃。"
L29_1.m_Talk_TWN = L30_1
L30_1 = "ในฐานะลูกค้าประจำ นายท่านของผมแพ้หรือพลาดทีไรก็พังเครื่องทุกครั้งครับ เจ้าของร้านก็เลยทำคำสั่งซื้อพิเศษไปที่ \"เดอะวอลล์\" บริษัทชั้นนำด้านการผลิตเครื่องกีดขวางและกระจกกันกระสุน"
L29_1.m_Talk_THA = L30_1
L30_1 = "Là khách hàng thường xuyên của khu trò chơi điện tử này, cô chủ từng phá vỡ mấy cái máy chơi cho dù thua hay thắng. Thế nên chủ cửa hàng đã đặc biệt đặt hàng với \"Bức Tường\", công ty hàng đầu về phòng vệ và kính chống đạn."
L29_1.m_Talk_VTN = L30_1
L30_1 = "得益于这个游戏厅的常客——我们的主人每次输掉游戏发火时都会砸东西，所以店主委托了这个世界最好的防护墙制造商“壁垒”制作了这种特制玻璃。"
L29_1.m_Talk_SCN = L30_1
L30_1 = "Meine Herrin, die regelmäßig in dieser Spielhalle ist, randaliert oft, wenn sie nach einem verlorenen Spiel wütend wird, also ist es ein spezielles Glas, das auf Wunsch des Spielhallenbesitzers von „Die Mauer“, der führenden Firma für Barrikaden und kugelsicheres Glas, hergestellt wurde."
L29_1.m_Talk_DEU = L30_1
L30_1 = "Voyez-vous, ma maîtresse est une cliente régulière de cette salle d'arcade. Mais ayant la fâcheuse habitude de tout casser quand elle n'obtient pas ce qu'elle veut, le propriétaire de l'établissement a été contraint de passer commande chez « Le Mur » pour équiper ses machines, une entreprise spécialisée dans la conception de barricades et de verre pare-balles."
L29_1.m_Talk_FRA = L30_1
L30_1 = {}
L31_1 = "FOOLSDAY_PART2_NODE1_EPILOGUE@130#Talk"
L30_1.m_CutScenKey_Talk = L31_1
L31_1 = 130
L30_1.m_CutScenProcessKey = L31_1
L30_1.m_CutScenID = 2700117
L30_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L30_1.m_bWaitClick = true
L30_1.m_fWaitTime = 0
L30_1.m_Face = "UNIT_SERIOUS"
L31_1 = "ROSARIA_NPC_FOOLSDAY_NULL"
L30_1.m_CharStrID = L31_1
L30_1.m_Pos = "C"
L31_1 = "흥, 그래봐야 내가 마음만 먹으면 한 주먹에 부술 수 있거든?"
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "ふん、妾がその気になればこんなもの拳ひとつで壊せるぞ。"
L30_1.m_Talk_JPN = L31_1
L31_1 = "Hmph, it’ll still take me a single blow to shatter this glass into pieces."
L30_1.m_Talk_ENG = L31_1
L31_1 = "哼，要是我認真起來的話，一拳就能打爆它好嗎？"
L30_1.m_Talk_TWN = L31_1
L31_1 = "ฮึ่ม ข้าก็ยังหวดทีเดียวแหลกอยู่ดีแหละกระจกนี่"
L30_1.m_Talk_THA = L31_1
L31_1 = "Hừ,  ta vẫn chỉ mất một đòn để đập tan tấm kính này thành từng mảnh."
L30_1.m_Talk_VTN = L31_1
L31_1 = "哼，那又如何，只要我下定决心，一拳就能砸碎！"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Hmm, aber wenn ich will, dann kann ich dieses Glas mit nur einem einzigen Schlag durchbrechen."
L30_1.m_Talk_DEU = L31_1
L31_1 = "Peuh. Si je le voulais, je pourrais briser cette vitre en morceaux d'un simple claquement de doigts."
L30_1.m_Talk_FRA = L31_1
L31_1 = {}
L32_1 = 131
L31_1.m_CutScenProcessKey = L32_1
L31_1.m_CutScenID = 2700117
L31_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L31_1.m_bWaitClick = false
L31_1.m_fWaitTime = 0
L32_1 = "ROSARIA_NPC_FOOLSDAY_NULL"
L31_1.m_CharStrID = L32_1
