L32_1 = {}
L33_1 = "FOOLSDAY_PART2_NODE1_EPILOGUE@132#Talk"
L32_1.m_CutScenKey_Talk = L33_1
L33_1 = 132
L32_1.m_CutScenProcessKey = L33_1
L32_1.m_CutScenID = 2700117
L32_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L32_1.m_bWaitClick = true
L32_1.m_fWaitTime = 0
L33_1 = "DOMA_FALLEN_NULL_NULL"
L32_1.m_CharStrID = L33_1
L33_1 = "물론입니다. 주인님께서 진심을 다 한다면 이 세계를 멸망시키는 것조차 간단한 일이죠."
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "もちろんです。ご主人様が本気を出されたら、この世界を滅ぼすことさえ容易いことでしょう。"
L32_1.m_Talk_JPN = L33_1
L33_1 = "Of course, Mistress. Destroying the world would be easy as cake if it is something you deeply wish for."
L32_1.m_Talk_ENG = L33_1
L33_1 = "那是當然的，只要主人下定決心，彈指間就可以毀掉這個世界。"
L32_1.m_Talk_TWN = L33_1
L33_1 = "แน่อยู่แล้วครับนายท่าน การสาปแช่งชั่วนิรันดร์\nเป็นเรื่องง่ายเหมือนปอกกล้วยหากลึกแล้วท่านปรารถนาเช่นนั้น"
L32_1.m_Talk_THA = L33_1
L33_1 = "Dĩ nhiên, Cô chủ. Sự đày đọa vĩnh viễn chả là gì nếu người thực sự muốn."
L32_1.m_Talk_VTN = L33_1
L33_1 = "那当然。只要主人想，毁灭这个世界也是一件简单的事。"
L32_1.m_Talk_SCN = L33_1
L33_1 = "Natürlich, Herrin. Wenn Sie etwas wirklich wollen, dann ist sogar die Zerstörung dieser Welt ein Klacks für Sie."
L32_1.m_Talk_DEU = L33_1
L33_1 = "Bien entendu, Maîtresse. Si c'est quelque chose qui vous tient vraiment à cœur, nul doute qu'apporter la ruine sur ce monde serait un véritable jeu d'enfant pour vous."
L32_1.m_Talk_FRA = L33_1
L33_1 = {}
