L35_1 = "FOOLSDAY_PART2_NODE1_EPILOGUE@134#Talk"
L34_1.m_CutScenKey_Talk = L35_1
L35_1 = 134
L34_1.m_CutScenProcessKey = L35_1
L34_1.m_CutScenID = 2700117
L34_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L34_1.m_bWaitClick = true
L34_1.m_fWaitTime = 0
L34_1.m_Face = "UNIT_PRIDE"
L34_1.m_CharStrID = "KNIGHT_REPLACER_UNIT_FOOLSDAY"
L35_1 = "L"
L34_1.m_Pos = L35_1
L35_1 = "m_bCharPinup"
L34_1[L35_1] = true
L35_1 = "하! 네가 세계를 멸망시킨다고? 뭐 대단한 능력이라도 가지고 있는 모양이지?"
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "は！　てめえが世界を滅ぼす？　すごい能力でも持ってるのか？"
L34_1.m_Talk_JPN = L35_1
L35_1 = "Hah! You? Destroying the world? Sounds like you don’t know what you’re capable of."
L34_1.m_Talk_ENG = L35_1
L35_1 = "哈！你要毀掉世界？不就很厲害的樣子？"
L34_1.m_Talk_TWN = L35_1
L35_1 = "เฮอะ! เธอนะเหรอ? การสาปแช่งชั่วนิรันดร์เนี่ยนะ? พูดจาอย่างกับไม่รู้ระดับความสามารถตัวเอง"
L34_1.m_Talk_THA = L35_1
L35_1 = "Hả? Mi á? Đày đọa vĩnh viễn? Nhìn mi có thể làm gì được chứ?"
L34_1.m_Talk_VTN = L35_1
L35_1 = "哈！你能毁灭这个世界？看样子你还挺有能力啊？"
L34_1.m_Talk_SCN = L35_1
L35_1 = "Haha! Denkst du wirklich, dass du diese Welt zerstören könntest?! Du scheinst an Selbstüberschätzung zu leiden."
L34_1.m_Talk_DEU = L35_1
L35_1 = "Bah. Apporter la ruine sur ce monde, cette mioche ? Tu vas me faire croire qu'elle a des super pouvoirs, peut-être ?"
L34_1.m_Talk_FRA = L35_1
L35_1 = {}
L36_1 = "FOOLSDAY_PART2_NODE1_EPILOGUE@135#Talk"
L35_1.m_CutScenKey_Talk = L36_1
L36_1 = 135
L35_1.m_CutScenProcessKey = L36_1
L35_1.m_CutScenID = 2700117
L35_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L35_1.m_bWaitClick = true
L35_1.m_fWaitTime = 0
L35_1.m_Face = "UNIT_SURPRISE"
L36_1 = "ROSARIA_NPC_FOOLSDAY_NULL"
L35_1.m_CharStrID = L36_1
L36_1 = "R"
L35_1.m_Pos = L36_1
L36_1 = "호오? 감히 날 도발하다니. 재밌는 녀석이구나."
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "ほう？　妾を挑発するとは。面白いやつじゃな。"
L35_1.m_Talk_JPN = L36_1
L36_1 = "Oh? Are you dare taunt me? That's interesting."
L35_1.m_Talk_ENG = L36_1
L36_1 = "喔呵？竟然敢挑釁我，有趣的傢伙。"
L35_1.m_Talk_TWN = L36_1
L36_1 = "โอ้? เจ้ากำลังดูถูกข้าสินะ ไม่ค่อยได้เจอนะนี่"
L35_1.m_Talk_THA = L36_1
L36_1 = "Oh? Vậy là ngươi vừa sỉ nhục ta đấy sao. Thường thì ta không hay bị như vậy đâu."
L35_1.m_Talk_VTN = L36_1
L36_1 = "呃呃？你这是在挑衅我吗，真是个有趣的家伙。"
L35_1.m_Talk_SCN = L36_1
L36_1 = "Oh? Du wagst es, mich zu beleidigen? Was für ein lustiges Püppchen du doch bist."
L35_1.m_Talk_DEU = L36_1
L36_1 = "Oh, de la provocation ? Tu n'as pas froid aux yeux."
L35_1.m_Talk_FRA = L36_1
L36_1 = {}
L37_1 = "FOOLSDAY_PART2_NODE1_EPILOGUE@136#Talk"
L36_1.m_CutScenKey_Talk = L37_1
L37_1 = 136
L36_1.m_CutScenProcessKey = L37_1
L36_1.m_CutScenID = 2700117
L36_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L36_1.m_bWaitClick = true
L36_1.m_fWaitTime = 0
L36_1.m_CharStrID = "KNIGHT_REPLACER_UNIT_FOOLSDAY"
L37_1 = "L"
L36_1.m_Pos = L37_1
L37_1 = "m_bCharPinup"
L36_1[L37_1] = true
L37_1 = "큭큭, 난 센 척하는 녀석이 있으면 봐주곤 못 넘기는 체질이라 말이야."
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "ククッ、アタシは強いふりするやつを見ていられない体質なんでな。"
L36_1.m_Talk_JPN = L37_1
L37_1 = "Hah hah, I’m the type of person who can’t stand arrogant brats like you."
L36_1.m_Talk_ENG = L37_1
L37_1 = "呵呵，我天生就是看那種虛張聲勢的人不爽。"
L36_1.m_Talk_TWN = L37_1
L37_1 = "ฮี่ฮี่ ฉันมันพวกทนคนหยิ่งผยองแบบเธอไม่ได้น่ะ"
L36_1.m_Talk_THA = L37_1
L37_1 = "Kehe, tôi là kiểu người không thể chịu nổi những tên khốn ngạo mạn như cô."
L36_1.m_Talk_VTN = L37_1
L37_1 = "咳咳，我这个人就是看不惯有人装腔作势。"
L36_1.m_Talk_SCN = L37_1
L37_1 = "Hehe, ich bin die Art von Person, die arrogante Gören wie dich, die vorgeben stark zu sein, nicht ausstehen kann."
L36_1.m_Talk_DEU = L37_1
L37_1 = "Hé hé. J'ai horreur des gamines arrogantes dans ton genre."
L36_1.m_Talk_FRA = L37_1
L37_1 = {}
L38_1 = "FOOLSDAY_PART2_NODE1_EPILOGUE@137#Talk"
L37_1.m_CutScenKey_Talk = L38_1
L38_1 = 137
L37_1.m_CutScenProcessKey = L38_1
L37_1.m_CutScenID = 2700117
L37_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L37_1.m_bWaitClick = true
L37_1.m_fWaitTime = 0
L37_1.m_CharStrID = "KNIGHT_REPLACER_UNIT_FOOLSDAY"
L38_1 = "L"
L37_1.m_Pos = L38_1
L38_1 = "m_bCharPinup"
L37_1[L38_1] = true
L38_1 = "자신 있으면 어디 한 번 그 실력 좀 구경해볼까?"
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "自信があるんならその実力とやらを見せてもらおうじゃないか。"
L37_1.m_Talk_JPN = L38_1
L38_1 = "If you’re so confident about your powers, why not show me?"
L37_1.m_Talk_ENG = L38_1
L38_1 = "要是真這麼厲害的話，那就讓我見識一下吧？"
L37_1.m_Talk_TWN = L38_1
L38_1 = "ถ้ามั่นใจในพลังตัวเองนัก ทำไมไม่ให้ฉันดูซะหน่อยล่ะ?"
L37_1.m_Talk_THA = L38_1
L38_1 = "Nếu cô tự tin đến thế về sức mạnh của mình, sao không biểu diễn cho tôi xem thử?"
L37_1.m_Talk_VTN = L38_1
L38_1 = "你有信心的话，就跟我比试一下？"
L37_1.m_Talk_SCN = L38_1
L38_1 = "Wenn du so sehr auf deine Kräfte vertraust, warum testen wir sie dann nicht einmal aus?"
L37_1.m_Talk_DEU = L38_1
L38_1 = "Si tu as si confiance que ça en tes pouvoirs, pourquoi ne pas me faire une démonstration ?"
L37_1.m_Talk_FRA = L38_1
L38_1 = {}
L39_1 = "FOOLSDAY_PART2_NODE1_EPILOGUE@138#Talk"
L38_1.m_CutScenKey_Talk = L39_1
L39_1 = 138
L38_1.m_CutScenProcessKey = L39_1
L38_1.m_CutScenID = 2700117
L38_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L38_1.m_bWaitClick = true
L38_1.m_fWaitTime = 0
L38_1.m_Face = "UNIT_PRIDE"
L39_1 = "ROSARIA_NPC_FOOLSDAY_NULL"
L38_1.m_CharStrID = L39_1
L39_1 = "R"
L38_1.m_Pos = L39_1
L39_1 = "어린 것이 배짱 한 번 좋구나."
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "若僧が、いい度胸じゃ。"
L38_1.m_Talk_JPN = L39_1
L39_1 = "You’re brave, kid. I give you that."
L38_1.m_Talk_ENG = L39_1
L39_1 = "這傢伙膽識不錯。"
L38_1.m_Talk_TWN = L39_1
L39_1 = "กล้าดีนะนังเด็กน้อย ข้ายอมรับ"
L38_1.m_Talk_THA = L39_1
L39_1 = "Ngươi dũng cảm đấy. Ta phải công nhận điều đó."
L38_1.m_Talk_VTN = L39_1
L39_1 = "年纪不大，胆子倒不小。"
L38_1.m_Talk_SCN = L39_1
L39_1 = "Du bist echt mutig Kleine. Das muss ich ja schon zugeben."
L38_1.m_Talk_DEU = L39_1
L39_1 = "Tu as du cran, gamine. C'est tout à ton honneur."
L38_1.m_Talk_FRA = L39_1
L39_1 = {}
L40_1 = "FOOLSDAY_PART2_NODE1_EPILOGUE@139#Talk"
L39_1.m_CutScenKey_Talk = L40_1
L40_1 = 139
L39_1.m_CutScenProcessKey = L40_1
L39_1.m_CutScenID = 2700117
L39_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L39_1.m_bWaitClick = true
L39_1.m_fWaitTime = 0
L40_1 = "ROSARIA_NPC_FOOLSDAY_NULL"
L39_1.m_CharStrID = L40_1
L40_1 = "R"
L39_1.m_Pos = L40_1
L40_1 = "좋다. 오늘은 기분이 좋으니, 네놈의 결투 신청을 흔쾌히 받아주지."
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "よかろう。今日は機嫌がいい、其方の決闘の申し出は快く受けてやろう。"
L39_1.m_Talk_JPN = L40_1
L40_1 = "Very well. Since I am in a good mood today, I shall accept your offer and fight."
L39_1.m_Talk_ENG = L40_1
L40_1 = "好吧，我今天心情好，就爽快收下你的戰帖吧。"
L39_1.m_Talk_TWN = L40_1
L40_1 = "ดีล่ะ ในเมื่อวันนี้ข้าอารมณ์ดี ข้าก็จะรับข้อเสนอของเจ้าแล้วสู้กัน"
L39_1.m_Talk_THA = L40_1
L40_1 = "Tốt thôi. Vì hôm nay ta đang vui, ta sẽ chấp nhận lời mời của ngươi và chiến đấu."
L39_1.m_Talk_VTN = L40_1
L40_1 = "好。今天我心情好，就答应你的决斗请求了。"
L39_1.m_Talk_SCN = L40_1
L40_1 = "Nun gut. Da ich heute gut gelaunt bin, werde ich dein Angebot annehmen und gegen dich antreten."
L39_1.m_Talk_DEU = L40_1
L40_1 = "Très bien. Comme je suis de bonne humeur aujourd'hui, j'accepte ton offre. Battons-nous."
L39_1.m_Talk_FRA = L40_1
L40_1 = {}
