L41_1.m_Pos = "C"
L42_1 = "음…? 뭐지? 이 심상치 않은 기운은…?"
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "うむ……？　何だ？　この凄まじい気は……？"
L41_1.m_Talk_JPN = L42_1
L42_1 = "Mm...? What is this menacing energy...?"
L41_1.m_Talk_ENG = L42_1
L42_1 = "嗯…？怎麼回事？氛圍不太尋常…？"
L41_1.m_Talk_TWN = L42_1
L42_1 = "หืม...? พลังอันชั่วร้ายนี้นี่มันอะไรกัน...?"
L41_1.m_Talk_THA = L42_1
L42_1 = "Mm...? Nguồn năng lượng đe dọa này là sao...?"
L41_1.m_Talk_VTN = L42_1
L42_1 = "姆……？怎么回事？这不寻常的气氛……？"
L41_1.m_Talk_SCN = L42_1
L42_1 = "Hmm ...? Was ist das? Woher kommt denn diese bedrohliche Energie ...?"
L41_1.m_Talk_DEU = L42_1
L42_1 = "Mmh...? Cette aura...?"
L41_1.m_Talk_FRA = L42_1
