L42_1.m_CharStrID = L43_1
L42_1.m_Pos = "C"
L43_1 = "시종, 이 몸의 전용의자를 가져오거라."
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "僕よ、妾の椅子を持ってまいれ。"
L42_1.m_Talk_JPN = L43_1
L43_1 = "Servant, fetch me my chair."
L42_1.m_Talk_ENG = L43_1
L43_1 = "僕人，把我的專屬座椅拿來！"
L42_1.m_Talk_TWN = L43_1
L43_1 = "เจ้าข้ารับใช้ ไปเอาเก้าอี้ข้ามาซิ"
L42_1.m_Talk_THA = L43_1
L43_1 = "Này người hầu, đưa ghế cho ta."
L42_1.m_Talk_VTN = L43_1
L43_1 = "侍从，把本尊的专用椅子拿来。"
L42_1.m_Talk_SCN = L43_1
L43_1 = "Diener, hol mir meinen Stuhl."
L42_1.m_Talk_DEU = L43_1
L43_1 = "Va me chercher mon fauteuil, laquais."
