L45_1 = "哦吼吼吼，请您稍等片刻，我的主人。"
L44_1.m_Talk_SCN = L45_1
L45_1 = "Haha, wie Sie wünschen, Herrin."
L44_1.m_Talk_DEU = L45_1
L45_1 = "Tout de suite, Maîtresse."
