L2_1.m_Face = "UNIT_PRIDE"
L3_1 = "ROSARIA_NPC_FOOLSDAY_NULL"
L2_1.m_CharStrID = L3_1
L3_1 = "L"
L2_1.m_Pos = L3_1
L3_1 = "너 같은 녀석이 우주대악당이라고? 분수도 모르면서 감히 이 몸에게 도전장을 내밀다니. 가소롭구나."
L2_1.m_Talk_KOREA = L3_1
L2_1.m_fTalkTime = 0.03
L3_1 = "貴様のようなやつが宇宙大悪党じゃと？　身の程も知らずこの妾に挑戦するとは。笑わせる。"
L2_1.m_Talk_JPN = L3_1
L3_1 = "You call yourself the Atrocious Space Supervillain? With those noob controls? Pathetic."
L2_1.m_Talk_ENG = L3_1
L3_1 = "就你這點料也敢稱為宇宙大反派？不知好歹的傢伙還敢對我下戰帖，真是可笑。"
L2_1.m_Talk_TWN = L3_1
L3_1 = "เจ้าเรียกตัวเองว่าวายร้ายอวกาศใจโหดงั้นเหรอ? ด้วยการควบคุมอ่อนหัดแบบนั้นน่ะนะ? น่าสมเพชจริง"
L2_1.m_Talk_THA = L3_1
L3_1 = "Ngươi tự xưng là Siêu Phản Diện Không Gian Hung Tàn sao? Bằng mớ kỹ năng gà mờ này á? Thật là thảm hại."
L2_1.m_Talk_VTN = L3_1
L3_1 = "你这种实力还敢叫宇宙大恶棍？连自己几斤几两都不知道就敢挑战本尊。真是可笑。"
L2_1.m_Talk_SCN = L3_1
L3_1 = "Du wirst also grausame Weltraumschurkin genannt? Wie kannst du es wagen, mich herauszufordern? Wie erbärmlich."
L2_1.m_Talk_DEU = L3_1
L3_1 = "Et ça se prétend criminel de l'espace ? Avec des réflexes pareils ? Ne me fais pas rire."
L2_1.m_Talk_FRA = L3_1
L3_1 = {}
