L4_1 = "R"
L3_1.m_Pos = L4_1
L4_1 = "칫… 정복 첫날부터 이런 강적을 만나다니."
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "チッ……征服初日からこんな強敵に出会うなんて。"
L3_1.m_Talk_JPN = L4_1
L4_1 = "Tch... Just my luck running into a formidable foe on my first day of world domination."
L3_1.m_Talk_ENG = L4_1
L4_1 = "嘖…征服的第一天竟然就遇到強敵。"
L3_1.m_Talk_TWN = L4_1
L4_1 = "ชิ... แค่ดวงฉันมันพามาเจอคู่ต่อสู้ตัวตึงตั้งแต่วันแรกของการครองโลกหรอก"
L3_1.m_Talk_THA = L4_1
L4_1 = "Chậc…không ngờ lại gặp một kẻ thù đáng gờm ngay trong ngày đầu tiên xâm chiếm thế giới."
L3_1.m_Talk_VTN = L4_1
L4_1 = "切……没想到征服世界的第一天就遇到了这样强劲的对手。"
L3_1.m_Talk_SCN = L4_1
L4_1 = "Tzz ... Das kann ja auch nur mir passieren ... Gleich am ersten Tag der Eroberung auf eine so starke Gegnerin zu treffen."
L3_1.m_Talk_DEU = L4_1
L4_1 = "Tss... C'est bien ma veine, de tomber sur un ennemi pareil pour le premier jour de ma conquête de l'espace."
L3_1.m_Talk_FRA = L4_1
