L4_1.m_fTalkTime = 0.03
L5_1 = "このまま負けてられない！　もう一度勝負しようぜ！"
L4_1.m_Talk_JPN = L5_1
L5_1 = "I can’t give up just yet! I challenge you again!"
L4_1.m_Talk_ENG = L5_1
L5_1 = "我不能輸！再比一局！"
L4_1.m_Talk_TWN = L5_1
L5_1 = "ฉันยังยอมแพ้ไม่ได้หรอก! ฉันขอท้าเธออีกครั้ง!"
L4_1.m_Talk_THA = L5_1
L5_1 = "Tôi chưa thể bỏ cuộc được! Tôi thách đấu cô một lần nữa!"
L4_1.m_Talk_VTN = L5_1
L5_1 = "我不能就这样输掉！再来！"
L4_1.m_Talk_SCN = L5_1
L5_1 = "So darf es nicht enden! Ich fordere dich erneut heraus!"
L4_1.m_Talk_DEU = L5_1
L5_1 = "Mais ce n'est pas fini ! Je te défie à nouveau !"
L4_1.m_Talk_FRA = L5_1
