L8_1.m_Pos = "C"
L9_1 = "흥, 싱겁구나. 발끝에도 못 미치는 수준이라니."
L8_1.m_Talk_KOREA = L9_1
L8_1.m_fTalkTime = 0.03
L9_1 = "ふん、つまらぬ。足元にも及ばぬ実力じゃな。"
L8_1.m_Talk_JPN = L9_1
L9_1 = "Hmph, not even close. Try harder."
L8_1.m_Talk_ENG = L9_1
L9_1 = "哼，真無聊，你根本看不到我的車尾燈。"
L8_1.m_Talk_TWN = L9_1
L9_1 = "เฮอะ ไม่ได้ใกล้เคียงเลย พยายามกว่านี้อีก"
L8_1.m_Talk_THA = L9_1
L9_1 = "Hmph, còn chả chạm tới ngón tay ta. Cố lên tí nữa đi."
L8_1.m_Talk_VTN = L9_1
L9_1 = "哼，真无趣。你的实力也太不够看了。"
L8_1.m_Talk_SCN = L9_1
L9_1 = "Hmm, wie langweilig. Du schaffst es ja nicht einmal ansatzweise."
L8_1.m_Talk_DEU = L9_1
L9_1 = "Peuh, même pas en rêve. Il faudra faire mieux que ça pour me battre."
