L9_1.m_Pos = "C"
L10_1 = "자, 이제 마무리를 지어볼까?"
L9_1.m_Talk_KOREA = L10_1
L9_1.m_fTalkTime = 0.03
L10_1 = "さて、これでお終いにしようではないか。"
L9_1.m_Talk_JPN = L10_1
L10_1 = "Now, let’s put an end to this boring fight."
L9_1.m_Talk_ENG = L10_1
L10_1 = "我要結束囉？"
L9_1.m_Talk_TWN = L10_1
L10_1 = "ทีนี้ก็มาจบการต่อสู้อันน่าเบื่อนี่ซะทีเถอะ"
L9_1.m_Talk_THA = L10_1
L10_1 = "Nào, hãy chấm dứt cuộc đấu tay đôi nhàm chán này đi thôi."
L9_1.m_Talk_VTN = L10_1
L10_1 = "好了，接下来做个了断吧？"
L9_1.m_Talk_SCN = L10_1
L10_1 = "Sollen wir es jetzt langsam mal zu Ende bringen?"
L9_1.m_Talk_DEU = L10_1
L10_1 = "Bien. Il est temps de mettre fin à ce pathétique affrontement."
