L11_1.m_CharStrID = "KNIGHT_REPLACER_UNIT_FOOLSDAY"
L12_1 = "L"
L11_1.m_Pos = L12_1
L12_1 = "대체 뭐하는 괴물이야? 이 말도 안 되는 반응 속도는 또 뭐고?"
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "いったいどんなバケモンなんだよ？　この反応速度、あり得ないだろ？"
L11_1.m_Talk_JPN = L12_1
L12_1 = "That monster... What are those insane reflexes?"
L11_1.m_Talk_ENG = L12_1
L12_1 = "她到底是什麼怪物？反應速度快得要命是怎樣？"
L11_1.m_Talk_TWN = L12_1
L12_1 = "ยัยสัตว์ประหลาดนั่น... ปฏิกิริยาโต้ตอบบ้าบอขนาดนั้นมันอะไรกัน?"
L11_1.m_Talk_THA = L12_1
L12_1 = "Con quái vật đó...Mấy đòn phản công điên rồ ấy là sao chứ?"
L11_1.m_Talk_VTN = L12_1
L12_1 = "对面究竟是个什么怪物啊……这种可怕的反应速度又是怎么回事？"
L11_1.m_Talk_SCN = L12_1
L12_1 = "Was zur Hölle machst du? Was ist denn mit dieser lächerlichen Reaktionsgeschwindigkeit?"
L11_1.m_Talk_DEU = L12_1
L12_1 = "C'est quoi ces réflexes absurdes ? Quel monstre... !"
L11_1.m_Talk_FRA = L12_1
