L13_1 = "R"
L12_1.m_Pos = L13_1
L13_1 = "네 녀석이 무식하게 공격만 해서 계속 반격기에 당하고 있지 않느냐! 잡기! 잡기를 써라!"
L12_1.m_Talk_KOREA = L13_1
L12_1.m_fTalkTime = 0.03
L13_1 = "貴様が愚直な攻撃ばかりしているから返し技を食らうのだ！　投げ技だ！　投げ技を使え！"
L12_1.m_Talk_JPN = L13_1
L13_1 = "You're getting countered all the time because all you do is to attack! Grab! Use grab!"
L12_1.m_Talk_ENG = L13_1
L13_1 = "誰叫你只會一味地攻擊，當然會被反擊！要抓她啦！抓她！"
L12_1.m_Talk_TWN = L13_1
L13_1 = "เจ้าโดนสวนกลับตลอดเพราะเอาแต่โจมตีไง! จับทุ่มสิ! จับทุ่ม!"
L12_1.m_Talk_THA = L13_1
L13_1 = "Ngươi lúc nào cũng bị phản đòn vì ngươi chỉ có tấn công! Tóm lấy đi! Tóm đi nào!"
L12_1.m_Talk_VTN = L13_1
L13_1 = "你一味贸然攻击，只能一直被反击挨打！投技！用投技！"
L12_1.m_Talk_SCN = L13_1
L13_1 = "Du Spinnerin wirst ständig von Gegenangriffen getroffen, weil du einfach ohne nachzudenken angreifst! Nutz den Greifer!"
L12_1.m_Talk_DEU = L13_1
L13_1 = "Tes attaques sont trop prévisibles, elle a juste à guetter tes mouvements pour contre-attaquer ! Utilise des prises, bon sang !"
L12_1.m_Talk_FRA = L13_1
