L18_1 = "R"
L17_1.m_Pos = L18_1
L18_1 = "한심하구나. 그렇게 자신만만하게 도전 해놓고 처참하게 지다니."
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "情けない。あれほど自信満々に挑戦しておいて、惨めに負けるとはな。"
L17_1.m_Talk_JPN = L18_1
L18_1 = "Pitiful. Your confidence has plummeted to the ground."
L17_1.m_Talk_ENG = L18_1
L18_1 = "真是沒用，剛剛下戰帖時還那麼神氣，結果慘敗。"
L17_1.m_Talk_TWN = L18_1
L18_1 = "น่าสงสารจริง ความมั่นใจของเจ้าดิ่งลงพื้นเสียแล้ว"
L17_1.m_Talk_THA = L18_1
L18_1 = "Thật vô dụng. Sự tự tin của ngươi đã tụt xuống đáy rồi."
L17_1.m_Talk_VTN = L18_1
L18_1 = "真是没用。之前还信誓旦旦地，结果却输得这么惨。"
L17_1.m_Talk_SCN = L18_1
L18_1 = "So erbärmlich. Wie kannst du es nur wagen, so selbstbewusst jemanden herauszufordern, nur um dann so jämmerlich zu verlieren?"
L17_1.m_Talk_DEU = L18_1
L18_1 = "Pitoyable. Où est passée ton assurance de tout à l'heure ?"
L17_1.m_Talk_FRA = L18_1
