L19_1.m_Talk_TWN = L20_1
L20_1 = "แต่อย่างน้อยข้าก็ชนะยกหนึ่งนะ ไม่เหมือนเจ้า"
L19_1.m_Talk_THA = L20_1
L20_1 = "Ít nhất thì ta đã thắng một lượt, không giống ngươi."
