L27_1.m_fTalkTime = 0.03
L28_1 = "悪党という看板はただの飾りか？　道行くサラリーマンの財布でもかっさらうのだ！"
L27_1.m_Talk_JPN = L28_1
L28_1 = "You’re a villain, are you not? Go rob some bypassing workers or something!"
L27_1.m_Talk_ENG = L28_1
L28_1 = "你反派是當假的嗎？不會隨便抓個路人搶劫他的錢包嗎！"
L27_1.m_Talk_TWN = L28_1
L28_1 = "พวกเจ้าเป็นวายร้ายไม่ใช่เหรอ? ก็ไปปล้นคนงานที่ผ่านไปผ่านมาหรืออะไรซะสิ?"
L27_1.m_Talk_THA = L28_1
L28_1 = "Ngươi có phải kẻ phản diện không thế? Hãy đi cướp của vài tên qua đường hay làm gì đi chứ!"
L27_1.m_Talk_VTN = L28_1
