L31_1 = "FX_CUTSCEN_FOOTSTEP_RUNNING_02"
L30_1.m_StartFXSoundName = L31_1
L30_1.m_CharStrID = "KNIGHT_REPLACER_UNIT_FOOLSDAY"
L31_1 = "C_L_M_I"
L30_1.m_Pos = L31_1
L31_1 = "어이! 네 녀석! 지갑에 든 돈을 내놔!"
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "おい！　そこの雑魚！　財布の金を出せ！"
L30_1.m_Talk_JPN = L31_1
L31_1 = "Hey! You! Hand over your money!"
L30_1.m_Talk_ENG = L31_1
L31_1 = "喂！小子！把錢包裡的錢交出來！"
L30_1.m_Talk_TWN = L31_1
L31_1 = "นี่! แก! ส่งเงินมานะ!"
L30_1.m_Talk_THA = L31_1
L31_1 = "Này! Mi đấy! Nôn tiền ra đây!"
L30_1.m_Talk_VTN = L31_1
L31_1 = "喂！就是你！把钱包里的钱都交出来！"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Hey! Du! Gib mir dein Geld!"
L30_1.m_Talk_DEU = L31_1
L31_1 = "Hé ! Toi, là-bas ! La bourse ou la vie !"
L30_1.m_Talk_FRA = L31_1
