L33_1 = "FOOLSDAY_PART2_NODE1_EPILOGUE@182#Talk"
L32_1.m_CutScenKey_Talk = L33_1
L33_1 = 182
L32_1.m_CutScenProcessKey = L33_1
L32_1.m_CutScenID = 2700117
L32_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L32_1.m_bWaitClick = true
L32_1.m_fWaitTime = 0
L33_1 = "JOO_SHI_YOON_NPC_FOOLSDAY_NULL"
L32_1.m_CharStrID = L33_1
L33_1 = "R"
L32_1.m_Pos = L33_1
L33_1 = "이야, 죄송해요. 어제 스승님 회식비를 대신 내느라 탈탈 털려서 말이죠."
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "いやぁ、すみません。昨日師匠の代わりに会食代を払ったので、一文無しなんですよ。"
L32_1.m_Talk_JPN = L33_1
L33_1 = "Oh, my apologies. I’m broke because I had to pay for Master’s dinner."
L32_1.m_Talk_ENG = L33_1
L33_1 = "哎呀，真抱歉，我昨天代墊師傅的聚餐費，現在錢包都空咧。"
L32_1.m_Talk_TWN = L33_1
L33_1 = "โอ๊ะ ขออภัยด้วยครับ ผมถังแตกเพราะไปจ่ายค่าอาหารให้อาจารย์หมดแล้วครับ"
L32_1.m_Talk_THA = L33_1
L33_1 = "Ồ,xin lỗi. Tôi phá sản rồi vì tôi cứ phải trả tiền ăn cho Sếp mãi."
L32_1.m_Talk_VTN = L33_1
L33_1 = "哎呀啊，抱歉。昨天因为要替老师垫聚餐费，我的钱包已经空空如也了。"
L32_1.m_Talk_SCN = L33_1
L33_1 = "Oh, Entschuldigung. Ich bin pleite, weil ich die Mahlzeiten der Meisterin bezahlen musste."
L32_1.m_Talk_DEU = L33_1
L33_1 = "Désolé, mais je n'ai rien à vous donner. J'ai du payer pour le repas de collègues avec le Maître hier, j'ai plus un rond..."
L32_1.m_Talk_FRA = L33_1
L33_1 = {}
L34_1 = "FOOLSDAY_PART2_NODE1_EPILOGUE@183#Talk"
L33_1.m_CutScenKey_Talk = L34_1
L34_1 = 183
L33_1.m_CutScenProcessKey = L34_1
L33_1.m_CutScenID = 2700117
L33_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L33_1.m_bWaitClick = true
L33_1.m_fWaitTime = 0
L33_1.m_Face = "UNIT_SERIOUS"
L33_1.m_CharStrID = "KNIGHT_REPLACER_UNIT_FOOLSDAY"
L34_1 = "L"
L33_1.m_Pos = L34_1
L34_1 = "뒤져서 나오면 동전 하나에 한 대씩이다!"
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "ポケットに１円玉でも入ってたら、１円につき一発だからな！"
L33_1.m_Talk_JPN = L34_1
L34_1 = "It’s gonna be one blow for each coin we get out of you!"
L33_1.m_Talk_ENG = L34_1
L34_1 = "要是被我搜到零錢，一塊打一下！"
L33_1.m_Talk_TWN = L34_1
L34_1 = "แม่จะอัดให้คายออกมาหมัดละเหรียญเลย!"
L33_1.m_Talk_THA = L34_1
L34_1 = "Cứ một xu mà bọn ta tìm thấy trên người mi thì ăn một đấm đấy!"
L33_1.m_Talk_VTN = L34_1
L34_1 = "什么！小心别让我翻到，翻到的话一个硬币算一拳！"
L33_1.m_Talk_SCN = L34_1
L34_1 = "Ich hau dir für jede einzelne Münze, die wir dir aus den Taschen ziehen, eine runter!"
L33_1.m_Talk_DEU = L34_1
L34_1 = "Vraiment ? Dans ce cas, je te mets un coup pour chaque pièce que j'arriverai à t'extorquer !"
L33_1.m_Talk_FRA = L34_1
L34_1 = {}
