L36_1 = "UNIT_LAUGH"
L35_1.m_Face = L36_1
L36_1 = "JOO_SHI_YOON_NPC_FOOLSDAY_NULL"
L35_1.m_CharStrID = L36_1
L36_1 = "R"
L35_1.m_Pos = L36_1
L36_1 = "아, 전 또 큰돈을 원하는 강도분인 줄 알았지 뭐예요?"
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "ああ、てっきり大金が欲しい強盗の方かと思いました。"
L35_1.m_Talk_JPN = L36_1
L36_1 = "Oh, I thought you wanted a large amount of money."
L35_1.m_Talk_ENG = L36_1
L36_1 = "喔～我還以為是要搶劫大筆的強盜呢。"
L35_1.m_Talk_TWN = L36_1
L36_1 = "อ๋อ ผมก็นึกว่าคุณอยากได้เงินเยอะๆ ซะอีก"
L35_1.m_Talk_THA = L36_1
L36_1 = "Ồ, tôi cứ tưởng các cô cần nhiều tiền chứ."
L35_1.m_Talk_VTN = L36_1
L36_1 = "啊，我还以为你想要大钱呢？"
L35_1.m_Talk_SCN = L36_1
L36_1 = "Oh, ich dachte, Sie wären eine Räuberin, die es auf eine große Menge Geld abgesehen hat."
L35_1.m_Talk_DEU = L36_1
L36_1 = "Oh, je pensais que vous vouliez une somme plus... conséquente, moi."
L35_1.m_Talk_FRA = L36_1
L36_1 = {}
L37_1 = "FOOLSDAY_PART2_NODE1_EPILOGUE@186#Talk"
L36_1.m_CutScenKey_Talk = L37_1
L37_1 = 186
L36_1.m_CutScenProcessKey = L37_1
L36_1.m_CutScenID = 2700117
L36_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L36_1.m_bWaitClick = true
L36_1.m_fWaitTime = 0
L37_1 = "JOO_SHI_YOON_NPC_FOOLSDAY_NULL"
L36_1.m_CharStrID = L37_1
L37_1 = "R"
L36_1.m_Pos = L37_1
L37_1 = "동전이라면 몇 개 남은 게 있습니다. 여기요."
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "小銭ならいくらか持ってますよ。どうぞ。"
L36_1.m_Talk_JPN = L37_1
L37_1 = "If it’s coins you’re asking for, here. I have a few left."
L36_1.m_Talk_ENG = L37_1
L37_1 = "零錢的話我這是有一點，拿去吧。"
L36_1.m_Talk_TWN = L37_1
L37_1 = "ถ้าเหรียญละก็ เอานี่สิครับ ผมมีเหลืออยู่"
L36_1.m_Talk_THA = L37_1
L37_1 = "Nếu các cô chỉ cần vài xu thì đây, tôi còn vài xu."
L36_1.m_Talk_VTN = L37_1
L37_1 = "硬币的话应该还剩下几个，给你。"
L36_1.m_Talk_SCN = L37_1
L37_1 = "Wenn es um Münzen geht, dann habe ich noch ein paar übrig. Bitte schön."
L36_1.m_Talk_DEU = L37_1
L37_1 = "Si ce sont des pièces qu'il vous faut, tenez. Ça tombe bien, il m'en reste justement quelques unes."
L36_1.m_Talk_FRA = L37_1
