L40_1.m_CutScenKey_Talk = L41_1
L41_1 = 190
L40_1.m_CutScenProcessKey = L41_1
L40_1.m_CutScenID = 2700117
L40_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L40_1.m_bWaitClick = true
L40_1.m_fWaitTime = 0
L40_1.m_Face = "UNIT_SERIOUS"
L40_1.m_CharStrID = "OROCHI_JAPAN_NULL_FOOLSDAY"
L40_1.m_Pos = "C"
L41_1 = "인간을 갈취하라고 했더니 구걸따윌 하고 있는 것이냐? 정말이지 악당의 수치로구나."
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "恐喝しろと言ったのに物乞いをしてるのか？　まったく、悪党の恥だな。"
L40_1.m_Talk_JPN = L41_1
L41_1 = "I told you to rob humans, not beg. You truly are a disgrace to us villains."
L40_1.m_Talk_ENG = L41_1
L41_1 = "我叫你搶劫人類，結果你卻去向人類乞討？你真的是反派之恥！"
L40_1.m_Talk_TWN = L41_1
L41_1 = "ข้าบอกให้เจ้าไปปล้นเอาจากมนุษย์ ไม่ใช่ไปขอ เจ้านี่คือความเสื่อมเสียของชาววายร้ายเราจริงๆ"
L40_1.m_Talk_THA = L41_1
L41_1 = "Ta đã bảo ngươi là cướp, chứ đâu phải ăn mày. Ngươi thực sự là nỗi ô nhục với những kẻ phản diện như chúng ta."
L40_1.m_Talk_VTN = L41_1
L41_1 = "哈……我让你勒索他们，没让你去讨饭。你可真是反派的耻辱。"
L40_1.m_Talk_SCN = L41_1
L41_1 = "Ich habe dir gesagt, du sollst von Menschen stehlen und sie nicht anbetteln! Du bist wirklich eine Schande für uns Schurken."
L40_1.m_Talk_DEU = L41_1
L41_1 = "Je t'ai dit de leur faire les poches, pas de jouer à la mendiante... Tu es vraiment la risée des criminels de l'espace, toi."
L40_1.m_Talk_FRA = L41_1
L41_1 = {}
