L43_1 = "L_F_C"
L42_1.m_Pos = L43_1
L43_1 = "그래서 얼마나 받았지?"
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "それで、いくらもらったんだ？"
L42_1.m_Talk_JPN = L43_1
L43_1 = "So how much did you get?"
L42_1.m_Talk_ENG = L43_1
L43_1 = "怎麼樣？拿到多少？"
L42_1.m_Talk_TWN = L43_1
L43_1 = "ว่าแต่ได้มาเท่าไหร่ล่ะ?"
L42_1.m_Talk_THA = L43_1
L43_1 = "Vậy ngươi lấy được bao nhiêu?"
L42_1.m_Talk_VTN = L43_1
L43_1 = "所以你拿到了多少钱？"
L42_1.m_Talk_SCN = L43_1
L43_1 = "Wie viel hast du bekommen?"
L42_1.m_Talk_DEU = L43_1
L43_1 = "Bon, combien il nous reste ?"
L42_1.m_Talk_FRA = L43_1
L43_1 = {}
L44_1 = "FOOLSDAY_PART2_NODE1_EPILOGUE@193#Talk"
L43_1.m_CutScenKey_Talk = L44_1
L44_1 = 193
L43_1.m_CutScenProcessKey = L44_1
L43_1.m_CutScenID = 2700117
L43_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L43_1.m_bWaitClick = true
L43_1.m_fWaitTime = 0
L43_1.m_CharStrID = "KNIGHT_REPLACER_UNIT_FOOLSDAY"
L44_1 = "R_D"
L43_1.m_Pos = L44_1
L44_1 = "이 정도면 다섯 판은 더 할 수 있겠는데?"
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "このくらいならあと5回はやれそうだぞ。"
L43_1.m_Talk_JPN = L44_1
L44_1 = "I think this would get us about five more sets!"
L43_1.m_Talk_ENG = L44_1
L44_1 = "這些錢應該可以再玩五局吧？"
L43_1.m_Talk_TWN = L44_1
L44_1 = "ฉันว่าเราเล่นได้อีกห้าครั้งเลย!"
L43_1.m_Talk_THA = L44_1
L44_1 = "Tôi nghĩ là được thêm năm lần nữa!"
L43_1.m_Talk_VTN = L44_1
L44_1 = "这些应该还能再玩五把？"
L43_1.m_Talk_SCN = L44_1
L44_1 = "Ich denke, damit könnten wir noch fünf weitere Runden spielen!"
L43_1.m_Talk_DEU = L44_1
L44_1 = "De quoi faire environ... cinq parties supplémentaires !"
L43_1.m_Talk_FRA = L44_1
