L46_1 = "FOOLSDAY_PART2_NODE1_EPILOGUE@195#Talk"
L45_1.m_CutScenKey_Talk = L46_1
L46_1 = 195
L45_1.m_CutScenProcessKey = L46_1
L45_1.m_CutScenID = 2700117
L45_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L45_1.m_bWaitClick = true
L45_1.m_fWaitTime = 0
L46_1 = "UNIT_LAUGH"
L45_1.m_Face = L46_1
L46_1 = "JOO_SHI_YOON_NPC_FOOLSDAY_NULL"
L45_1.m_CharStrID = L46_1
L46_1 = "C_R_M_I"
L45_1.m_Pos = L46_1
L46_1 = "오, 격투게임이네요? 저도 구경해도 되죠?"
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "おお、格闘ゲームですね。僕も見てていいですか？"
L45_1.m_Talk_JPN = L46_1
L46_1 = "Oh, a fighting game? May I watch?"
L45_1.m_Talk_ENG = L46_1
L46_1 = "喔，是格鬥遊戲欸，我可以在旁邊看吧？"
L45_1.m_Talk_TWN = L46_1
L46_1 = "โอ๊ะ เกมต่อสู้เหรอครับ? ผมขอดูได้มั้ย?"
L45_1.m_Talk_THA = L46_1
L46_1 = "Ồ, trò chơi đánh nhau à? Cho tôi xem được chứ?"
L45_1.m_Talk_VTN = L46_1
L46_1 = "噢，是格斗游戏啊？我也能看吧？"
L45_1.m_Talk_SCN = L46_1
L46_1 = "Oh, ein Wettkampf? Dürfte ich auch zuschauen?"
L45_1.m_Talk_DEU = L46_1
L46_1 = "Oh, un jeu de combat ? Je peux regarder ?"
L45_1.m_Talk_FRA = L46_1
L46_1 = {}
L47_1 = "FOOLSDAY_PART2_NODE1_EPILOGUE@196#Talk"
L46_1.m_CutScenKey_Talk = L47_1
L47_1 = 196
L46_1.m_CutScenProcessKey = L47_1
L46_1.m_CutScenID = 2700117
L46_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L46_1.m_bWaitClick = true
L46_1.m_fWaitTime = 0
L46_1.m_Face = "UNIT_PRIDE"
L46_1.m_CharStrID = "KNIGHT_REPLACER_UNIT_FOOLSDAY"
L46_1.m_Pos = "C"
L47_1 = "흥, 물론이지. 이번에야말로 이길 테니 네 녀석도 잘 봐두라고."
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "ふん、もちろんだ。今度こそ勝つからてめえもよく見とけ。"
L46_1.m_Talk_JPN = L47_1
L47_1 = "Hmph, of course. I’ll win for sure this time. You just wait and see."
L46_1.m_Talk_ENG = L47_1
L47_1 = "哼，當然，這次我一定會贏的，睜大你的眼睛看好！"
L46_1.m_Talk_TWN = L47_1
L47_1 = "หืม ได้อยู่แล้วสิ คราวนี้ฉันชนะแน่ นายอยู่เฉยๆ ดูไปแล้วกัน"
L46_1.m_Talk_THA = L47_1
L47_1 = "Hmph, dĩ nhiên. Lần này tôi thắng là cái chắc. Cứ chờ mà xem."
L46_1.m_Talk_VTN = L47_1
L47_1 = "哼，当然。这次我一定会赢，你也给我看好喽。"
L46_1.m_Talk_SCN = L47_1
L47_1 = "Hmm, natürlich. Schau gut zu, da ich dieses Mal mit Sicherheit gewinnen werde."
L46_1.m_Talk_DEU = L47_1
L47_1 = "Bien entendu. Cette fois-ci, je vais gagner à coup sûr. Installe-toi et profite du spectacle."
L46_1.m_Talk_FRA = L47_1
L47_1 = {}
L48_1 = "FOOLSDAY_PART2_NODE1_EPILOGUE@197#Talk"
L47_1.m_CutScenKey_Talk = L48_1
L48_1 = 197
L47_1.m_CutScenProcessKey = L48_1
L47_1.m_CutScenID = 2700117
L47_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L47_1.m_bWaitClick = true
L47_1.m_fWaitTime = 0
L48_1 = "ROSARIA_NPC_FOOLSDAY_NULL"
L47_1.m_CharStrID = L48_1
L47_1.m_Pos = "C"
L48_1 = "겨우 다섯 판으로? 어차피 또 질 게 뻔한데 그 정도로 연습이나 되겠어?"
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L48_1 = "たった5回じゃと？　どうせ負けるだろうに、その程度では練習にもならぬわ。"
L47_1.m_Talk_JPN = L48_1
L48_1 = "With only five rounds? I doubt that’ll do you any good. You’re going to lose anyway."
L47_1.m_Talk_ENG = L48_1
L48_1 = "才五局？反正你一定又會輸，就當作是練習吧？"
L47_1.m_Talk_TWN = L48_1
L48_1 = "แค่ห้ารอบเหรอ? ข้าสงสัยจริงว่าเจ้าจะทำอะไรได้ ยังไงเจ้าก็แพ้อยู่ดี"
L47_1.m_Talk_THA = L48_1
L48_1 = "Chỉ được năm lượt thôi sao? Ta chẳng thấy ngươi có cơ may nào cả. Dù sao ngươi vẫn sẽ thua thôi."
L47_1.m_Talk_VTN = L48_1
L48_1 = "五把？反正肯定会输，就这几把都不够你们练习吧？"
L47_1.m_Talk_SCN = L48_1
L48_1 = "Mit nur fünf Runden? Du wirst sowieso wieder verlieren, also sieh es lieber als Übung an."
L47_1.m_Talk_DEU = L48_1
L48_1 = "En seulement cinq parties ? Pas sûr que ça te serve à grand chose puisque tu vas perdre, de toute façon."
L47_1.m_Talk_FRA = L48_1
L48_1 = {}
L49_1 = "FOOLSDAY_PART2_NODE1_EPILOGUE@198#Talk"
L48_1.m_CutScenKey_Talk = L49_1
L49_1 = 198
L48_1.m_CutScenProcessKey = L49_1
L48_1.m_CutScenID = 2700117
L48_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L48_1.m_bWaitClick = true
