L50_1 = "FOOLSDAY_PART2_NODE1_EPILOGUE@199#Talk"
L49_1.m_CutScenKey_Talk = L50_1
L50_1 = 199
L49_1.m_CutScenProcessKey = L50_1
L49_1.m_CutScenID = 2700117
L49_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L49_1.m_bWaitClick = true
L49_1.m_fWaitTime = 0
L49_1.m_Face = "UNIT_PRIDE"
L50_1 = "ROSARIA_NPC_FOOLSDAY_NULL"
L49_1.m_CharStrID = L50_1
L49_1.m_Pos = "C"
L50_1 = "너네, 기본기는 충실한데 테크닉이 영 부족해."
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "其方たち、基本スキルは十分じゃがテクニックがまったく足りぬ。"
L49_1.m_Talk_JPN = L50_1
L50_1 = "You two, your controls are good but you lack technique."
L49_1.m_Talk_ENG = L50_1
L50_1 = "你這傢伙，基本功很扎實，只是技巧不足。"
L49_1.m_Talk_TWN = L50_1
L50_1 = "เจ้าสองคนน่ะ การควบคุมดีนะ แต่ขาดเทคนิค"
L49_1.m_Talk_THA = L50_1
L50_1 = "Này hai người, khả năng kiểm soát của các ngươi thì tốt nhưng kỹ năng thì tệ quá."
L49_1.m_Talk_VTN = L50_1
L50_1 = "你们两个，控制人物的基本功还很扎实，但完全不懂连招技巧嘛。"
L49_1.m_Talk_SCN = L50_1
L50_1 = "Du verfügst über die Grundlagen, aber es mangelt dir an Technik."
L49_1.m_Talk_DEU = L50_1
L50_1 = "Vous avez de bons réflexes, toutes les deux, mais vous manquez de technique."
L49_1.m_Talk_FRA = L50_1
L50_1 = {}
L51_1 = "FOOLSDAY_PART2_NODE1_EPILOGUE@200#Talk"
L50_1.m_CutScenKey_Talk = L51_1
L51_1 = 200
L50_1.m_CutScenProcessKey = L51_1
L50_1.m_CutScenID = 2700117
L50_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L50_1.m_bWaitClick = true
L50_1.m_fWaitTime = 0
L51_1 = "ROSARIA_NPC_FOOLSDAY_NULL"
L50_1.m_CharStrID = L51_1
L50_1.m_Pos = "C"
L51_1 = "이대로 계속하면 나도 시시하니까, 내가 좀 가르쳐 줄까?"
L50_1.m_Talk_KOREA = L51_1
L50_1.m_fTalkTime = 0.03
L51_1 = "このまま続けても退屈じゃ。妾が教えてやろうか？"
L50_1.m_Talk_JPN = L51_1
L51_1 = "Why don’t I teach you as we go? Winning all the time isn’t fun, you know."
L50_1.m_Talk_ENG = L51_1
L51_1 = "再贏下去也沒意思，要我教你兩招嗎？"
L50_1.m_Talk_TWN = L51_1
L51_1 = "ทำไมไม่เล่นกันไปแล้วก็ให้ข้าสอนไปล่ะ? ชนะตลอดมันไม่สนุกนะรู้มั้ย"
L50_1.m_Talk_THA = L51_1
L51_1 = "Hay để ta dạy kèm cho nhé? Lúc nào cũng thắng thì có vui gì đâu."
L50_1.m_Talk_VTN = L51_1
L51_1 = "这样没有进步我也会很无聊，用不用我教教你们？"
L50_1.m_Talk_SCN = L51_1
L51_1 = "Wenn du so weitermachst, wird mir auch langweilig. Wie wäre es also, wenn ich es dir ein bisschen beibringe?"
L50_1.m_Talk_DEU = L51_1
L51_1 = "Et si je vous montrais un peu comment on fait ? Ça m'amuse pas vraiment, de gagner tout le temps."
L50_1.m_Talk_FRA = L51_1
