L2_1.m_CharStrID = L3_1
L2_1.m_Pos = "C"
L3_1 = "그래, 마침 달콤한 것도 당기던 참이니 자리를 옮기는 게 좋겠구나."
L2_1.m_Talk_KOREA = L3_1
L2_1.m_fTalkTime = 0.03
L3_1 = "うむ、ちょうど甘いものが欲しかったところじゃ。場所を移そう。"
L2_1.m_Talk_JPN = L3_1
L3_1 = "Yes, I was craving something sweet anyway... Let us move to another place."
L2_1.m_Talk_ENG = L3_1
L3_1 = "嗯嗯，正好我想吃甜點，就移動一下位置吧。"
L2_1.m_Talk_TWN = L3_1
L3_1 = "พูดจริง ว่าแต่ ข้าอยากกินอะไรหวานๆ แล้วนะสิ... ไปที่อื่นกันเถอะ"
L2_1.m_Talk_THA = L3_1
L3_1 = "Ừ, ta đang thèm cái gì đó ngọt ngọt đây...Hay chúng ta chuyển tới nơi khác nhé."
L2_1.m_Talk_VTN = L3_1
L3_1 = "是啊，正好我想吃甜品了，我们换个地方聊吧。"
L2_1.m_Talk_SCN = L3_1
L3_1 = "Ja, ich habe gerade Lust auf etwas Süßes bekommen ... Lass uns zu einem anderen Ort weiterziehen."
L2_1.m_Talk_DEU = L3_1
L3_1 = "Oui. Allons faire une pause autre part, j'ai besoin de quelque chose de sucré."
L2_1.m_Talk_FRA = L3_1
