L7_1.m_CutScenID = 2700117
L7_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L7_1.m_bWaitClick = true
L7_1.m_fWaitTime = 0
L8_1 = "UNIT_LAUGH"
L7_1.m_Face = L8_1
L7_1.m_CharStrID = "KNIGHT_REPLACER_UNIT_FOOLSDAY"
L8_1 = "L"
L7_1.m_Pos = L8_1
L8_1 = "그래서, 네 상사는 경찰을 보자마자 그대로 창문을 깨고 달아났단 말이지?"
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "それで、てめえの上司は警察を見るなりそのまま窓を割って逃げたのか？"
L7_1.m_Talk_JPN = L8_1
L8_1 = "So, your boss fled through the window as soon as the cops came in?"
L7_1.m_Talk_ENG = L8_1
L8_1 = "你說你上司一看到警察就破窗而出嗎？"
L7_1.m_Talk_TWN = L8_1
L8_1 = "แล้วพอตำรวจมา บอสนายก็โดดทะลุหน้าต่างออกไปเลยเหรอ?"
L7_1.m_Talk_THA = L8_1
L8_1 = "Vậy là sếp của cậu chạy trốn bằng cửa sổ ngay khi cảnh sát ập vào sao?"
L7_1.m_Talk_VTN = L8_1
L8_1 = "所以，你的上司一见到警察就直接破窗逃跑了吗？"
L7_1.m_Talk_SCN = L8_1
L8_1 = "Also, deine Vorgesetze ist durch das Fenster geflohen, sobald die Polizisten hereingekommen sind?"
L7_1.m_Talk_DEU = L8_1
L8_1 = "Donc ta boss s'est enfuie par la fenêtre dès l'instant où les flics sont entrés ?"
L7_1.m_Talk_FRA = L8_1
L8_1 = {}
L9_1 = "FOOLSDAY_PART2_NODE1_EPILOGUE@208#Talk"
L8_1.m_CutScenKey_Talk = L9_1
L9_1 = 208
L8_1.m_CutScenProcessKey = L9_1
L8_1.m_CutScenID = 2700117
L8_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L8_1.m_bWaitClick = true
L8_1.m_fWaitTime = 0
L9_1 = "JOO_SHI_YOON_NPC_FOOLSDAY_NULL"
L8_1.m_CharStrID = L9_1
L9_1 = "R"
L8_1.m_Pos = L9_1
L9_1 = "뭐, 그때는 저 혼자 시말서를 쓰느라 고생했지만 돌이켜보면 다 추억이죠."
L8_1.m_Talk_KOREA = L9_1
L8_1.m_fTalkTime = 0.03
L9_1 = "まあ、その時は僕一人で始末書を書くのに苦労したんですけど、今考えるといい思い出ですよ。"
L8_1.m_Talk_JPN = L9_1
L9_1 = "Yes, well... I went through a lot of trouble writing the letter of explanation on my own, but it’s all passed now."
L8_1.m_Talk_ENG = L9_1
L9_1 = "那時候我寫悔過書寫得多辛苦，不過現在回想起來都是回憶呢。"
L8_1.m_Talk_TWN = L9_1
L9_1 = "ครับ คือ... ผมก็ลำบากมากกับการเขียนจดหมายอธิบายเอง แต่ตอนนี้ก็ผ่านมาได้แล้วล่ะครับ"
L8_1.m_Talk_THA = L9_1
L9_1 = "Ừ đấy...Tôi đã gặp rất nhiều rắc rối khi tự viết thư giải thích, nhưng giờ mọi thứ qua cả rồi."
L8_1.m_Talk_VTN = L9_1
L9_1 = "啊哈哈哈，那时候虽然我一个人写检讨很累，但如今回想起来都是满满的回忆呀。"
L8_1.m_Talk_SCN = L9_1
L9_1 = "Nun ja ... Damals fiel es mir schwer, alleine den Bericht diesbezüglich zu verfassen, aber rückblickend sind es nun alles Erinnerungen."
L8_1.m_Talk_DEU = L9_1
L9_1 = "Oui, j'ai du me débrouiller seul pour la lettre d'excuse, autant dire que j'ai passé un sale quart d'heure. Enfin, c'est du passé maintenant."
L8_1.m_Talk_FRA = L9_1
L9_1 = {}
