L11_1 = "FOOLSDAY_PART2_NODE1_EPILOGUE@210#Talk"
L10_1.m_CutScenKey_Talk = L11_1
L11_1 = 210
L10_1.m_CutScenProcessKey = L11_1
L10_1.m_CutScenID = 2700117
L10_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L10_1.m_bWaitClick = true
L10_1.m_fWaitTime = 0
L11_1 = "UNIT_LAUGH"
L10_1.m_Face = L11_1
L11_1 = "ROSARIA_NPC_FOOLSDAY_NULL"
L10_1.m_CharStrID = L11_1
L10_1.m_Pos = "C"
L11_1 = "그런 상사를 두면 회사를 관둘 법도 한데, 저 녀석도 참 보살이라니까."
L10_1.m_Talk_KOREA = L11_1
L10_1.m_fTalkTime = 0.03
L11_1 = "そういう上司がいると会社をやめてもおかしくなかろうに、其方もたいがい人がいい。"
L10_1.m_Talk_JPN = L11_1
L11_1 = "With a boss like that, I would have quit my job long ago. He has a heart of gold, that boy."
L10_1.m_Talk_ENG = L11_1
L11_1 = "有那種上司應該要辭職吧，你這傢伙還真是不記仇。"
L10_1.m_Talk_TWN = L11_1
L11_1 = "มีบอสแบบนั้น เป็นข้าคงลาออกไปนานแล้ว จิตใจดีงามจริงๆ เจ้าเด็กนั่น"
L10_1.m_Talk_THA = L11_1
L11_1 = "Sếp như thế, thì ta bỏ việc lâu rồi. Cậu ta quả là bồ tát sống đấy."
L10_1.m_Talk_VTN = L11_1
L11_1 = "遇到那种上司，很多人都应该会辞职吧，你也真是个老实巴交的。"
L10_1.m_Talk_SCN = L11_1
L11_1 = "Bei einer solchen Vorgesetzen hätte ich meinen Job schon vor langer Zeit an den Nagel gehängt. Er hat wirklich ein Herz aus Gold, dieser Junge."
L10_1.m_Talk_DEU = L11_1
L11_1 = "À ta place, j'aurais changé de job depuis longtemps. Tu es un vrai cœur d'or, toi !"
L10_1.m_Talk_FRA = L11_1
L11_1 = {}
L12_1 = "FOOLSDAY_PART2_NODE1_EPILOGUE@211#Talk"
L11_1.m_CutScenKey_Talk = L12_1
L12_1 = 211
L11_1.m_CutScenProcessKey = L12_1
L11_1.m_CutScenID = 2700117
L11_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L11_1.m_bWaitClick = true
L11_1.m_fWaitTime = 0
L12_1 = "UNIT_LAUGH"
L11_1.m_Face = L12_1
L12_1 = "JOO_SHI_YOON_NPC_FOOLSDAY_NULL"
L11_1.m_CharStrID = L12_1
L11_1.m_Pos = "C"
L12_1 = "하하, 스승님이 겉으론 무정해 보여도 정이 많으신 분이라서요."
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "はは、師匠は無情に見えても、情が深い方なんで。"
L11_1.m_Talk_JPN = L12_1
L12_1 = "Ha ha, Master might sound cold and heartless, but she is actually very caring."
L11_1.m_Talk_ENG = L12_1
L12_1 = "哈哈，師傅雖然看似無情，但其實很重感情的。"
L11_1.m_Talk_TWN = L12_1
L12_1 = "ฮ่าฮ่า ฟังดูอาจเหมือนอาจารย์เหมือนเย็นชาไม่มีหัวใจ แต่จริงๆ เธอใส่ใจคนอื่นมากนะครับ"
L11_1.m_Talk_THA = L12_1
L12_1 = "Ha ha, Sếp có thể hơi lạnh lùng và vô tâm, nhưng cô ấy thực ra rất quan tâm người khác."
L11_1.m_Talk_VTN = L12_1
L12_1 = "哈哈，老师虽然表面看起来很冷漠，但其实是个很重情义的人。"
L11_1.m_Talk_SCN = L12_1
L12_1 = "Haha, die Meisterin mag zwar kalt und herzlos klingen, aber sie ist eigentlich sehr fürsorglich."
L11_1.m_Talk_DEU = L12_1
L12_1 = "Ha ha, le Maître a un petit côté rigide c'est vrai, mais elle a bon fond."
L11_1.m_Talk_FRA = L12_1
L12_1 = {}
L13_1 = "FOOLSDAY_PART2_NODE1_EPILOGUE@212#Talk"
L12_1.m_CutScenKey_Talk = L13_1
L13_1 = 212
L12_1.m_CutScenProcessKey = L13_1
L12_1.m_CutScenID = 2700117
L12_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L12_1.m_bWaitClick = true
L12_1.m_fWaitTime = 0
L13_1 = "JOO_SHI_YOON_NPC_FOOLSDAY_NULL"
L12_1.m_CharStrID = L13_1
L12_1.m_Pos = "C"
L13_1 = "아마 제가 관두고 사라진다면 우주 끝까지라도 절 잡으러 오실 겁니다."
L12_1.m_Talk_KOREA = L13_1
L12_1.m_fTalkTime = 0.03
L13_1 = "多分僕が仕事を辞めて消えたら、宇宙の果てまで捕まえに来ますよ。"
L12_1.m_Talk_JPN = L13_1
L13_1 = "If I were to quit my job and disappear, she would probably come looking for me all over space."
L12_1.m_Talk_ENG = L13_1
L13_1 = "要是我辭職消失的話，就算是天涯海角她也會把我揪回的。"
L12_1.m_Talk_TWN = L13_1
L13_1 = "เกิดผมลาออกแล้วหายหัวไป เธอคงตามหาผมไปทั่วอวกาศแน่"
L12_1.m_Talk_THA = L13_1
L13_1 = "Nếu tôi bỏ việc rồi biến mất, cô ấy chắc chắn sẽ đi tìm tôi khắp nơi."
L12_1.m_Talk_VTN = L13_1
L13_1 = "而且如果我辞职消失了，她一定会追到宇宙尽头把我抓回去的。"
L12_1.m_Talk_SCN = L13_1
L13_1 = "Wenn ich meinen Job kündigen und verschwinden würde, würde sie wahrscheinlich jeden Winkel des Weltraums nach mir absuchen."
L12_1.m_Talk_DEU = L13_1
L13_1 = "Si je décide de tout plaquer pour disparaître dans la nature, elle voyagera sans doute jusqu'aux confins de l'espace pour me retrouver."
L12_1.m_Talk_FRA = L13_1
L13_1 = {}
L14_1 = "FOOLSDAY_PART2_NODE1_EPILOGUE@213#Talk"
L13_1.m_CutScenKey_Talk = L14_1
L14_1 = 213
L13_1.m_CutScenProcessKey = L14_1
L13_1.m_CutScenID = 2700117
L13_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L13_1.m_bWaitClick = true
L13_1.m_fWaitTime = 0
L13_1.m_Face = "UNIT_SURPRISE"
L13_1.m_CharStrID = "KNIGHT_REPLACER_UNIT_FOOLSDAY"
L13_1.m_Pos = "C"
L13_1.m_Crash = 20
L14_1 = "그건 좀 무서운데…?"
L13_1.m_Talk_KOREA = L14_1
L13_1.m_fTalkTime = 0.03
L14_1 = "それはちょっと怖いな……"
L13_1.m_Talk_JPN = L14_1
L14_1 = "That’s kind of creepy..."
L13_1.m_Talk_ENG = L14_1
L14_1 = "那好像有點恐怖欸…？"
L13_1.m_Talk_TWN = L14_1
L14_1 = "ฟังดูอี๋ๆ นะนั่น..."
L13_1.m_Talk_THA = L14_1
L14_1 = "Nghe rùng rợn quá..."
L13_1.m_Talk_VTN = L14_1
L14_1 = "这个有点吓人呢……？"
L13_1.m_Talk_SCN = L14_1
L14_1 = "Das klingt irgendwie ein bisschen gruselig ..."
L13_1.m_Talk_DEU = L14_1
L14_1 = "C'est un peu effrayant..."
L13_1.m_Talk_FRA = L14_1
