L15_1 = "FOOLSDAY_PART2_NODE1_EPILOGUE@214#Talk"
L14_1.m_CutScenKey_Talk = L15_1
L15_1 = 214
L14_1.m_CutScenProcessKey = L15_1
L14_1.m_CutScenID = 2700117
L14_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L14_1.m_bWaitClick = true
L14_1.m_fWaitTime = 0
L14_1.m_Face = "UNIT_PRIDE"
L14_1.m_CharStrID = "OROCHI_JAPAN_NULL_FOOLSDAY"
L14_1.m_Pos = "C"
L15_1 = "듣자 하니 네 녀석들도 우리 악당 못지 않게 참 파란만장하게 살았구나."
L14_1.m_Talk_KOREA = L15_1
L14_1.m_fTalkTime = 0.03
L15_1 = "聞けば、お前らも我々悪党に負けず劣らず波瀾万丈な人生を生きて来たのだな。"
L14_1.m_Talk_JPN = L15_1
L15_1 = "From what I hear, you've also been through quite a lot, like us."
L14_1.m_Talk_ENG = L15_1
L15_1 = "這樣聽起來，你們活得也不比我們反派輕鬆呢。"
L14_1.m_Talk_TWN = L15_1
L15_1 = "เท่าที่ฟัง เจ้าเองก็ผ่านอะไรมาเยอะทีเดียว เหมือนพวกเรา"
L14_1.m_Talk_THA = L15_1
L15_1 = "Nghe ngươi nói vậy, có vẻ ngươi cũng thăng trầm chẳng thua gì phản diện chúng ta."
L14_1.m_Talk_VTN = L15_1
L15_1 = "这么听来，你们的生活也真够跌宕起伏的，一点都不亚于我们。"
L14_1.m_Talk_SCN = L15_1
L15_1 = "Es klingt so, als hättet ihr auch ziemlich viel durchgemacht."
L14_1.m_Talk_DEU = L15_1
L15_1 = "Eh bien il s'en passe des choses dans ta vie, à toi aussi."
L14_1.m_Talk_FRA = L15_1
L15_1 = {}
L16_1 = "FOOLSDAY_PART2_NODE1_EPILOGUE@215#Talk"
L15_1.m_CutScenKey_Talk = L16_1
L16_1 = 215
L15_1.m_CutScenProcessKey = L16_1
L15_1.m_CutScenID = 2700117
L15_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L15_1.m_bWaitClick = true
L15_1.m_fWaitTime = 0
L15_1.m_CharStrID = "OROCHI_JAPAN_NULL_FOOLSDAY"
L15_1.m_Pos = "C"
L16_1 = "회사생활이라는 것도 제법 재밌어 보이는 걸?"
L15_1.m_Talk_KOREA = L16_1
L15_1.m_fTalkTime = 0.03
L16_1 = "会社生活というものも結構面白そうではないか。"
L15_1.m_Talk_JPN = L16_1
L16_1 = "Working at a company sounds rather interesting."
L15_1.m_Talk_ENG = L16_1
L16_1 = "職場生活感覺也蠻有趣的？"
L15_1.m_Talk_TWN = L16_1
L16_1 = "การทำงานในบริษัทสักแห่งก็ฟังดูน่าสนใจดีนะ"
L15_1.m_Talk_THA = L16_1
L16_1 = "Làm việc ở một công ty nghe cũng có vẻ hấp dẫn."
L15_1.m_Talk_VTN = L16_1
L16_1 = "职场生活看起来也挺有意思的。"
L15_1.m_Talk_SCN = L16_1
L16_1 = "Die Arbeit in einem Unternehmen klingt ziemlich interessant."
L15_1.m_Talk_DEU = L16_1
L16_1 = "À t'entendre ça n'a pas l'air si mal finalement, la vie de bureau."
L15_1.m_Talk_FRA = L16_1
L16_1 = {}
L17_1 = "FOOLSDAY_PART2_NODE1_EPILOGUE@216#Talk"
L16_1.m_CutScenKey_Talk = L17_1
L17_1 = 216
L16_1.m_CutScenProcessKey = L17_1
L16_1.m_CutScenID = 2700117
L16_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L16_1.m_bWaitClick = true
L16_1.m_fWaitTime = 0
L17_1 = "UNIT_LAUGH"
L16_1.m_Face = L17_1
L17_1 = "ROSARIA_NPC_FOOLSDAY_NULL"
L16_1.m_CharStrID = L17_1
L16_1.m_Pos = "C"
L17_1 = "그럼~ 악당처럼 보험도 못 들고 수익이 불안정한 직종은 별로 인기가 없지."
L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "そうじゃ～悪党のように保険もなく、収益が不安定な職種はあまりモテぬ。"
L16_1.m_Talk_JPN = L17_1
L17_1 = "Of course! There aren't a lot of jobs that are as unstable and dangerous as being a villain."
L16_1.m_Talk_ENG = L17_1
L17_1 = "那當然～反派這個職業既沒有保險，收入又不穩定，當然沒什麼人想從事。"
L16_1.m_Talk_TWN = L17_1
L17_1 = "ก็แน่นะสิ! มีไม่กี่งานหรอกนะที่ไม่มั่นคงแล้วก็อันตรายเหมือนเป็นวายร้ายน่ะ"
L16_1.m_Talk_THA = L17_1
L17_1 = "Dĩ nhiên! Không có nhiều công việc bất ổn và nguy hiểm như làm kẻ xấu đâu."
L16_1.m_Talk_VTN = L17_1
L17_1 = "当然~像恶棍这种不能投保、收入也不稳定的职业并不怎么受欢迎。"
L16_1.m_Talk_SCN = L17_1
L17_1 = "Natürlich! Ein Job ohne Versicherungen und mit instabilem Einkommen wie beispielsweise der eines Schurken ist nicht sehr beliebt."
L16_1.m_Talk_DEU = L17_1
L17_1 = "Bien sûr ! Ça vaut sans doute mieux que la vie de criminel sans assurance et sans revenu stable, en tout cas."
L16_1.m_Talk_FRA = L17_1
L17_1 = {}
L18_1 = "FOOLSDAY_PART2_NODE1_EPILOGUE@217#Talk"
L17_1.m_CutScenKey_Talk = L18_1
L18_1 = 217
L17_1.m_CutScenProcessKey = L18_1
L17_1.m_CutScenID = 2700117
L17_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L17_1.m_bWaitClick = true
L17_1.m_fWaitTime = 0
L18_1 = "ROSARIA_NPC_FOOLSDAY_NULL"
L17_1.m_CharStrID = L18_1
L17_1.m_Pos = "C"
L18_1 = "게임을 좋아한다면 이 참에 너희도 입사지원서나 내보는 건 어떠냐?"
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "ゲーム好きというのなら、この際其方たちも履歴書を出してみてはどうじゃ？"
L17_1.m_Talk_JPN = L18_1
L18_1 = "If you are into games, why don’t you both submit a resume?"
L17_1.m_Talk_ENG = L18_1
L18_1 = "既然你們喜歡玩遊戲，不如就趁這個機會遞交入職申請書吧？"
L17_1.m_Talk_TWN = L18_1
L18_1 = "ในเมื่อพวกเจ้าก็สนใจ แล้วทำไมไม่ส่งประวัติไปกันทั้งคู่เลยล่ะ?"
L17_1.m_Talk_THA = L18_1
L18_1 = "Nếu thích, sao cả hai không nộp CV đi?"
L17_1.m_Talk_VTN = L18_1
L18_1 = "如果你们喜欢游戏，干脆借这个机会也提交一下求职简历怎么样？"
L17_1.m_Talk_SCN = L18_1
L18_1 = "Wenn du dich für Spiele interessierst, warum reichst du dann nicht mal eine Bewerbung ein?"
L17_1.m_Talk_DEU = L18_1
L18_1 = "Si vous aimez les jeux toutes les deux, pourquoi n'essayez-vous pas d'envoyer un C.V. ?"
L17_1.m_Talk_FRA = L18_1
L18_1 = {}
