L20_1 = "FOOLSDAY_PART2_NODE1_EPILOGUE@219#Talk"
L19_1.m_CutScenKey_Talk = L20_1
L20_1 = 219
L19_1.m_CutScenProcessKey = L20_1
L19_1.m_CutScenID = 2700117
L19_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L19_1.m_bWaitClick = true
L19_1.m_fWaitTime = 0
L20_1 = "UNIT_LAUGH"
L19_1.m_Face = L20_1
L20_1 = "JOO_SHI_YOON_NPC_FOOLSDAY_NULL"
L19_1.m_CharStrID = L20_1
L20_1 = "R_M_I"
L19_1.m_Pos = L20_1
L20_1 = "맞습니다. 물가 오르는 속도가 제 연봉인상보다 빠르다는 점만 빼면 안정적인 직장을 갖는 게 최고이거든요."
L19_1.m_Talk_KOREA = L20_1
L19_1.m_fTalkTime = 0.03
L20_1 = "そうですよ。物価上昇の速度が僕の昇給よりも早いのがネックですが、安定した職が一番ですからね。"
L19_1.m_Talk_JPN = L20_1
L20_1 = "She’s right. Aside from the fact that inflation is more rapid than my salary raise, it’s nice having a job with stable income."
L19_1.m_Talk_ENG = L20_1
L20_1 = "沒錯，雖然薪水漲的速度比不上物價上漲的速度， 但排除這點，有個穩定的工作還是比較好的。"
L19_1.m_Talk_TWN = L20_1
L20_1 = "จริงของเธอนะครับ ถ้าไม่นับเรื่องเงินเฟ้อโตเร็วกว่าเงินเดือนผมละก็ การมีงานที่รายได้แน่นอนก็ดีอยู่นะครับ"
L19_1.m_Talk_THA = L20_1
L20_1 = "Cô ấy nói đúng đấy. Mặc dù tiền lương thì chẳng thể nào đuổi kịp lạm phát, nhưng có thu nhập ổn định vẫn là tốt nhất."
L19_1.m_Talk_VTN = L20_1
L20_1 = "没错。虽然薪资上涨的速度跟不上物价上涨的速度，但有一份稳定的工作再好不过了。"
L19_1.m_Talk_SCN = L20_1
L20_1 = "Sie hat recht. Abgesehen von der Tatsache, dass die Inflation schneller als meine Gehaltserhöhung ist, ist es schön, einen Job mit stabilem Einkommen zu haben."
L19_1.m_Talk_DEU = L20_1
L20_1 = "Elle a raison. Mis à part que l'inflation augmente plus vite que mon salaire, c'est quand même confortable de disposer d'un emploi à revenu fixe."
L19_1.m_Talk_FRA = L20_1
L20_1 = {}
