L23_1 = "FOOLSDAY_PART2_NODE1_EPILOGUE@222#Talk"
L22_1.m_CutScenKey_Talk = L23_1
L23_1 = 222
L22_1.m_CutScenProcessKey = L23_1
L22_1.m_CutScenID = 2700117
L22_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L22_1.m_bWaitClick = true
L22_1.m_fWaitTime = 0
L22_1.m_Face = "UNIT_PRIDE"
L22_1.m_CharStrID = "KNIGHT_REPLACER_UNIT_FOOLSDAY"
L23_1 = "R"
L22_1.m_Pos = L23_1
L23_1 = "괜찮네. 이 참에 나도 회사에 취업이나 해볼까?"
L22_1.m_Talk_KOREA = L23_1
L22_1.m_fTalkTime = 0.03
L23_1 = "いいな。アタシも会社に就職してみるか？"
L22_1.m_Talk_JPN = L23_1
L23_1 = "That sounds pretty good. Maybe I should seriously consider applying for a job at a company."
L22_1.m_Talk_ENG = L23_1
L23_1 = "好像不錯欸，我也趁機找個工作吧？"
L22_1.m_Talk_TWN = L23_1
L23_1 = "ฟังดูดีอยู่นะนั่น ฉันน่าจะลองคิดเรื่องสมัครทำงานบริษัทให้จริงจังดูแฮะ"
L22_1.m_Talk_THA = L23_1
L23_1 = "Nghe hay ho nhỉ. Có lẽ tôi nên nghiêm túc cân nhắc việc xin việc làm ở một công ty."
L22_1.m_Talk_VTN = L23_1
L23_1 = "好像不错耶。不如借此机会，我们也去公司上班吧？"
L22_1.m_Talk_SCN = L23_1
L23_1 = "Das klingt ziemlich gut. Vielleicht sollte ich ernsthaft in Betracht ziehen, mich für einen Job bei einem Unternehmen zu bewerben."
L22_1.m_Talk_DEU = L23_1
L23_1 = "Ça a l'air. Peut-être que je devrais envisager sérieusement la question, moi aussi..."
L22_1.m_Talk_FRA = L23_1
L23_1 = {}
L24_1 = "FOOLSDAY_PART2_NODE1_EPILOGUE@223#Talk"
L23_1.m_CutScenKey_Talk = L24_1
L24_1 = 223
L23_1.m_CutScenProcessKey = L24_1
L23_1.m_CutScenID = 2700117
L23_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L23_1.m_bWaitClick = true
L23_1.m_fWaitTime = 0
L23_1.m_CharStrID = "OROCHI_JAPAN_NULL_FOOLSDAY"
L24_1 = "L"
L23_1.m_Pos = L24_1
L24_1 = "생각 한 번 단순하구나. 네놈의 망나니 기질을 직장에서 감당할 수 있을 것 같으냐?"
L23_1.m_Talk_KOREA = L24_1
L23_1.m_fTalkTime = 0.03
L24_1 = "単純でいいな。貴様のごろつき気質に職場が耐えられると思うのか？"
L23_1.m_Talk_JPN = L24_1
L24_1 = "Such a simple minded child. Do you really think your workplace will be able to handle your insane impulses?"
L23_1.m_Talk_ENG = L24_1
L24_1 = "想得簡單，你這傢伙天生做反派的料，你有辦法承受職場生活嗎？"
L23_1.m_Talk_TWN = L24_1
L24_1 = "คิดอะไรง่ายเป็นเด็กๆ คิดจริงๆ เหรอว่าที่ทำงานจะรับมือคนวู่วามเสียสติแบบเจ้าได้รึ?"
L23_1.m_Talk_THA = L24_1
L24_1 = "Đầu óc đơn giản quá thể, nhóc ạ. Ngươi thực sự nghĩ có chỗ làm nào chịu nổi mấy cơn bốc đồng của ngươi à?"
L23_1.m_Talk_VTN = L24_1
L24_1 = "别把事情想得太简单了。你觉得公司能受得了你那无赖的气质吗？"
L23_1.m_Talk_SCN = L24_1
L24_1 = "Du bist so einfach gestrickt. Denkst du wirklich, dass du am Arbeitsplatz in der Lage sein wirst, dein wildes Temperament im Zaum zu halten?"
L23_1.m_Talk_DEU = L24_1
L24_1 = "Quelle naïveté. Crois-tu vraiment que tes collègues pourront supporter des délires de psychopathe ?"
L23_1.m_Talk_FRA = L24_1
L24_1 = {}
L25_1 = "FOOLSDAY_PART2_NODE1_EPILOGUE@224#Talk"
L24_1.m_CutScenKey_Talk = L25_1
L25_1 = 224
L24_1.m_CutScenProcessKey = L25_1
L24_1.m_CutScenID = 2700117
L24_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L24_1.m_bWaitClick = true
L24_1.m_fWaitTime = 0
L24_1.m_Face = "UNIT_DESPAIR"
L24_1.m_CharStrID = "KNIGHT_REPLACER_UNIT_FOOLSDAY"
L25_1 = "R"
L24_1.m_Pos = L25_1
L25_1 = "으음… 그것도 맞는 말이야."
L24_1.m_Talk_KOREA = L25_1
L24_1.m_fTalkTime = 0.03
L25_1 = "うーむ……それもそうだな。"
L24_1.m_Talk_JPN = L25_1
L25_1 = "Mm... You do have a point."
L24_1.m_Talk_ENG = L25_1
L25_1 = "呃…你說的也沒錯。"
L24_1.m_Talk_TWN = L25_1
L25_1 = "อืม... ก็จริงของเธอ"
L24_1.m_Talk_THA = L25_1
L25_1 = "Hmm... Cô có lý."
L24_1.m_Talk_VTN = L25_1
L25_1 = "呃呃……说的也是。"
L24_1.m_Talk_SCN = L25_1
L25_1 = "Hmm ... Das stimmt auch wieder."
L24_1.m_Talk_DEU = L25_1
L25_1 = "Hum... Tu n'as pas tort."
L24_1.m_Talk_FRA = L25_1
L25_1 = {}
