L27_1 = "FOOLSDAY_PART2_NODE1_EPILOGUE@226#Talk"
L26_1.m_CutScenKey_Talk = L27_1
L27_1 = 226
L26_1.m_CutScenProcessKey = L27_1
L26_1.m_CutScenID = 2700117
L26_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L26_1.m_bWaitClick = true
L26_1.m_fWaitTime = 0
L26_1.m_Face = "UNIT_SURPRISE"
L27_1 = "JOO_SHI_YOON_NPC_FOOLSDAY_NULL"
L26_1.m_CharStrID = L27_1
L26_1.m_Pos = "C"
L27_1 = "생각보다 이성적으로 납득하시네요."
L26_1.m_Talk_KOREA = L27_1
L26_1.m_fTalkTime = 0.03
L27_1 = "思ったより理性的に納得するんですね。"
L26_1.m_Talk_JPN = L27_1
L27_1 = "You accept it rather calmly than I imagined."
L26_1.m_Talk_ENG = L27_1
L27_1 = "你還真好說服。"
L26_1.m_Talk_TWN = L27_1
L27_1 = "คุณยอมรับเงียบๆ ง่ายๆ กว่าที่ผมคิดอีกนะครับ"
L26_1.m_Talk_THA = L27_1
L27_1 = "Cô chấp nhận nó bình tĩnh hơn tôi tưởng."
L26_1.m_Talk_VTN = L27_1
L27_1 = "你倒是接受得挺快的。"
L26_1.m_Talk_SCN = L27_1
L27_1 = "Du nimmst es viel gelassener auf als ich es erwartet habe."
L26_1.m_Talk_DEU = L27_1
L27_1 = "Vous êtes du genre influençable vous, hein ?"
L26_1.m_Talk_FRA = L27_1
L27_1 = {}
L28_1 = "FOOLSDAY_PART2_NODE1_EPILOGUE@227#Talk"
L27_1.m_CutScenKey_Talk = L28_1
L28_1 = 227
L27_1.m_CutScenProcessKey = L28_1
L27_1.m_CutScenID = 2700117
L27_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L27_1.m_bWaitClick = true
L27_1.m_fWaitTime = 0
L27_1.m_Face = "UNIT_DESPAIR"
L27_1.m_CharStrID = "KNIGHT_REPLACER_UNIT_FOOLSDAY"
L27_1.m_Pos = "C"
L28_1 = "사실, 요즘 들어 악당짓을 하면서도 예전만큼 보람차지 않더라고."
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "実はな、最近悪党やっても昔のようにやりがいを感じられなくてさ。"
L27_1.m_Talk_JPN = L28_1
L28_1 = "To be honest, being a villain doesn’t bring as much joy to me as it used to."
L27_1.m_Talk_ENG = L28_1
L28_1 = "不瞞大家說，我最近在幹壞事時，已經沒有像過去那種滿足感。"
L27_1.m_Talk_TWN = L28_1
L28_1 = "ว่ากันตรงๆ นะ การเป็นวายร้ายมันไม่ได้สนุกเหมือนที่เคยแล้วน่ะ"
L27_1.m_Talk_THA = L28_1
L28_1 = "Thành thật mà nói làm kẻ phản diện chẳng mang lại cho tôi nhiều niềm vui như xưa."
L27_1.m_Talk_VTN = L28_1
L28_1 = "其实吧，最近做坏事也没有以前那么有意义了。"
L27_1.m_Talk_SCN = L28_1
L28_1 = "Um ehrlich zu sein, eine Schurkin zu sein, bereitet mir nicht mehr so viel Freude wie früher."
L27_1.m_Talk_DEU = L28_1
L28_1 = "La vérité... c'est que ça ne me procure plus autant de plaisir qu'avant, de faire le mal autour de moi."
L27_1.m_Talk_FRA = L28_1
L28_1 = {}
L29_1 = "FOOLSDAY_PART2_NODE1_EPILOGUE@228#Talk"
L28_1.m_CutScenKey_Talk = L29_1
L29_1 = 228
L28_1.m_CutScenProcessKey = L29_1
L28_1.m_CutScenID = 2700117
L28_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L28_1.m_bWaitClick = true
L28_1.m_fWaitTime = 0
L28_1.m_Face = "UNIT_IDLE"
L28_1.m_CharStrID = "KNIGHT_REPLACER_UNIT_FOOLSDAY"
L28_1.m_Pos = "C"
L29_1 = "돌이켜보면 세간에 악명을 떨치는 것 말고는 남긴 것 하나 없었고 말이야."
L28_1.m_Talk_KOREA = L29_1
L28_1.m_fTalkTime = 0.03
L29_1 = "振り返ってみると世間に悪名を轟かせること以外に残したもんもなかったし。"
L28_1.m_Talk_JPN = L29_1
L29_1 = "I never had any achievements apart from being infamous."
L28_1.m_Talk_ENG = L29_1
L29_1 = "驀然回首，留下的只有臭名。"
L28_1.m_Talk_TWN = L29_1
L29_1 = "ฉันไม่เคยประสบความสำเร็จอะไรนอกจากชื่อเสียงฉาวโฉ่เลยไง"
L28_1.m_Talk_THA = L29_1
L29_1 = "Tôi chẳng có thành tựu gì ngoài việc danh tiếng hư hỏng hết."
L28_1.m_Talk_VTN = L29_1
L29_1 = "回头看看，除了臭名远扬，什么都没有留下。"
L28_1.m_Talk_SCN = L29_1
L29_1 = "Ich hatte nie irgendwelche Erfolge zu verzeichnen, abgesehen von meinem Bekanntheitsgrad."
L28_1.m_Talk_DEU = L29_1
L29_1 = "Et puis rétrospectivement, je n'ai pas accompli grand chose. La seule chose qui me reste, c'est une mauvaise réputation."
L28_1.m_Talk_FRA = L29_1
L29_1 = {}
L30_1 = "FOOLSDAY_PART2_NODE1_EPILOGUE@229#Talk"
L29_1.m_CutScenKey_Talk = L30_1
L30_1 = 229
L29_1.m_CutScenProcessKey = L30_1
L29_1.m_CutScenID = 2700117
L29_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L29_1.m_bWaitClick = true
L29_1.m_fWaitTime = 0
L29_1.m_Face = "UNIT_IDLE"
L29_1.m_CharStrID = "OROCHI_JAPAN_NULL_FOOLSDAY"
L29_1.m_Pos = "C"
L30_1 = "네 녀석이 그런 깊은 생각을 하고 있었다니, 의외로구나."
L29_1.m_Talk_KOREA = L30_1
L29_1.m_fTalkTime = 0.03
L30_1 = "貴様がそんなことを考えていたなんて、意外だな。"
L29_1.m_Talk_JPN = L30_1
L30_1 = "I couldn't expect to hear someone like you having those kinds of thoughts."
L29_1.m_Talk_ENG = L30_1
L30_1 = "沒想到你的心思竟然有這麼深。"
L29_1.m_Talk_TWN = L30_1
L30_1 = "น่าตกใจไม่น้อยนะ ที่ได้รู้ว่าคนเยี่ยงเจ้าคิดอะไรเช่นนั้น"
L29_1.m_Talk_THA = L30_1
L30_1 = "Thật sốc khi nghe một người như ngươi chia sẻ tâm sự như thế đấy."
L29_1.m_Talk_VTN = L30_1
L30_1 = "你居然有这么深刻的想法，真让我意外。"
L29_1.m_Talk_SCN = L30_1
L30_1 = "Ich bin ziemlich schockiert, dass jemand wie du so tiefgründig sein kann."
L29_1.m_Talk_DEU = L30_1
L30_1 = "Venant de toi, ce genre d'introspection est surprenant."
L29_1.m_Talk_FRA = L30_1
L30_1 = {}
L31_1 = "FOOLSDAY_PART2_NODE1_EPILOGUE@230#Talk"
L30_1.m_CutScenKey_Talk = L31_1
L31_1 = 230
L30_1.m_CutScenProcessKey = L31_1
L30_1.m_CutScenID = 2700117
L30_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L30_1.m_bWaitClick = true
L30_1.m_fWaitTime = 0
L30_1.m_Face = "UNIT_HATE"
L30_1.m_CharStrID = "KNIGHT_REPLACER_UNIT_FOOLSDAY"
L30_1.m_Pos = "C"
L31_1 = "넌 정말로 한결같이 긁어대네."
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "てめえは本当ひたすらウザいな。"
L30_1.m_Talk_JPN = L31_1
L31_1 = "You’re as annoying as always, aren’t you?"
L30_1.m_Talk_ENG = L31_1
L31_1 = "你真的是毒舌欸。"
L30_1.m_Talk_TWN = L31_1
L31_1 = "เธอนี่จะกวนประสาทกันตลอดเลยใช่มั้ยนะ?"
L30_1.m_Talk_THA = L31_1
L31_1 = "Cô vẫn làm tôi khó chịu như mọi khi nhỉ?"
L30_1.m_Talk_VTN = L31_1
L31_1 = "你真是一如既往地爱挖苦人啊。"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Die Äußerung konntest du echt nicht für dich behalten, oder?"
L30_1.m_Talk_DEU = L31_1
L31_1 = "Toi par contre, t'as toujours besoin d'en rajouter..."
L30_1.m_Talk_FRA = L31_1
L31_1 = {}
L32_1 = "FOOLSDAY_PART2_NODE1_EPILOGUE@231#Talk"
L31_1.m_CutScenKey_Talk = L32_1
L32_1 = 231
L31_1.m_CutScenProcessKey = L32_1
L31_1.m_CutScenID = 2700117
L31_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L31_1.m_bWaitClick = true
L31_1.m_fWaitTime = 0
L31_1.m_Face = "UNIT_IDLE"
