L33_1 = "ROSARIA_NPC_FOOLSDAY_NULL"
L32_1.m_CharStrID = L33_1
L32_1.m_Pos = "C"
L33_1 = "그럼 다시 오락실로 돌아가볼까?"
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "それでは、またゲームセンターに戻るとするか。"
L32_1.m_Talk_JPN = L33_1
L33_1 = "Should we go back to the arcade, then?"
L32_1.m_Talk_ENG = L33_1
L33_1 = "那我們再回到遊戲場吧？"
L32_1.m_Talk_TWN = L33_1
L33_1 = "งั้นเรากลับไปที่อาร์เคดกันมั้ย?"
L32_1.m_Talk_THA = L33_1
L33_1 = "Chúng ta quay lại khu trò chơi điện tử nhé?"
L32_1.m_Talk_VTN = L33_1
L33_1 = "那我们就回游戏厅吧？"
L32_1.m_Talk_SCN = L33_1
L33_1 = "Wollen wir dann mal zur Spielhalle zurückgehen?"
L32_1.m_Talk_DEU = L33_1
L33_1 = "Bon, on y retourne ?"
L32_1.m_Talk_FRA = L33_1
L33_1 = {}
L34_1 = "FOOLSDAY_PART2_NODE1_EPILOGUE@233#Talk"
L33_1.m_CutScenKey_Talk = L34_1
L34_1 = 233
L33_1.m_CutScenProcessKey = L34_1
L33_1.m_CutScenID = 2700117
L33_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
