L33_1.m_fWaitTime = 0
L33_1.m_Face = "UNIT_SURPRISE"
L33_1.m_CharStrID = "KNIGHT_REPLACER_UNIT_FOOLSDAY"
L33_1.m_Pos = "C"
L34_1 = "갑자기…? 네가 우리보다 강한 건 이미 충분히 증명하지 않았어?"
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "いきなり……？　てめえがアタシたちより強いってのはもう十分証明しただろ？"
L33_1.m_Talk_JPN = L34_1
L34_1 = "Why all of a sudden...? We get it. You’re stronger than us."
L33_1.m_Talk_ENG = L34_1
L34_1 = "這麼突然…？不是已經充分證明你比我們厲害嗎？"
L33_1.m_Talk_TWN = L34_1
L34_1 = "ทำไมจู่ๆ ก็...? เรารู้แล้วนะว่าเธอเก่งกว่าเราน่ะ"
L33_1.m_Talk_THA = L34_1
L34_1 = "Sao đột nhiên lại...? Không phải rõ ràng là cô mạnh hơn chúng tôi sao."
L33_1.m_Talk_VTN = L34_1
L34_1 = "这么突然……？可是不管怎么说，我们还是赢不了你啊？"
L33_1.m_Talk_SCN = L34_1
L34_1 = "Warum so plötzlich ...? Hast du denn nicht schon genug bewiesen, dass du stärker bist als wir?"
L33_1.m_Talk_DEU = L34_1
L34_1 = "Euh... là, tout de suite ? Ça va, on sait que tu es plus forte que nous."
L33_1.m_Talk_FRA = L34_1
L34_1 = {}
