L34_1.m_CharStrID = L35_1
L34_1.m_Pos = "C"
L35_1 = "결투 때문이 아니다."
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "決闘のためではない。"
L34_1.m_Talk_JPN = L35_1
L35_1 = "I’m not going to fight you."
L34_1.m_Talk_ENG = L35_1
L35_1 = "回去不是要決鬥。"
L34_1.m_Talk_TWN = L35_1
L35_1 = "ข้าไม่ได้จะไปสู้กับพวกเจ้านะ"
L34_1.m_Talk_THA = L35_1
L35_1 = "Ta sẽ không đấu với cô."
L34_1.m_Talk_VTN = L35_1
L35_1 = "这个不重要。"
L34_1.m_Talk_SCN = L35_1
L35_1 = "Ich will nicht zurückgehen, um zu kämpfen."
L34_1.m_Talk_DEU = L35_1
L35_1 = "Non, je ne parlais pas du jeu de combat."
L34_1.m_Talk_FRA = L35_1
