L35_1.m_CharStrID = L36_1
L35_1.m_Pos = "C"
L36_1 = "네놈이 하려던 인형 뽑기, 아직 마무리 짓지 못했잖아?"
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "其方がやろうとしていたクレーンゲーム、まだ終わってなかろう？"
L35_1.m_Talk_JPN = L36_1
L36_1 = "You still haven’t got that doll you wanted, have you?"
L35_1.m_Talk_ENG = L36_1
L36_1 = "你剛不是想抓娃娃還沒抓到嗎？"
L35_1.m_Talk_TWN = L36_1
L36_1 = "แต่เจ้ายังไม่ได้ตุ๊กตาตัวที่อยากได้ไม่ใช่เหรอ?"
L35_1.m_Talk_THA = L36_1
L36_1 = "Cô vẫn chưa có được con búp bê mà mình muốn phải không?"
L35_1.m_Talk_VTN = L36_1
L36_1 = "你那个娃娃不是还没抓到吗？"
L35_1.m_Talk_SCN = L36_1
L36_1 = "Du hast immer noch nicht die Puppe, die du wolltest, oder?"
L35_1.m_Talk_DEU = L36_1
L36_1 = "Tu n'as toujours pas obtenu la peluche que tu voulais, si ?"
L35_1.m_Talk_FRA = L36_1
