L39_1.m_Pos = L40_1
L40_1 = "조금만 더 왼쪽으로…! 왼쪽을 노리거라!"
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "もう少し左……！　左を狙いなさい！"
L39_1.m_Talk_JPN = L40_1
L40_1 = "A little bit more to the left...! The left, I said!"
L39_1.m_Talk_ENG = L40_1
L40_1 = "再左邊一點…！瞄準左邊！"
L39_1.m_Talk_TWN = L40_1
L40_1 = "ซ้ายอีกนิด...! บอกว่าซ้ายไง!"
L39_1.m_Talk_THA = L40_1
L40_1 = "Sang trái một chút nữa...! Ta nói là bên trái mà!"
L39_1.m_Talk_VTN = L40_1
L40_1 = "再往左一点点……！夹住左边！"
L39_1.m_Talk_SCN = L40_1
L40_1 = "Ein bisschen weiter links ...! Links hab ich gesagt!"
L39_1.m_Talk_DEU = L40_1
L40_1 = "Là, un tout petit peu à gauche...! À gauche, je te dis !"
L39_1.m_Talk_FRA = L40_1
