L41_1 = "L_M_I"
L40_1.m_Pos = L41_1
L41_1 = "지금이라도 더 작은 인형을 노리는 편이 좋지 않을까요?"
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "今からでももっと小さいぬいぐるみを狙った方がいいんじゃないですか？"
L40_1.m_Talk_JPN = L41_1
L41_1 = "Don’t you think it’ll be wiser to aim for a smaller doll?"
L40_1.m_Talk_ENG = L41_1
L41_1 = "是不是改抓小一點的比較好？"
L40_1.m_Talk_TWN = L41_1
L41_1 = "ไม่คิดเหรอครับว่าจับตุ๊กตาตัวเล็กๆ จะง่ายกว่า?"
L40_1.m_Talk_THA = L41_1
L41_1 = "Cô không nghĩ là nhắm đến một con búp bê nhỏ hơn sẽ tốt hơn sao?"
L40_1.m_Talk_VTN = L41_1
L41_1 = "不然还是试试更小一点的娃娃吧？"
L40_1.m_Talk_SCN = L41_1
L41_1 = "Glaubst du nicht, dass es klüger wäre, eine kleinere Puppe herauszuholen?"
L40_1.m_Talk_DEU = L41_1
L41_1 = "Et si vous essayiez avec une peluche un peu plus petite ?"
