L42_1.m_Crash = 20
L43_1 = "시끄러워. 조종하는 건 나거든?"
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "うるさい。コントロールしてるのはアタシなんだよ。"
L42_1.m_Talk_JPN = L43_1
L43_1 = "Shut up! I’m the one controlling the claw!"
L42_1.m_Talk_ENG = L43_1
L43_1 = "你們好吵，現在是我在控制操縱桿好嗎？"
L42_1.m_Talk_TWN = L43_1
L43_1 = "เงียบนะ! คนคุมที่คีบน่ะฉันนะ!"
L42_1.m_Talk_THA = L43_1
L43_1 = "Im đi! Tôi mới là người điều khiển móng gắp!"
L42_1.m_Talk_VTN = L43_1
L43_1 = "闭嘴。操控的人是我！"
L42_1.m_Talk_SCN = L43_1
L43_1 = "Halt die Klappe! Ich bin diejenige, die den Greifer in der Hand hat!"
L42_1.m_Talk_DEU = L43_1
L43_1 = "La ferme ! C'est moi qui contrôle, c'est moi qui décide !"
L42_1.m_Talk_FRA = L43_1
