L43_1.m_Talk_VTN = L44_1
L44_1 = "咳……这是最后一枚硬币了，一定要成功。"
L43_1.m_Talk_SCN = L44_1
L44_1 = "Argh ... Das ist meine letzte Münze. Diesmal muss es klappen!"
L43_1.m_Talk_DEU = L44_1
L44_1 = "Urgh... c'est ma dernière pièce. Allez, je dois y arriver !"
