L3_1.m_CharStrID = L4_1
L4_1 = "L_F_C"
L3_1.m_Pos = L4_1
L4_1 = "됐다! 내가 성공했다고, 오로치!"
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "やった！　成功したぞ、オロチ！"
L3_1.m_Talk_JPN = L4_1
L4_1 = "I did it! Orochi, I made it!"
L3_1.m_Talk_ENG = L4_1
L4_1 = "抓到了！我成功了，大蛇！"
L3_1.m_Talk_TWN = L4_1
L4_1 = "ฉันทำได้! ฉันทำสำเร็จแล้ว โอโรจิ!"
L3_1.m_Talk_THA = L4_1
L4_1 = "Tôi đã làm được! Tôi đã thành công rồi, Orochi ơi!"
L3_1.m_Talk_VTN = L4_1
L4_1 = "好了！我成功了，大蛇！"
L3_1.m_Talk_SCN = L4_1
L4_1 = "Geschafft! Ich habe es geschafft, Orochi!"
L3_1.m_Talk_DEU = L4_1
L4_1 = "Je l'ai fait ! J'ai réussi, Orochi !"
L3_1.m_Talk_FRA = L4_1
