L5_1 = "FOOLSDAY_PART2_NODE1_EPILOGUE@254#Talk"
L4_1.m_CutScenKey_Talk = L5_1
L5_1 = 254
L4_1.m_CutScenProcessKey = L5_1
L4_1.m_CutScenID = 2700117
L4_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L4_1.m_bWaitClick = true
