L4_1.m_Face = "UNIT_IDLE"
L4_1.m_CharStrID = "OROCHI_JAPAN_NULL_FOOLSDAY"
L5_1 = "R"
L4_1.m_Pos = L5_1
L5_1 = "흥… 어울리지 않게 고작 인형 하나로 기뻐하긴."
L4_1.m_Talk_KOREA = L5_1
L4_1.m_fTalkTime = 0.03
L5_1 = "ふん……らしくもなく、ぬいぐるみ一つで喜ぶとは。"
L4_1.m_Talk_JPN = L5_1
L5_1 = "Hmph... All that racket for a lousy doll."
L4_1.m_Talk_ENG = L5_1
L5_1 = "哼…抓到這麼小的娃娃還那麼開心。"
L4_1.m_Talk_TWN = L5_1
L5_1 = "ฮึ่ม... วุ่นวายไปหมดก็เพื่อตุ๊กตาชั้นต่ำตัวเดียว"
L4_1.m_Talk_THA = L5_1
L5_1 = "Hừm…Gắp được con búp bê xấu xí mà vui thế, không hợp ngươi đâu."
L4_1.m_Talk_VTN = L5_1
L5_1 = "呵……因为一个破娃娃，就高兴成这样。"
L4_1.m_Talk_SCN = L5_1
L5_1 = "Hmm ... All diese Anstrengungen nur für eine lausige Puppe ... Das passt so gar nicht zu dir ..."
L4_1.m_Talk_DEU = L5_1
L5_1 = "Bah, tout ce bruit pour une vulgaire poupée... et moche, en plus !"
L4_1.m_Talk_FRA = L5_1
