L5_1.m_CharStrID = "OROCHI_JAPAN_NULL_FOOLSDAY"
L6_1 = "R"
L5_1.m_Pos = L6_1
L6_1 = "큰돈 주고 뽑았으니 칠칠 맞게 잃어버리지나 마라."
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "大金をはたいて取ったんだから、うっかりなくすな。"
L5_1.m_Talk_JPN = L6_1
L6_1 = "Just make sure you don’t lose it. You paid a fortune for it."
L5_1.m_Talk_ENG = L6_1
L6_1 = "花這麼多錢才抓到的，你可別弄丟了。"
L5_1.m_Talk_TWN = L6_1
L6_1 = "ระวังอย่าทำหายก็พอ เจ้าทุ่มโชคลาภทั้งปวงให้มันไปแล้ว"
L5_1.m_Talk_THA = L6_1
L6_1 = "Chắc chắn đừng có làm mất nó nhé. Ngươi tốn một đống tiền cho nó đấy."
L5_1.m_Talk_VTN = L6_1
L6_1 = "这可是我们花大价钱才抓到的，你可别弄丢了。"
L5_1.m_Talk_SCN = L6_1
L6_1 = "Du hast echt ein kleines Vermögen ausgegeben, um diese Puppe zu bekommen, also pass gut auf sie auf und verlier sie bloß nicht gleich."
L5_1.m_Talk_DEU = L6_1
L6_1 = "Tu n'as pas intérêt à la perdre. Avec la fortune que tu as dépensée pour l'obtenir, ce serait dommage."
L5_1.m_Talk_FRA = L6_1
