L8_1 = "이야, 결국 마지막에 성공할 줄이야. 축하드려요."
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "いやぁ、結局最後に成功するなんて。おめでとうございます。"
L7_1.m_Talk_JPN = L8_1
L8_1 = "Wow, you got it with your final shot! Congratulations."
L7_1.m_Talk_ENG = L8_1
L8_1 = "哇，我就知道你一定會成功，恭喜你。"
L7_1.m_Talk_TWN = L8_1
L8_1 = "โห คุณทำได้ตอนโอกาสสุดท้ายพอดีเลย! ยินดีด้วยนะครับ"
L7_1.m_Talk_THA = L8_1
L8_1 = "Wow, cô đã lấy được nó trong lần cuối cùng! Chúc mừng nhé."
L7_1.m_Talk_VTN = L8_1
L8_1 = "哇，没想到最后真的成功了，祝贺你。"
L7_1.m_Talk_SCN = L8_1
L8_1 = "Wow, du hast es am Ende wirklich geschafft! Glückwunsch."
L7_1.m_Talk_DEU = L8_1
L8_1 = "Ouah, vous l'avez eu avec votre dernier coup. Quel sang-froid, félicitations."
L7_1.m_Talk_FRA = L8_1
