L12_1 = "It’s a kind of strange feeling... But in a good way."
L11_1.m_Talk_ENG = L12_1
L12_1 = "好陌生的感覺…不過感覺不錯！"
L11_1.m_Talk_TWN = L12_1
L12_1 = "มันก็รู้สึกแปลกๆ นะ... แต่ในแง่ดีน่ะ"
L11_1.m_Talk_THA = L12_1
L12_1 = "Đó là một cảm xúc rất lạ...Nhưng tích cực."
L11_1.m_Talk_VTN = L12_1
L12_1 = "嗯，感觉有点陌生……但好像不错。"
L11_1.m_Talk_SCN = L12_1
L12_1 = "Es ist ein seltsames Gefühl ... Aber es fühlt sich nicht schlecht an."
L11_1.m_Talk_DEU = L12_1
L12_1 = "Ça fait un peu bizarre, mais... c'est pas si mal, en fait."
L11_1.m_Talk_FRA = L12_1
L12_1 = {}
L13_1 = "FOOLSDAY_PART2_NODE1_EPILOGUE@262#Talk"
L12_1.m_CutScenKey_Talk = L13_1
L13_1 = 262
L12_1.m_CutScenProcessKey = L13_1
L12_1.m_CutScenID = 2700117
L12_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L12_1.m_bWaitClick = true
L12_1.m_fWaitTime = 0
L12_1.m_Face = "UNIT_PRIDE"
L13_1 = "ROSARIA_NPC_FOOLSDAY_NULL"
L12_1.m_CharStrID = L13_1
L12_1.m_Pos = "C"
L13_1 = "보람이란, 원하는 것을 규칙에 따라 쟁취했을 때 비로소 온전히 누릴 수 있는 것이지."
L12_1.m_Talk_KOREA = L13_1
L12_1.m_fTalkTime = 0.03
L13_1 = "やりがいとは、規則に従いつつ欲しいものを勝ち取って初めて感じられるものじゃ。"
L12_1.m_Talk_JPN = L13_1
L13_1 = "The feeling of accomplishment is only earned when you get what you want while following the rules."
L12_1.m_Talk_ENG = L13_1
L13_1 = "所謂的滿足，是你用正當手法爭取到你想要的東西時，才能夠完全地享受到。"
L12_1.m_Talk_TWN = L13_1
L13_1 = "ความรู้สึกของการทำอะไรสำเร็จน่ะ คู่ควรจะได้รับมาก็ตอนที่เราทำอะไรตามกฎเท่านั้นนะ"
L12_1.m_Talk_THA = L13_1
L13_1 = "Cảm giác thành tựu chỉ có thể  ý nghĩa khi ngươi lấy được thứ mình muốn trong khi vẫn tuân theo luật."
L12_1.m_Talk_VTN = L13_1
L13_1 = "所谓的成就感，只有在按照规则去争取想要的东西时才会真正感受到。"
L12_1.m_Talk_SCN = L13_1
L13_1 = "Das Gefühl des Erfolgs stellt sich nur dann ein, wenn man das, was man unbedingt wollte, erhalten hat, während man die Regeln befolgt hat."
L12_1.m_Talk_DEU = L13_1
L13_1 = "Au lieu de briser la vitre pour piller la cage, tu as obtenu cette peluche en suivant les règles du jeu."
L12_1.m_Talk_FRA = L13_1
L13_1 = {}
L14_1 = "FOOLSDAY_PART2_NODE1_EPILOGUE@263#Talk"
L13_1.m_CutScenKey_Talk = L14_1
L14_1 = 263
L13_1.m_CutScenProcessKey = L14_1
L13_1.m_CutScenID = 2700117
L13_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L13_1.m_bWaitClick = true
L13_1.m_fWaitTime = 0
L14_1 = "ROSARIA_NPC_FOOLSDAY_NULL"
L13_1.m_CharStrID = L14_1
L13_1.m_Pos = "C"
L14_1 = "기계 안으로 들어가 훔치지 않고, 그 거지같은 집게로 결국 인형을 뽑은 것처럼 말이다."
L13_1.m_Talk_KOREA = L14_1
L13_1.m_fTalkTime = 0.03
L14_1 = "機械の中に潜り込んで盗む代わりに、あのアームで最終的にぬいぐるみを取ったようにのう。"
L13_1.m_Talk_JPN = L14_1
L14_1 = "Just like how you got the doll from controlling the claw machine, instead of breaking it."
L13_1.m_Talk_ENG = L14_1
L14_1 = "就像你現在不是爬到機台裡去偷，而是用那個破爛爪子抓到娃娃的感覺一樣。"
L13_1.m_Talk_TWN = L14_1
L14_1 = "เหมือนที่ตอนนี้เจ้าได้ตุ๊กตาจากการควบคุมตู้คีบ ไม่ใช่พังมันไงล่ะ"
L13_1.m_Talk_THA = L14_1
L14_1 = "Giống như cách cô lấy được con búp bê bằng máy gắp, thay vì phá vỡ chiếc máy."
L13_1.m_Talk_VTN = L14_1
L14_1 = "就像最后你选择用那个破夹子抓娃娃，而不是钻机器一样。"
L13_1.m_Talk_SCN = L14_1
L14_1 = "Damit meine ich, anstatt in den Greifautomaten hereinzukrabbeln und die Puppe zu stehlen, ist das Herausholen mit dem Greifer, die bessere Variante."
L13_1.m_Talk_DEU = L14_1
L14_1 = "Tu as le sentiment d'avoir accompli quelque chose, n'est-ce pas ? À force de travail et de détermination, et sans tricher."
L13_1.m_Talk_FRA = L14_1
L14_1 = {}
