L18_1 = "FOOLSDAY_PART2_NODE1_EPILOGUE@267#Talk"
L17_1.m_CutScenKey_Talk = L18_1
L18_1 = 267
L17_1.m_CutScenProcessKey = L18_1
L17_1.m_CutScenID = 2700117
L17_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L17_1.m_bWaitClick = true
L17_1.m_fWaitTime = 0
L17_1.m_Face = "UNIT_IDLE"
L18_1 = "JOO_SHI_YOON_NPC_FOOLSDAY_NULL"
L17_1.m_CharStrID = L18_1
L17_1.m_Pos = "C"
L18_1 = "저희는 이만 집으로 돌아갈 건데, 두 분은 정말 괜찮으시겠어요?"
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "僕たちはもう帰りますけど、二人は本当に大丈夫なんですか？"
L17_1.m_Talk_JPN = L18_1
L18_1 = "We will be heading home now. Are you two going to be all right?"
L17_1.m_Talk_ENG = L18_1
L18_1 = "我們要回去囉，你們二位真的沒問題吧？"
L17_1.m_Talk_TWN = L18_1
L18_1 = "เรากำลังจะกลับบ้านกันแล้ว คุณสองคนจะไม่เป็นไรใช่มั้ยครับ?"
L17_1.m_Talk_THA = L18_1
L18_1 = "Giờ chúng tôi sẽ về nhà. Hai cô sẽ ổn chứ?"
L17_1.m_Talk_VTN = L18_1
L18_1 = "那么，我们要回去了，两位在这里没关系吗？"
L17_1.m_Talk_SCN = L18_1
L18_1 = "Wir werden uns jetzt nach Hause begeben. Werden ihr wirklich klarkommen?"
L17_1.m_Talk_DEU = L18_1
L18_1 = "C'est pas tout, mais je dois y aller. Ça va aller, pour vous deux ?"
L17_1.m_Talk_FRA = L18_1
L18_1 = {}
L19_1 = "FOOLSDAY_PART2_NODE1_EPILOGUE@268#Talk"
L18_1.m_CutScenKey_Talk = L19_1
L19_1 = 268
L18_1.m_CutScenProcessKey = L19_1
L18_1.m_CutScenID = 2700117
L18_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L18_1.m_bWaitClick = true
L18_1.m_fWaitTime = 0
L19_1 = "UNIT_LAUGH"
L18_1.m_Face = L19_1
L18_1.m_CharStrID = "OROCHI_JAPAN_NULL_FOOLSDAY"
L18_1.m_Pos = "C"
L19_1 = "걱정 말고 가거라. 우린 기다리는 동료가 있으니까."
L18_1.m_Talk_KOREA = L19_1
L18_1.m_fTalkTime = 0.03
L19_1 = "心配せず行くがいい。我々は仲間を待っているのだからな。"
L18_1.m_Talk_JPN = L19_1
L19_1 = "Do not worry about us. We are waiting for a friend."
L18_1.m_Talk_ENG = L19_1
L19_1 = "儘管回去吧，我們還要等一個人。"
L18_1.m_Talk_TWN = L19_1
L19_1 = "ไม่ต้องห่วงหรอก พวกเรากำลังรอเพื่อนอยู่"
L18_1.m_Talk_THA = L19_1
L19_1 = "Không sao. Chúng ta đang chờ một người bạn."
L18_1.m_Talk_VTN = L19_1
L19_1 = "不用担心，快走吧，我们有同伴要等。"
L18_1.m_Talk_SCN = L19_1
L19_1 = "Mach dir keine Sorgen. Na los, geh schon. Wir warten noch auf eine Kollegin."
L18_1.m_Talk_DEU = L19_1
L19_1 = "Ne t'inquiète pas pour nous. On attend quelqu'un."
L18_1.m_Talk_FRA = L19_1
L19_1 = {}
L20_1 = "FOOLSDAY_PART2_NODE1_EPILOGUE@269#Talk"
L19_1.m_CutScenKey_Talk = L20_1
L20_1 = 269
L19_1.m_CutScenProcessKey = L20_1
L19_1.m_CutScenID = 2700117
L19_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L19_1.m_bWaitClick = true
L19_1.m_fWaitTime = 0
L19_1.m_Face = "UNIT_PRIDE"
L20_1 = "ROSARIA_NPC_FOOLSDAY_NULL"
L19_1.m_CharStrID = L20_1
L19_1.m_Pos = "C"
L20_1 = "마음 내키면 언제든 연락해. 면접은 보게 해줄 테니."
L19_1.m_Talk_KOREA = L20_1
L19_1.m_fTalkTime = 0.03
L20_1 = "気が向いたらいつでも連絡するのじゃ。面接を受けられるようにしてやろう。"
L19_1.m_Talk_JPN = L20_1
L20_1 = "If you feel like applying, let me know. I’ll let you take the interview."
L19_1.m_Talk_ENG = L20_1
L20_1 = "有意願的話隨時聯絡我，我可以安排面試。"
L19_1.m_Talk_TWN = L20_1
L20_1 = "ถ้าพวกเจ้าอยากสมัครงานก็บอกข้านะ ข้าจะพาไปสัมภาษณ์เอง"
L19_1.m_Talk_THA = L20_1
L20_1 = "Nếu muốn ứng tuyển, cứ báo ta nhé. Ta sẽ cho ngươi vào vòng phỏng vấn."
L19_1.m_Talk_VTN = L20_1
L20_1 = "想进公司的话随时联系我。我可以安排面试。"
L19_1.m_Talk_SCN = L20_1
L20_1 = "Wenn du dich bewerben möchtest, lass es mich jederzeit wissen. Ich werde dich zum Interview einladen."
L19_1.m_Talk_DEU = L20_1
L20_1 = "Si vous comptez postuler à mon entreprise, faites-le moi savoir. Je m'arrangerai pour que vous passiez directement les entretiens."
L19_1.m_Talk_FRA = L20_1
L20_1 = {}
L21_1 = "FOOLSDAY_PART2_NODE1_EPILOGUE@270#Talk"
L20_1.m_CutScenKey_Talk = L21_1
L21_1 = 270
L20_1.m_CutScenProcessKey = L21_1
L20_1.m_CutScenID = 2700117
L20_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L20_1.m_bWaitClick = true
L20_1.m_fWaitTime = 0
L20_1.m_Face = "UNIT_PRIDE"
L20_1.m_CharStrID = "KNIGHT_REPLACER_UNIT_FOOLSDAY"
L20_1.m_Pos = "C"
L21_1 = "그래, 다음 번에 만나면 오늘의 패배는 반드시 갚아주지."
L20_1.m_Talk_KOREA = L21_1
L20_1.m_fTalkTime = 0.03
L21_1 = "ああ、次に会ったら今日の借りは必ず返してやるよ。"
L20_1.m_Talk_JPN = L21_1
L21_1 = "Very well. Next time we meet, I'm getting my revenge."
L20_1.m_Talk_ENG = L21_1
L21_1 = "沒問題，下次再見面時，我一定會報仇的！"
L20_1.m_Talk_TWN = L21_1
L21_1 = "เอาล่ะ เจอกันคราวหน้า ฉันจะล้างแค้นให้ได้เลย"
L20_1.m_Talk_THA = L21_1
L21_1 = "Được thôi. Lần tới khi chúng ta gặp nhau, tôi sẽ trả thù đấy."
L20_1.m_Talk_VTN = L21_1
L21_1 = "好！下次再见面，我一定会一雪今日之耻！"
L20_1.m_Talk_SCN = L21_1
L21_1 = "Alles klar. Wenn wir uns das nächste Mal treffen, werde ich dir auf jeden Fall die heutige Niederlage heimzahlen."
L20_1.m_Talk_DEU = L21_1
L21_1 = "Très bien. La prochaine fois, je prendrai ma revanche pour les défaites d'aujourd'hui !"
L20_1.m_Talk_FRA = L21_1
L21_1 = {}
L22_1 = "FOOLSDAY_PART2_NODE1_EPILOGUE@271#Talk"
L21_1.m_CutScenKey_Talk = L22_1
L22_1 = 271
