L28_1 = "R"
L27_1.m_Pos = L28_1
L28_1 = "시종이란 녀석은 목소리만 들리고 끝까지 눈에 안 보이는구나."
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "僕というやつは最後まで声だけで、顔は見せないのだな。"
L27_1.m_Talk_JPN = L28_1
L28_1 = "That servant never shows himself, does he? All I can hear is his voice."
L27_1.m_Talk_ENG = L28_1
L28_1 = "那個叫僕人的傢伙，根本從頭到尾只聞其聲不見其人。"
L27_1.m_Talk_TWN = L28_1
L28_1 = "เจ้าข้ารับใช้อะไรนั่นไม่เคยปรากฏตัวออกมาเลยใช่มั้ยนะ? ข้าได้ยินแต่เสียงของเขาเท่านั้น"
L27_1.m_Talk_THA = L28_1
L28_1 = "Gã người hầu đó chẳng bao giờ lộ mặt nhỉ? Ta chỉ nghe thấy giọng của hắn thôi."
L27_1.m_Talk_VTN = L28_1
L28_1 = "那个叫侍从的家伙，只能听到声音，到最后也没看见人呢。"
L27_1.m_Talk_SCN = L28_1
L28_1 = "Dieser Diener hat sich bis zum Schluss nicht gezeigt, oder? Alles was ich hören konnte, war seine Stimme."
L27_1.m_Talk_DEU = L28_1
L28_1 = "Jusqu'au bout, on aura pas vu le visage de ce fameux laquais. Tout ce que j'ai entendu moi, c'est sa voix."
L27_1.m_Talk_FRA = L28_1
L28_1 = {}
L29_1 = "FOOLSDAY_PART2_NODE1_EPILOGUE@278#Talk"
L28_1.m_CutScenKey_Talk = L29_1
L29_1 = 278
L28_1.m_CutScenProcessKey = L29_1
L28_1.m_CutScenID = 2700117
