L28_1.m_CharStrID = "OROCHI_JAPAN_NULL_FOOLSDAY"
L29_1 = "R"
L28_1.m_Pos = L29_1
L29_1 = "목소리는 내 취향이었는데 말이지."
L28_1.m_Talk_KOREA = L29_1
L28_1.m_fTalkTime = 0.03
L29_1 = "声は我の好みだったのだが。"
L28_1.m_Talk_JPN = L29_1
L29_1 = "His voice was to my taste."
L28_1.m_Talk_ENG = L29_1
L29_1 = "不過他的聲音是我的菜。"
L28_1.m_Talk_TWN = L29_1
L29_1 = "แต่อย่างน้อย เสียงเขาฟังดูเป็นคนดีอยู่นะ"
L28_1.m_Talk_THA = L29_1
L29_1 = "Ít nhất thì giọng hắn ta cũng dễ nghe."
L28_1.m_Talk_VTN = L29_1
L29_1 = "声音是我喜欢的类型。"
L28_1.m_Talk_SCN = L29_1
L29_1 = "Zumindest klang seine Stimme angenehm."
L28_1.m_Talk_DEU = L29_1
L29_1 = "Une voix agréable, du moins."
L28_1.m_Talk_FRA = L29_1
