L30_1.m_Face = "UNIT_PRIDE"
L30_1.m_CharStrID = "OROCHI_JAPAN_NULL_FOOLSDAY"
L31_1 = "R"
L30_1.m_Pos = L31_1
L31_1 = "그 인형이 그렇게 마음에 드느냐?"
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "そんなにそのぬいぐるみが気に入ったのか？"
L30_1.m_Talk_JPN = L31_1
L31_1 = "Do you like the doll that much?"
L30_1.m_Talk_ENG = L31_1
L31_1 = "你這麼喜歡那個娃娃喔？"
L30_1.m_Talk_TWN = L31_1
L31_1 = "เจ้าชอบตุ๊กตานั่นขนาดนั้นเลยเหรอ?"
L30_1.m_Talk_THA = L31_1
L31_1 = "Cô thích con búp bê đó thế cơ à?"
L30_1.m_Talk_VTN = L31_1
L31_1 = "你就那么喜欢那个娃娃？"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Gefällt dir diese Puppe wirklich so sehr?"
L30_1.m_Talk_DEU = L31_1
L31_1 = "Cette peluche te plaît tant que ça ?"
L30_1.m_Talk_FRA = L31_1
