L34_1 = "FOOLSDAY_PART2_NODE1_EPILOGUE@283#Talk"
L33_1.m_CutScenKey_Talk = L34_1
L34_1 = 283
L33_1.m_CutScenProcessKey = L34_1
L33_1.m_CutScenID = 2700117
L33_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L33_1.m_bWaitClick = true
L33_1.m_fWaitTime = 0
L34_1 = "UNIT_LAUGH"
L33_1.m_Face = L34_1
L33_1.m_CharStrID = "KNIGHT_REPLACER_UNIT_FOOLSDAY"
L34_1 = "L"
L33_1.m_Pos = L34_1
L34_1 = "그렇게 열심히 뽑지 않았다면, 이 정도로 마음에 들진 않았을 것 같아."
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "あれほど懸命に取ろうとしてなかったら、こんなに気に入ることはなかったと思う。"
L33_1.m_Talk_JPN = L34_1
L34_1 = "I don’t think I would have liked it this much if I hadn’t put in all the hard work."
L33_1.m_Talk_ENG = L34_1
L34_1 = "要是沒有剛才辛苦的過程，也不會這麼喜歡吧？"
L33_1.m_Talk_TWN = L34_1
L34_1 = "ฉันคิดว่าถ้าไม่ใช่เพราะพยายามอย่างหนัก ก็คงไม่ชอบมันขนาดนี้หรอก"
L33_1.m_Talk_THA = L34_1
L34_1 = "Tôi không nghĩ mình sẽ thích nó thế này nếu tôi không nỗ lực đến thế để có nó."
L33_1.m_Talk_VTN = L34_1
L34_1 = "要不是那么努力才拿到，我可能也不会这么喜欢。"
L33_1.m_Talk_SCN = L34_1
L34_1 = "Ich glaube, dass sie mir nicht so gut gefallen würde, wenn ich nicht all die harte Arbeit in sie investiert hätte."
L33_1.m_Talk_DEU = L34_1
L34_1 = "Je ne pense pas qu'elle m'aurait plu autant si je n'avais pas fait tout ces efforts pour l'avoir."
L33_1.m_Talk_FRA = L34_1
L34_1 = {}
L35_1 = "FOOLSDAY_PART2_NODE1_EPILOGUE@284#Talk"
L34_1.m_CutScenKey_Talk = L35_1
L35_1 = 284
L34_1.m_CutScenProcessKey = L35_1
L34_1.m_CutScenID = 2700117
L34_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L34_1.m_bWaitClick = true
L34_1.m_fWaitTime = 0
L34_1.m_Face = "UNIT_IDLE"
L34_1.m_CharStrID = "OROCHI_JAPAN_NULL_FOOLSDAY"
L35_1 = "R"
L34_1.m_Pos = L35_1
L35_1 = "흥… 사내대장부 같이 생겨선, 아주 감수성 넘치는 소녀가 따로 없구나."
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "ふん……屈強な男のようにしているが、実は感性豊かな少女なんだな。"
L34_1.m_Talk_JPN = L35_1
L35_1 = "Hmph... With looking like a tough guy, you talk like a frail innocent damsel."
L34_1.m_Talk_ENG = L35_1
L35_1 = "哼…長得那麼Man，沒想到是個心思細膩的少女呢。"
L34_1.m_Talk_TWN = L35_1
L35_1 = "หืม... สำหรับคนที่ดูอย่างกับผู้ชายแล้ว เจ้านี่พูดจาอย่างกับสาวน้อยไร้เดียงสา"
L34_1.m_Talk_THA = L35_1
L35_1 = "Hmph... Với một người trông như đàn ông thì ngươi nói cứ như một thiếu nữ ngây ngô, yếu đuối ấy."
L34_1.m_Talk_VTN = L35_1
L35_1 = "哼……外表虽然像个男人，内心却是个感性的少女。"
L34_1.m_Talk_SCN = L35_1
L35_1 = "Hmm ... Trotz deines rauen Erscheinungsbildes, bist du am Ende doch nur ein äußerst sensibles Mädchen."
L34_1.m_Talk_DEU = L35_1
L35_1 = "Hum... malgré ton look macho, je dois dire que tu es assez sensible."
L34_1.m_Talk_FRA = L35_1
L35_1 = {}
