L38_1 = "FOOLSDAY_PART2_NODE1_EPILOGUE@287#Talk"
L37_1.m_CutScenKey_Talk = L38_1
L38_1 = 287
L37_1.m_CutScenProcessKey = L38_1
L37_1.m_CutScenID = 2700117
L37_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L37_1.m_bWaitClick = true
L37_1.m_fWaitTime = 0
L37_1.m_CharStrID = "COLLECTOR_NPC_NULL_FOOLSDAY"
L37_1.m_Pos = "C"
L38_1 = "뭐야. 나 빼놓고 둘이 데이트하고 있었나?"
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "なんだよ。俺をのけ者にして二人でデートしてたのか？"
L37_1.m_Talk_JPN = L38_1
L38_1 = "What’s going on? Are you two having fun without me?"
L37_1.m_Talk_ENG = L38_1
L38_1 = "搞什麼，你們是背著我約會嗎？"
L37_1.m_Talk_TWN = L38_1
L38_1 = "อะไรเนี่ย? พวกเธอไปสนุกกันตอนฉันไม่อยู่เหรอ?"
L37_1.m_Talk_THA = L38_1
L38_1 = "Chuyện gì đang xảy ra thế? Hai người có chuyện gì vui mà không có tôi vậy?"
L37_1.m_Talk_VTN = L38_1
L38_1 = "什么啊，你们两个是在背着我偷偷约会吗？"
L37_1.m_Talk_SCN = L38_1
L38_1 = "Was zum ...? Seid ihr beiden etwa ohne mich auf ein Date gegangen?"
L37_1.m_Talk_DEU = L38_1
L38_1 = "Hé, vous deux ! On s'amuse bien sans moi ?"
L37_1.m_Talk_FRA = L38_1
L38_1 = {}
L39_1 = "FOOLSDAY_PART2_NODE1_EPILOGUE@288#Talk"
L38_1.m_CutScenKey_Talk = L39_1
L39_1 = 288
L38_1.m_CutScenProcessKey = L39_1
L38_1.m_CutScenID = 2700117
L38_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L38_1.m_bWaitClick = true
L38_1.m_fWaitTime = 0
L38_1.m_Face = "UNIT_PRIDE"
L38_1.m_CharStrID = "COLLECTOR_NPC_NULL_FOOLSDAY"
L38_1.m_Pos = "C"
L39_1 = "당연히 서로 물어뜯고 있을 줄 알았더니, 두 사람 사이가 좋아졌나봐?"
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "当然お互い言い争ってるだろうと思ったけど、仲良くなれたようだね。"
L38_1.m_Talk_JPN = L39_1
L39_1 = "I thought you two would be biting each other’s heads off by now. But it looks like you two become close?"
L38_1.m_Talk_ENG = L39_1
L39_1 = "我還以為你們二個會吵翻天，怎麼好像感情變好啦？"
L38_1.m_Talk_TWN = L39_1
L39_1 = "นึกว่าจะหยุมหัวกันตายไปแล้วซะอีก แต่เหมือนความสัมพันธ์จะดีขึ้นกันนะ"
L38_1.m_Talk_THA = L39_1
L39_1 = "Tôi tưởng đáng lẽ giờ hai người phải nhai đầu nhau rồi ấy chứ. Nhưng có vẻ như mối quan hệ của hai người có bước tiến lớn."
L38_1.m_Talk_VTN = L39_1
L39_1 = "我还以为你们肯定会互掐呢，看来你们的关系变好了？"
L38_1.m_Talk_SCN = L39_1
L39_1 = "Ich dachte, ihr beide würdet euch gegenseitig die Köpfe einschlagen. Aber es sieht so aus, als hättet ihr jetzt eine viel innigere Beziehung zueinander."
L38_1.m_Talk_DEU = L39_1
L39_1 = "Je pensais vous retrouver à couteaux tirés, mais on dirait que vous vous entendez bien finalement."
L38_1.m_Talk_FRA = L39_1
L39_1 = {}
L40_1 = "FOOLSDAY_PART2_NODE1_EPILOGUE@289#Talk"
L39_1.m_CutScenKey_Talk = L40_1
L40_1 = 289
L39_1.m_CutScenProcessKey = L40_1
L39_1.m_CutScenID = 2700117
L39_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L39_1.m_bWaitClick = true
L39_1.m_fWaitTime = 0
L39_1.m_Face = "UNIT_IDLE"
L39_1.m_CharStrID = "OROCHI_JAPAN_NULL_FOOLSDAY"
L39_1.m_Pos = "C"
L40_1 = "딱히 변한 건 없다만?"
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "別に変わったことはないのだが？"
L39_1.m_Talk_JPN = L40_1
L40_1 = "Nothing changed much, really."
L39_1.m_Talk_ENG = L40_1
L40_1 = "哪有變？"
L39_1.m_Talk_TWN = L40_1
L40_1 = "จริงๆ ก็ไม่มีอะไรเปลี่ยนไปนักหรอกนะ"
L39_1.m_Talk_THA = L40_1
L40_1 = "Chẳng có gì thay đổi cả."
L39_1.m_Talk_VTN = L40_1
L40_1 = "你怎么还戴着那东西？"
L39_1.m_Talk_SCN = L40_1
L40_1 = "Es hat sich aber nichts wirklich geändert."
L39_1.m_Talk_DEU = L40_1
L40_1 = "Les choses n'ont pas vraiment changé."
L39_1.m_Talk_FRA = L40_1
L40_1 = {}
L41_1 = "FOOLSDAY_PART2_NODE1_EPILOGUE@290#Talk"
L40_1.m_CutScenKey_Talk = L41_1
L41_1 = 290
L40_1.m_CutScenProcessKey = L41_1
L40_1.m_CutScenID = 2700117
L40_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L40_1.m_bWaitClick = true
L40_1.m_fWaitTime = 0
L40_1.m_Face = "UNIT_PRIDE"
L40_1.m_CharStrID = "OROCHI_JAPAN_NULL_FOOLSDAY"
L40_1.m_Pos = "C"
L41_1 = "그러는 넌 수갑을 아직도 풀지 못한 모양이구나."
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "そういう貴様はまだ手錠を外せていないようだな。"
L40_1.m_Talk_JPN = L41_1
L41_1 = "Meanwhile you're still there, handcuffed."
L40_1.m_Talk_ENG = L41_1
L41_1 = "倒是你，你的手銬好像還沒解開呢。"
L40_1.m_Talk_TWN = L41_1
L41_1 = "ส่วนเจ้าก็ยังอยู่ที่นี่ และถูกใส่กุญแจมือ"
L40_1.m_Talk_THA = L41_1
L41_1 = "Xem ra ngươi vẫn bị còng tay."
L40_1.m_Talk_VTN = L41_1
L41_1 = "呼呼，看来你没能解开手铐啊。"
L40_1.m_Talk_SCN = L41_1
L41_1 = "Sieht es so aus, als wärst du die Handschellen immer noch nicht losgeworden."
L40_1.m_Talk_DEU = L41_1
L41_1 = "Et toi en attendant, tu as toujours tes menottes..."
L40_1.m_Talk_FRA = L41_1
L41_1 = {}
L42_1 = "FOOLSDAY_PART2_NODE1_EPILOGUE@291#Talk"
L41_1.m_CutScenKey_Talk = L42_1
L42_1 = 291
L41_1.m_CutScenProcessKey = L42_1
L41_1.m_CutScenID = 2700117
L41_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L41_1.m_bWaitClick = true
L41_1.m_fWaitTime = 0
L41_1.m_Face = "UNIT_HATE"
L41_1.m_CharStrID = "COLLECTOR_NPC_NULL_FOOLSDAY"
L41_1.m_Pos = "C"
L42_1 = "빌어먹을 우주수갑… 너무 튼튼해서 이 동네 엔지니어도 감당을 못 하더라고."
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "クソったれな宇宙手錠……頑丈すぎてこの街のエンジニアも手が付けられなかったんだ。"
L41_1.m_Talk_JPN = L42_1
L42_1 = "These stupid space handcuffs... They’re so sturdy that even the town’s engineer couldn’t do anything."
L41_1.m_Talk_ENG = L42_1
L42_1 = "該死的宇宙手銬…牢固到這附近的工程師也拿它沒辦法。"
L41_1.m_Talk_TWN = L42_1
L42_1 = "ไอ้กุญแจมืออวกาศโง่ๆ นี่... มันทนจนขนาดวิศวกรของเมืองทำอะไรไม่ได้เลย"
L41_1.m_Talk_THA = L42_1
L42_1 = "Cái còng tay không gian ngu ngốc này...Chúng cứng đến mức ngay cả kỹ sư thị trấn cũng bó tay."
L41_1.m_Talk_VTN = L42_1
L42_1 = "该死的宇宙手铐……太结实了，这地方的工程师也没办法。"
L41_1.m_Talk_SCN = L42_1
L42_1 = "Diese verdammten Weltraumhandschellen ... Sie sind so robust, dass selbst der lokale Techniker nichts tun konnte."
L41_1.m_Talk_DEU = L42_1
L42_1 = "Foutues menottes de l'espace... elles sont si résistantes que même le meilleur ingénieur de la ville n'a rien pu faire."
L41_1.m_Talk_FRA = L42_1
L42_1 = {}
L43_1 = "FOOLSDAY_PART2_NODE1_EPILOGUE@292#Talk"
L42_1.m_CutScenKey_Talk = L43_1
L43_1 = 292
L42_1.m_CutScenProcessKey = L43_1
L42_1.m_CutScenID = 2700117
L42_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L42_1.m_bWaitClick = true
L42_1.m_fWaitTime = 0
L42_1.m_Face = "UNIT_IDLE"
L42_1.m_CharStrID = "COLLECTOR_NPC_NULL_FOOLSDAY"
L42_1.m_Pos = "C"
L43_1 = "그래도, 돌아갈 방법은 찾았어. 포탈 수리에 필요한 부품을 구했거든."
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "でも、戻る方法は見つけたよ。ワープ装置の修理に必要な部品があったからね。"
L42_1.m_Talk_JPN = L43_1
L43_1 = "Still, I found a way to get home. I’ve obtained all the parts needed to fix the portal machine."
L42_1.m_Talk_ENG = L43_1
L43_1 = "不過至少我有找到回去的方法，還弄來修理傳送門需要的零件。"
L42_1.m_Talk_TWN = L43_1
L43_1 = "แต่ถึงอย่างนั้น ฉันก็เจอวิธีกลับบ้านแล้วนะ ได้อะไหล่ทุกชิ้นที่ต้องใช้ซ่อมเครื่องวาร์ปมาแล้ว"
L42_1.m_Talk_THA = L43_1
L43_1 = "Nhưng tôi đã tìm ra cách về nhà. Tôi đã thu thập được tất cả bộ phận cần thiết để sửa máy dịch chuyển."
L42_1.m_Talk_VTN = L43_1
L43_1 = "不过我找到回去的办法了。因为我找到用来修理传送门的零件了。"
L42_1.m_Talk_SCN = L43_1
L43_1 = "Zumindest habe ich einen Weg gefunden, um in unsere Welt zurückzukehren. Ich habe außerdem die Teile besorgt, die für die Reparatur des Portals benötigt werden."
L42_1.m_Talk_DEU = L43_1
L43_1 = "Mais j'ai quand même trouvé un moyen de nous faire rentrer à la maison. Mieux, j'ai réuni tous les composants nécessaires pour réparer le portail."
L42_1.m_Talk_FRA = L43_1
L43_1 = {}
L44_1 = "FOOLSDAY_PART2_NODE1_EPILOGUE@293#Talk"
L43_1.m_CutScenKey_Talk = L44_1
L44_1 = 293
L43_1.m_CutScenProcessKey = L44_1
L43_1.m_CutScenID = 2700117
L43_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L43_1.m_bWaitClick = true
L43_1.m_fWaitTime = 0
L43_1.m_Face = "UNIT_IDLE"
L43_1.m_CharStrID = "KNIGHT_REPLACER_UNIT_FOOLSDAY"
L43_1.m_Pos = "C"
L44_1 = "그럼, 이쪽 세계와는 작별인 건가?"
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "じゃあ、こっちの世界とはおさらばなのか？"
L43_1.m_Talk_JPN = L44_1
L44_1 = "I guess we’re gonna have to say goodbye to this world."
L43_1.m_Talk_ENG = L44_1
L44_1 = "意思是，我們要跟這個世界告別了嗎？"
L43_1.m_Talk_TWN = L44_1
L44_1 = "ท่าทางเราคงต้องบอกลาดินแดนนี้แล้วสินะ"
L43_1.m_Talk_THA = L44_1
L44_1 = "Tôi đoán chúng ta phải chào tạm biệt nơi này thôi."
L43_1.m_Talk_VTN = L44_1
L44_1 = "那么就要跟这个世界说再见了吗？"
L43_1.m_Talk_SCN = L44_1
L44_1 = "Ich denke, wir müssen uns von dieser Welt verabschieden."
L43_1.m_Talk_DEU = L44_1
L44_1 = "Oh, alors il est temps de dire adieu à ce monde ?"
L43_1.m_Talk_FRA = L44_1
L44_1 = {}
L45_1 = "FOOLSDAY_PART2_NODE1_EPILOGUE@294#Talk"
L44_1.m_CutScenKey_Talk = L45_1
L45_1 = 294
L44_1.m_CutScenProcessKey = L45_1
L44_1.m_CutScenID = 2700117
L44_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L44_1.m_bWaitClick = true
L44_1.m_fWaitTime = 0
L44_1.m_CharStrID = "COLLECTOR_NPC_NULL_FOOLSDAY"
L44_1.m_Pos = "C"
L45_1 = "그렇게 되겠지."
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "そうなるな。"
L44_1.m_Talk_JPN = L45_1
L45_1 = "I guess so."
L44_1.m_Talk_ENG = L45_1
L45_1 = "是吧。"
L44_1.m_Talk_TWN = L45_1
L45_1 = "ก็คงงั้น"
L44_1.m_Talk_THA = L45_1
L45_1 = "Tôi đoán vậy."
L44_1.m_Talk_VTN = L45_1
L45_1 = "应该是吧。"
L44_1.m_Talk_SCN = L45_1
L45_1 = "So sieht es wohl aus."
L44_1.m_Talk_DEU = L45_1
L45_1 = "On dirait bien, oui."
L44_1.m_Talk_FRA = L45_1
L45_1 = {}
L46_1 = "FOOLSDAY_PART2_NODE1_EPILOGUE@295#Talk"
L45_1.m_CutScenKey_Talk = L46_1
L46_1 = 295
L45_1.m_CutScenProcessKey = L46_1
L45_1.m_CutScenID = 2700117
L45_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L45_1.m_bWaitClick = true
L45_1.m_fWaitTime = 0
L45_1.m_Face = "UNIT_PRIDE"
L45_1.m_CharStrID = "COLLECTOR_NPC_NULL_FOOLSDAY"
L45_1.m_Pos = "C"
L46_1 = "아쉬워? 반나절 사이에 세계에 정이라도 붙이셨나?"
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "名残惜しい？　半日でこの世界に情が湧いたのか？"
L45_1.m_Talk_JPN = L46_1
L46_1 = "Why the lone face? You feel attached already?"
L45_1.m_Talk_ENG = L46_1
L46_1 = "捨不得嗎？才半天時間不見，你就愛上這個世界啦？"
L45_1.m_Talk_TWN = L46_1
L46_1 = "มัยทำหน้าจ๋อยแบบนั้นล่ะ? ผูกพันกับที่นี่ซะแล้วเหรอ?"
L45_1.m_Talk_THA = L46_1
L46_1 = "Không nỡ đi sao? Cô đã cảm thấy gắn bó với chỗ này rồi á?"
L45_1.m_Talk_VTN = L46_1
L46_1 = "舍不得？才半天的时间就爱上这个世界了？"
L45_1.m_Talk_SCN = L46_1
L46_1 = "Warum machst du so ein betrübtes Gesicht? Hast du dich etwa innerhalb eines halben Tages an diese Welt gewöhnt?"
L45_1.m_Talk_DEU = L46_1
L46_1 = "C'est quoi cette tête ? Tu es triste de partir ?"
L45_1.m_Talk_FRA = L46_1
L46_1 = {}
L47_1 = "FOOLSDAY_PART2_NODE1_EPILOGUE@296#Talk"
L46_1.m_CutScenKey_Talk = L47_1
L47_1 = 296
L46_1.m_CutScenProcessKey = L47_1
L46_1.m_CutScenID = 2700117
L46_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L46_1.m_bWaitClick = true
L46_1.m_fWaitTime = 0
L46_1.m_Face = "UNIT_DESPAIR"
L46_1.m_CharStrID = "KNIGHT_REPLACER_UNIT_FOOLSDAY"
L46_1.m_Pos = "C"
L47_1 = "그런 건 아니지만… 조금은 더 머물러도 괜찮을 것 같달까…?"
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "そんなわけじゃないけど……もうちょっといても大丈夫じゃないかなーって……"
L46_1.m_Talk_JPN = L47_1
L47_1 = "Not really... But maybe we could stay a bit longer...?"
L46_1.m_Talk_ENG = L47_1
L47_1 = "不是這樣…只是覺得多待一會兒好像也沒關係…？"
L46_1.m_Talk_TWN = L47_1
L47_1 = "ก็ไม่เชิงหรอก... แต่เราอยู่ต่ออีกนิดได้มั้ยนะ...?"
L46_1.m_Talk_THA = L47_1
L47_1 = "Không phải thế...Nhưng có thể ở lâu hơn chút được không...?"
L46_1.m_Talk_VTN = L47_1
L47_1 = "那倒不是……我就是想多待一段时间好像也不错……？"
L46_1.m_Talk_SCN = L47_1
L47_1 = "Nicht wirklich ... aber vielleicht könnten wir doch ein bisschen länger hier bleiben ...?"
L46_1.m_Talk_DEU = L47_1
L47_1 = "C'est pas ça, mais... on pourrait pas rester un peu plus longtemps ?"
L46_1.m_Talk_FRA = L47_1
L47_1 = {}
