L51_1 = "R_M_I"
L50_1.m_Pos = L51_1
L51_1 = "복수를 해줘야 할 상대가 생겼다."
L50_1.m_Talk_KOREA = L51_1
L50_1.m_fTalkTime = 0.03
L51_1 = "復讐をすべき相手ができた。"
L50_1.m_Talk_JPN = L51_1
L51_1 = "We have someone to take vengeance on."
L50_1.m_Talk_ENG = L51_1
L51_1 = "因為現在有要報仇的對象。"
L50_1.m_Talk_TWN = L51_1
L51_1 = "มีคนที่เราต้องล้างแค้นน่ะ"
L50_1.m_Talk_THA = L51_1
L51_1 = "Chúng ta phải trả thù."
L50_1.m_Talk_VTN = L51_1
L51_1 = "因为要报仇。"
L50_1.m_Talk_SCN = L51_1
L51_1 = "Dass es jemanden gibt, mit dem wir noch eine Rechnung offen haben."
L50_1.m_Talk_DEU = L51_1
L51_1 = "Parce qu'on doit se venger de quelqu'un."
L50_1.m_Talk_FRA = L51_1
