L2_1 = "FOOLSDAY_PART2_NODE1_EPILOGUE@301#Talk"
L1_1.m_CutScenKey_Talk = L2_1
L2_1 = 301
L1_1.m_CutScenProcessKey = L2_1
L1_1.m_CutScenID = 2700117
L1_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L1_1.m_bWaitClick = true
L1_1.m_fWaitTime = 0
L1_1.m_Face = "UNIT_PRIDE"
L1_1.m_CharStrID = "OROCHI_JAPAN_NULL_FOOLSDAY"
L2_1 = "R"
L1_1.m_Pos = L2_1
L2_1 = "우리 같은 자존심 높은 악당이 지고 살 수는 없지 않겠느냐?"
L1_1.m_Talk_KOREA = L2_1
L1_1.m_fTalkTime = 0.03
L2_1 = "我々のようなプライド高き悪党が負けていられないではないか。"
L1_1.m_Talk_JPN = L2_1
L2_1 = "We’re dignified villains. Surely we can’t let a grudge pass, no?"
L1_1.m_Talk_ENG = L2_1
L2_1 = "像我們這種愛面子的反派怎麼可以服輸？"
L1_1.m_Talk_TWN = L2_1
L2_1 = "เราเป็นวายร้ายผู้สง่างามนะ จะปล่อยให้ความอาฆาตผ่านไปได้ยังไง จริงหรือไม่?"
L1_1.m_Talk_THA = L2_1
L2_1 = "Chúng ta là những kẻ phản diện có tự trọng. Chắc chắn là chúng ta không thể bỏ qua hận thù được, đúng chứ?"
L1_1.m_Talk_VTN = L2_1
L2_1 = "像我们这种自尊心很强的反派，总不能轻易向人认输吧？"
L1_1.m_Talk_SCN = L2_1
