L3_1.m_CutScenKey_Talk = L4_1
L4_1 = 303
L3_1.m_CutScenProcessKey = L4_1
L3_1.m_CutScenID = 2700117
L3_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L3_1.m_bWaitClick = true
L3_1.m_fWaitTime = 0
L3_1.m_Face = "UNIT_SERIOUS"
L3_1.m_CharStrID = "KNIGHT_REPLACER_UNIT_FOOLSDAY"
L4_1 = "L"
L3_1.m_Pos = L4_1
L4_1 = "마, 맞아! 오늘 꽤 강한 녀석을 만났는데 아쉽게 져버렸거든!"
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "そ、そうだぞ！　今日結構強いやつに会ったんだけど、残念ながら負けちゃってな！"
L3_1.m_Talk_JPN = L4_1
L4_1 = "S-she’s right! We met someone quite hard to beat, it was such a close call!"
L3_1.m_Talk_ENG = L4_1
L4_1 = "沒…沒錯！今天遇到高手，雖然我不幸落敗，"
L3_1.m_Talk_TWN = L4_1
L4_1 = "จะ-จริงของเธอ! เราไปเจอคนที่เอาชนะยากมากมาล่ะ เกือบไปแล้วเลย!"
L3_1.m_Talk_THA = L4_1
L4_1 = "C-cô ấy nói đúng! Chúng ta đã gặp người thực sự khó chơi, suýt tí nữa thì toi mạng đấy!"
L3_1.m_Talk_VTN = L4_1
L4_1 = "没、没错！今天我们遇到了一个很强大的家伙，遗憾的是我们输了！"
L3_1.m_Talk_SCN = L4_1
L4_1 = "Sie hat recht! Ich habe heute eine ziemlich starke Gegnerin getroffen, aber ich habe leider verloren!"
L3_1.m_Talk_DEU = L4_1
L4_1 = "E-Elle a raison ! On a perdu de justesse aujourd'hui, l'adversaire était redoutable."
L3_1.m_Talk_FRA = L4_1
L4_1 = {}
L5_1 = "FOOLSDAY_PART2_NODE1_EPILOGUE@304#Talk"
L4_1.m_CutScenKey_Talk = L5_1
L5_1 = 304
L4_1.m_CutScenProcessKey = L5_1
L4_1.m_CutScenID = 2700117
L4_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L4_1.m_bWaitClick = true
L4_1.m_fWaitTime = 0
L4_1.m_Face = "UNIT_PRIDE"
L4_1.m_CharStrID = "KNIGHT_REPLACER_UNIT_FOOLSDAY"
L5_1 = "L"
L4_1.m_Pos = L5_1
L5_1 = "하지만 마지막에 이기는 게 진짜 승자인 법이니까! 무슨 말인지 알지?"
L4_1.m_Talk_KOREA = L5_1
L4_1.m_fTalkTime = 0.03
L5_1 = "だけど、最後に勝った方が本物の勝者だからさ！　この意味わかるか？"
L4_1.m_Talk_JPN = L5_1
L5_1 = "But the last one standing becomes the winner! You know what I’m saying, right?"
L4_1.m_Talk_ENG = L5_1
L5_1 = "不過贏得最終勝利的人才是真正的贏家！你懂我意思吧？"
L4_1.m_Talk_TWN = L5_1
L5_1 = "แต่เขาว่ากันว่าคนที่ยืนหยัดเป็นคนสุดท้ายคือคนชนะไงล่ะ! รู้ใช่มั้ยว่าฉันหมายความว่ายังไง?"
L4_1.m_Talk_THA = L5_1
L5_1 = "Nhưng họ nói người đứng vững cuối cùng sẽ trở thành người thắng cuộc! Cô biết tôi nói gì mà, đúng không?"
L4_1.m_Talk_VTN = L5_1
L5_1 = "不过一时的胜负不算什么！你知道这话是什么意思吧？"
L4_1.m_Talk_SCN = L5_1
L5_1 = "Aber nur wer am Ende gewinnt, ist der wahre Gewinner! Du weißt, was ich dir damit sagen will, oder?"
L4_1.m_Talk_DEU = L5_1
L5_1 = "On dit bien que le vrai vainqueur est celui qui gagne la dernière manche, non ?"
L4_1.m_Talk_FRA = L5_1
