L8_1 = "요지는 이해했어. 어차피 당장은 돌아가기 힘들어졌으니까."
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "要旨は理解した。どうせ今すぐには戻れなくなったからな。"
L7_1.m_Talk_JPN = L8_1
L8_1 = "I get your point. We’re not going back immediately anyway."
L7_1.m_Talk_ENG = L8_1
L8_1 = "明白，反正現在也很難回去。"
L7_1.m_Talk_TWN = L8_1
L8_1 = "เข้าใจละ ยังไงเราก็ไม่ได้จะกลับกันทันทีอยู่แล้วนี่นะ"
L7_1.m_Talk_THA = L8_1
L8_1 = "Tôi hiểu ý cô. Dù sao chúng ta sẽ không về ngay."
L7_1.m_Talk_VTN = L8_1
L8_1 = "意思我明白了。反正也很难马上就回去。"
L7_1.m_Talk_SCN = L8_1
L8_1 = "Ja, ich habe es verstanden. Wir können sowieso nicht sofort zurückkehren."
L7_1.m_Talk_DEU = L8_1
L8_1 = "Dit comme ça, je comprends mieux. De toute façon, on peut pas partir tout de suite."
L7_1.m_Talk_FRA = L8_1
