L9_1.m_Talk_JPN = L10_1
L10_1 = "It takes at least a year to fix the dimensional portal."
L9_1.m_Talk_ENG = L10_1
L10_1 = "修理次元傳送門起碼要花一年的時間。"
L9_1.m_Talk_TWN = L10_1
L10_1 = "ก็กว่าจะซ่อมประตูมิติได้ก็ใช้เวลาอย่างน้อยหนึ่งปีน่ะ"
L9_1.m_Talk_THA = L10_1
L10_1 = "Cần ít nhất một năm để sửa lỗi cổng không gian."
L9_1.m_Talk_VTN = L10_1
L10_1 = "要想修好次元传送门，至少需要一年时间。"
