L18_1 = "R"
L17_1.m_Pos = L18_1
L18_1 = "이렇게 된 이상 어쩔 수 없이 직장이라도 구해서 돈을 벌어야겠구나."
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "こうなっては、仕方なく職場でも探して金を稼ぐべきだな。"
L17_1.m_Talk_JPN = L18_1
L18_1 = "I suppose we have no choice but to apply for jobs to make money."
L17_1.m_Talk_ENG = L18_1
L18_1 = "既然如此，那只好勉為其難找個工作來賺錢餬口囉。"
L17_1.m_Talk_TWN = L18_1
L18_1 = "เกรงว่าข้าจะไม่มีทางเลือกนอกจากต้องไปสมัครงานแล้ว อย่างไรเสียเราก็ต้องทำมาหากินนะจริงไหม?"
L17_1.m_Talk_THA = L18_1
L18_1 = "Chắc chúng ta không có lựa chọn nào khác ngoài tìm việc rồi. Dù sao chúng ta cũng phải kiếm sống chứ?"
L17_1.m_Talk_VTN = L18_1
L18_1 = "既然如此，就不得不找份工作赚钱了。"
L17_1.m_Talk_SCN = L18_1
L18_1 = "Ich nehme an, ich habe keine andere Wahl, als mich um einen Job zu bewerben. Wir müssen ja irgendwie unseren Lebensunterhalt verdienen, nicht wahr?"
L17_1.m_Talk_DEU = L18_1
L18_1 = "Au point où on en est, autant postuler dans cette entreprise. Il faudra bien qu'on gagne nos vies, non ?"
L17_1.m_Talk_FRA = L18_1
L18_1 = {}
L19_1 = "FOOLSDAY_PART2_NODE1_EPILOGUE@318#Talk"
L18_1.m_CutScenKey_Talk = L19_1
L19_1 = 318
L18_1.m_CutScenProcessKey = L19_1
L18_1.m_CutScenID = 2700117
L18_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L18_1.m_bWaitClick = true
L18_1.m_fWaitTime = 0
L18_1.m_Face = "UNIT_PRIDE"
L18_1.m_CharStrID = "KNIGHT_REPLACER_UNIT_FOOLSDAY"
L19_1 = "L"
L18_1.m_Pos = L19_1
L19_1 = "이야, 어쩔 수 없구만."
L18_1.m_Talk_KOREA = L19_1
L18_1.m_fTalkTime = 0.03
L19_1 = "いやあ、仕方ないなあ。"
L18_1.m_Talk_JPN = L19_1
L19_1 = "Ohh, how unfortunate."
L18_1.m_Talk_ENG = L19_1
L19_1 = "哎呀，真的是勉為其難。"
L18_1.m_Talk_TWN = L19_1
L19_1 = "เอ้อ น่าเศร้าจริง"
L18_1.m_Talk_THA = L19_1
L19_1 = "Ohh, thật xui xẻo."
L18_1.m_Talk_VTN = L19_1
L19_1 = "是呀，没办法了呢。"
L18_1.m_Talk_SCN = L19_1
L19_1 = "Ohh, da kann man wohl nichts machen."
L18_1.m_Talk_DEU = L19_1
L19_1 = "Oh non, quel malheur..."
L18_1.m_Talk_FRA = L19_1
