L21_1 = "FOOLSDAY_PART2_NODE1_EPILOGUE@320#Talk"
L20_1.m_CutScenKey_Talk = L21_1
L21_1 = 320
L20_1.m_CutScenProcessKey = L21_1
L20_1.m_CutScenID = 2700117
L20_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L20_1.m_bWaitClick = true
L20_1.m_fWaitTime = 0
L20_1.m_Face = "UNIT_IDLE"
L20_1.m_CharStrID = "COLLECTOR_NPC_NULL_FOOLSDAY"
L20_1.m_Pos = "C"
L21_1 = "세계정복이니 뭐니 하며 떠들어댈 줄 알았더니, 그건 상상도 못한 대답이군."
L20_1.m_Talk_KOREA = L21_1
L20_1.m_fTalkTime = 0.03
L21_1 = "世界征服だのなんだの騒ぐかと思ったら、想像もしなかった答えだね。"
L20_1.m_Talk_JPN = L21_1
L21_1 = "I thought it would be gibberish similar to world domination or something... That was unexpected."
L20_1.m_Talk_ENG = L21_1
L21_1 = "之前是誰說什麼要征服世界的，這是什麼神展開？"
L20_1.m_Talk_TWN = L21_1
L21_1 = "ไอ้เราก็นึกว่าจะเป็นอะไรที่พูดพล่อยๆ เหมือนเรื่องครองโลกอะไรนั่น... นี่มันผิดคาดชะมัด"
L20_1.m_Talk_THA = L21_1
L21_1 = "Tôi tưởng nó sẽ vô nghĩa như thống trị thế giới hay gì đó chứ... Thật bất ngờ."
L20_1.m_Talk_VTN = L21_1
L21_1 = "我还以为你们会吵着要征服世界什么的呢，现在这个回答真是出乎我的意料。"
L20_1.m_Talk_SCN = L21_1
L21_1 = "Ich dachte, du würdest wieder damit anfangen von der Eroberung dieser Welt zu sprechen, oder so ... aber das war definitiv nicht die Antwort, mit der ich gerechnet hatte."
L20_1.m_Talk_DEU = L21_1
L21_1 = "Moi qui m'attendais à entendre l'habituelle rengaine sur la conquête de l'espace... c'est inattendu."
L20_1.m_Talk_FRA = L21_1
L21_1 = {}
L22_1 = "FOOLSDAY_PART2_NODE1_EPILOGUE@321#Talk"
L21_1.m_CutScenKey_Talk = L22_1
L22_1 = 321
L21_1.m_CutScenProcessKey = L22_1
L21_1.m_CutScenID = 2700117
L21_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L21_1.m_bWaitClick = true
L21_1.m_fWaitTime = 0
L21_1.m_CharStrID = "COLLECTOR_NPC_NULL_FOOLSDAY"
L21_1.m_Pos = "C"
L22_1 = "악당이 뭣하러 직장을 구해? 그냥 남들 주머니를 털어버리면 되는 거 아닌가?"
L21_1.m_Talk_KOREA = L22_1
L21_1.m_fTalkTime = 0.03
L22_1 = "悪党がなんで職場を探すんだよ。別に人の懐からいただけばいいだろ？"
L21_1.m_Talk_JPN = L22_1
L22_1 = "Why would villains want to get a job? You could just rob others."
L21_1.m_Talk_ENG = L22_1
L22_1 = "反派還找什麼工作？直接搶劫別人的口袋就好啦？"
L21_1.m_Talk_TWN = L22_1
L22_1 = "จะไปหางานทำทำไมล่ะในเมื่อไปปล้นคนอื่นเอาก็ได้น่ะ?"
L21_1.m_Talk_THA = L22_1
L22_1 = "Tại sao cô lại muốn tìm việc trong khi có thể cướp bóc từ người khác chứ?"
L21_1.m_Talk_VTN = L22_1
L22_1 = "恶棍找工作干什么？打劫别人不就行了吗？"
L21_1.m_Talk_SCN = L22_1
L22_1 = "Warum sollte sich eigentlich eine Schurkin einen Job suchen? Sollten wir nicht einfach aus den Taschen anderer Leute stehlen?"
L21_1.m_Talk_DEU = L22_1
L22_1 = "Pourquoi vous emmerder à trouver un emploi quand vous pouvez simplement voler l'argent des autres ?"
L21_1.m_Talk_FRA = L22_1
L22_1 = {}
