L24_1 = "FOOLSDAY_PART2_NODE1_EPILOGUE@323#Talk"
L23_1.m_CutScenKey_Talk = L24_1
L24_1 = 323
L23_1.m_CutScenProcessKey = L24_1
L23_1.m_CutScenID = 2700117
L23_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L23_1.m_bWaitClick = true
L23_1.m_fWaitTime = 0
L23_1.m_Face = "UNIT_SERIOUS"
L23_1.m_CharStrID = "KNIGHT_REPLACER_UNIT_FOOLSDAY"
L24_1 = "L_M_I"
L23_1.m_Pos = L24_1
L24_1 = "그건 안되지! 그렇게 쉽게 빼앗으면 보람이 없다고!"
L23_1.m_Talk_KOREA = L24_1
L23_1.m_fTalkTime = 0.03
L24_1 = "それはダメだ！　そう簡単に奪ったらやりがいがないだろ！"
L23_1.m_Talk_JPN = L24_1
L24_1 = "No taking! Where’s the fun in that?"
L23_1.m_Talk_ENG = L24_1
L24_1 = "那怎麼行！得之不易才顯得珍貴！"
L23_1.m_Talk_TWN = L24_1
L24_1 = "ไม่ปลงไม่ปล้นแล้ว! แบบนั้นจะไปสนุกตรงไหน?"
L23_1.m_Talk_THA = L24_1
L24_1 = "Này! Làm thế thì có gì mà vui?"
L23_1.m_Talk_VTN = L24_1
L24_1 = "那不行！轻易抢到手的话就没有意义了！"
L23_1.m_Talk_SCN = L24_1
L24_1 = "Das geht doch nicht! Wo bleibt denn da der Spaß daran?"
L23_1.m_Talk_DEU = L24_1
L24_1 = "Mais non, enfin ! Et le sentiment d'accomplissement, alors ?"
L23_1.m_Talk_FRA = L24_1
L24_1 = {}
L25_1 = "FOOLSDAY_PART2_NODE1_EPILOGUE@324#Talk"
L24_1.m_CutScenKey_Talk = L25_1
L25_1 = 324
L24_1.m_CutScenProcessKey = L25_1
L24_1.m_CutScenID = 2700117
L24_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L24_1.m_bWaitClick = true
L24_1.m_fWaitTime = 0
L24_1.m_Face = "UNIT_IDLE"
L24_1.m_CharStrID = "OROCHI_JAPAN_NULL_FOOLSDAY"
L25_1 = "R_M_I"
L24_1.m_Pos = L25_1
L25_1 = "빼앗는 것도 좋지만, 가끔은 인간들의 문명을 직접 체험해보는 것도 재밌을 것 같아서 말이다."
L24_1.m_Talk_KOREA = L25_1
L24_1.m_fTalkTime = 0.03
L25_1 = "奪うのもいいのだが、たまには人間の文明を直接体験してみることも面白そうでな。"
L24_1.m_Talk_JPN = L25_1
L25_1 = "Robbery is fine, but I think it'd be nice to experience human culture every now and then."
L24_1.m_Talk_ENG = L25_1
L25_1 = "直接行搶也很好，只是偶爾體驗一下人類的文明應該也蠻有趣的。"
L24_1.m_Talk_TWN = L25_1
L25_1 = "ปล้นก็ไม่ได้เลวร้ายอะไร แต่ข้าว่า บางครั้ง การได้ไปสัมผัสวัฒนธรรมของมนุษย์บ้างก็น่าจะดี"
L24_1.m_Talk_THA = L25_1
L25_1 = "Cướp cũng được, nhưng ta nghĩ thỉnh thoảng trải nghiệm văn hóa loài người chẳng phải cũng thú vị sao."
L24_1.m_Talk_VTN = L25_1
L25_1 = "打劫固然好，但偶尔亲自体验人类的文明应该也很有意思。"
L24_1.m_Talk_SCN = L25_1
L25_1 = "Stehlen mag ja schön und gut sein, aber ich denke, es wäre schön, hin und wieder mal die menschliche Kultur zu erleben."
L24_1.m_Talk_DEU = L25_1
L25_1 = "Le vol ça va bien deux minutes mais parfois, il faut essayer de penser autrement. Vivre comme les humains, ça promet d'être une expérience enrichissante."
L24_1.m_Talk_FRA = L25_1
L25_1 = {}
