L27_1 = "FOOLSDAY_PART2_NODE1_EPILOGUE@326#Talk"
L26_1.m_CutScenKey_Talk = L27_1
L27_1 = 326
L26_1.m_CutScenProcessKey = L27_1
L26_1.m_CutScenID = 2700117
L26_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L26_1.m_bWaitClick = true
L26_1.m_fWaitTime = 0
L26_1.m_CharStrID = "COLLECTOR_NPC_NULL_FOOLSDAY"
L27_1 = "너희들… 그새 사이비한테 세뇌라도 당했냐? 아니면 도플갱어인가?"
L26_1.m_Talk_KOREA = L27_1
L26_1.m_fTalkTime = 0.03
L27_1 = "お前ら……カルト集団に洗脳でもされたのか？　それともドッペルゲンガー？"
L26_1.m_Talk_JPN = L27_1
L27_1 = "Hey... Were you brainwashed by cults or something? Or are you Doppelgangers?"
L26_1.m_Talk_ENG = L27_1
L27_1 = "你們…是被誰洗腦嗎？還是你們其實是二重身？"
L26_1.m_Talk_TWN = L27_1
L27_1 = "นี่... ไปโดนลัทธิอะไรล้างสมองกันมารึไงเนี่ย? หรือพวกเธอเป็นดอปเพลแกงเกอร์?"
L26_1.m_Talk_THA = L27_1
L27_1 = "Này...Cô bị giáo phái tẩy não hay sao? Hay cô là Kẻ Song Trùng?"
L26_1.m_Talk_VTN = L27_1
L27_1 = "你们……是被邪教给洗脑了吗？还是在我回来的路上被模仿者给掉包了？"
L26_1.m_Talk_SCN = L27_1
L27_1 = "Hey ihr beiden ... Wurdet ihr von einer Sekte einer Gehirnwäsche unterzogen? Oder seid ihr etwa Doppelgänger?"
L26_1.m_Talk_DEU = L27_1
L27_1 = "Euh... Vous avez eu un lavage de cerveau quand j'étais pas là ? Ou alors vous êtes des clones ?"
L26_1.m_Talk_FRA = L27_1
L27_1 = {}
