L27_1.m_CharStrID = "KNIGHT_REPLACER_UNIT_FOOLSDAY"
L28_1 = "L"
L27_1.m_Pos = L28_1
L28_1 = "사이비가 뭔데?"
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "カルトって何だ？"
L27_1.m_Talk_JPN = L28_1
L28_1 = "What’s a cult?"
L27_1.m_Talk_ENG = L28_1
L28_1 = "洗腦是什麼？"
L27_1.m_Talk_TWN = L28_1
L28_1 = "ลัทธงลัทธิอะไรนะ?"
L27_1.m_Talk_THA = L28_1
L28_1 = "Giáo phái là gì cơ?"
L27_1.m_Talk_VTN = L28_1
L28_1 = "邪教是什么？"
L27_1.m_Talk_SCN = L28_1
L28_1 = "Was ist denn eine Sekte?"
L27_1.m_Talk_DEU = L28_1
L28_1 = "Un lavage de cerveau ?"
L27_1.m_Talk_FRA = L28_1
