L28_1.m_CutScenKey_Talk = L29_1
L29_1 = 328
L28_1.m_CutScenProcessKey = L29_1
L28_1.m_CutScenID = 2700117
L28_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L28_1.m_bWaitClick = true
L28_1.m_fWaitTime = 0
L28_1.m_Face = "UNIT_IDLE"
L28_1.m_CharStrID = "OROCHI_JAPAN_NULL_FOOLSDAY"
L29_1 = "R"
L28_1.m_Pos = L29_1
L29_1 = "도플갱어라는 건 또 무엇이냐?"
L28_1.m_Talk_KOREA = L29_1
L28_1.m_fTalkTime = 0.03
L29_1 = "ドッペルゲンガーとはまた何なのだ？"
L28_1.m_Talk_JPN = L29_1
L29_1 = "What’s a Doppelganger?"
L28_1.m_Talk_ENG = L29_1
L29_1 = "二重身又是什麼？"
L28_1.m_Talk_TWN = L29_1
L29_1 = "ดอปเพลแกงเกอร์อะไรนะ?"
L28_1.m_Talk_THA = L29_1
L29_1 = "Kẻ song trùng là thứ gì?"
L28_1.m_Talk_VTN = L29_1
L29_1 = "模仿者又是什么？"
L28_1.m_Talk_SCN = L29_1
L29_1 = "Und was zur Hölle ist ein Doppelgänger?"
L28_1.m_Talk_DEU = L29_1
L29_1 = "Un clone ? Qu'est-ce que c'est ?"
L28_1.m_Talk_FRA = L29_1
