L31_1 = "FOOLSDAY_PART2_NODE1_EPILOGUE@330#Talk"
L30_1.m_CutScenKey_Talk = L31_1
L31_1 = 330
L30_1.m_CutScenProcessKey = L31_1
L30_1.m_CutScenID = 2700117
L30_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L30_1.m_bWaitClick = true
L30_1.m_fWaitTime = 0
L30_1.m_Face = "UNIT_DESPAIR"
L30_1.m_CharStrID = "COLLECTOR_NPC_NULL_FOOLSDAY"
L30_1.m_Pos = "C"
L31_1 = "…내가 알고 있던 얼간이들이 맞군."
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "……俺の知ってるアホたちで間違いないな。"
L30_1.m_Talk_JPN = L31_1
L31_1 = "...Never mind. It is you after all, idiots."
L30_1.m_Talk_ENG = L31_1
L31_1 = "…確實是我認識的那個二傻瓜沒錯。"
L30_1.m_Talk_TWN = L31_1
L31_1 = "...ช่างเหอะ ยังไงมันก็พวกเธอแหละ ปัญญาอ่อน"
L30_1.m_Talk_THA = L31_1
L31_1 = "...Thôi bỏ đi. Vẫn là đồ ngốc các cô rồi."
L30_1.m_Talk_VTN = L31_1
L31_1 = "……还是我认识的笨蛋们，没错啊。"
L30_1.m_Talk_SCN = L31_1
L31_1 = "... Schon gut. Ihr seid anscheinend doch die Deppen, die ich kenne."
L30_1.m_Talk_DEU = L31_1
L31_1 = "... Non, rien. C'est bien vous, pas de doute."
L30_1.m_Talk_FRA = L31_1
L31_1 = {}
L32_1 = "FOOLSDAY_PART2_NODE1_EPILOGUE@331#Talk"
L31_1.m_CutScenKey_Talk = L32_1
L32_1 = 331
L31_1.m_CutScenProcessKey = L32_1
L31_1.m_CutScenID = 2700117
L31_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L31_1.m_bWaitClick = true
L31_1.m_fWaitTime = 0
L32_1 = "UNIT_LAUGH"
L31_1.m_Face = L32_1
L31_1.m_CharStrID = "COLLECTOR_NPC_NULL_FOOLSDAY"
L31_1.m_Pos = "C"
L32_1 = "뭐, 언제 우주경찰이 여기까지 들이닥칠지 모르니 그런 위장 신분을 하나 만들어 두는 것도 괜찮겠지."
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "まあ、いつ宇宙警察がここまで押し寄せてくるかわからないから、そういった偽の身分を作っておくのも悪くない。"
L31_1.m_Talk_JPN = L32_1
L32_1 = "Since we don’t know when those space cops might come barging in, it would be a good idea to keep a fake identity."
L31_1.m_Talk_ENG = L32_1
L32_1 = "好吧，宇宙警察不知道什麼時候會追到這裡來，找個工作偽裝身分也不錯。"
L31_1.m_Talk_TWN = L32_1
L32_1 = "ในเมื่อเราไม่รู้ว่าพวกตำรวจอวกาศจะโผล่มาตอนไหน ปลอมๆ ตัวกันไว้ก็เข้าท่านะ"
L31_1.m_Talk_THA = L32_1
L32_1 = "Vì chúng ta không biết khi nào bọn cảnh sát không gian đó lại ập tới, tốt nhất hãy tạo danh tính giả đi."
L31_1.m_Talk_VTN = L32_1
L32_1 = "嗯，说不定哪天宇宙警察就会找到这里，弄个伪装的身份也不错。"
L31_1.m_Talk_SCN = L32_1
L32_1 = "Da wir nicht wissen, wann diese Weltraumbullen hier auftauchen werden, wäre es eine gute Idee, eine gefälschte Identität anzunehmen."
L31_1.m_Talk_DEU = L32_1
L32_1 = "Bon. Vu qu'on sait jamais quand les flics de l'espace pourraient nous tomber dessus, il va falloir qu'on se crée de nouvelles identités."
L31_1.m_Talk_FRA = L32_1
L32_1 = {}
L33_1 = "FOOLSDAY_PART2_NODE1_EPILOGUE@332#Talk"
