L32_1.m_Face = "UNIT_PRIDE"
L33_1 = "FX_CUTSCEN_NOISE_RUSTLE_04"
L32_1.m_StartFXSoundName = L33_1
L32_1.m_CharStrID = "KNIGHT_REPLACER_UNIT_FOOLSDAY"
L32_1.m_Pos = "C"
L32_1.m_Crash = 30
L33_1 = "좋았어! 오늘은 취업기념으로 밥이나 먹자고!"
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "よっし！　今日は就職記念に飯にでも行こうぜ！"
L32_1.m_Talk_JPN = L33_1
L33_1 = "Yes! Let’s eat out to celebrate our new job!"
L32_1.m_Talk_ENG = L33_1
L33_1 = "好欸！那就去吃飯慶祝找到工作吧！"
L32_1.m_Talk_TWN = L33_1
L33_1 = "ใช่! ไปหาอะไรกินฉลองสมัครงานกันเถอะ!"
L32_1.m_Talk_THA = L33_1
L33_1 = "Được! Hãy đi nhà hàng để chúc mừng chúng ta đi xin việc nào!"
L32_1.m_Talk_VTN = L33_1
L33_1 = "好！为了纪念今天找到工作，一起去吃饭吧！"
L32_1.m_Talk_SCN = L33_1
L33_1 = "Gut! Lasst uns was essen gehen, um unsere Bewerbungen zu feiern!"
L32_1.m_Talk_DEU = L33_1
L33_1 = "Ok ! Allons manger dehors pour célébrer cette nouvelle vie !"
L32_1.m_Talk_FRA = L33_1
