L36_1 = "FOOLSDAY_PART2_NODE1_EPILOGUE@335#Talk"
L35_1.m_CutScenKey_Talk = L36_1
L36_1 = 335
L35_1.m_CutScenProcessKey = L36_1
L35_1.m_CutScenID = 2700117
L35_1.m_CutScenStrID = "FOOLSDAY_PART2_NODE1_EPILOGUE"
L35_1.m_bWaitClick = true
L35_1.m_fWaitTime = 0
L35_1.m_CharStrID = "COLLECTOR_NPC_NULL_FOOLSDAY"
L36_1 = "벌써 결정됐다는 듯이 말하지 마."
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "もう決まった風に言うな。"
L35_1.m_Talk_JPN = L36_1
L36_1 = "Don’t talk as if you already got a job."
L35_1.m_Talk_ENG = L36_1
L36_1 = "不要講得一副已經找到工作的樣子，"
L35_1.m_Talk_TWN = L36_1
L36_1 = "อย่าพูดจาเหมือนได้งานแล้วน่า"
L35_1.m_Talk_THA = L36_1
L36_1 = "Đừng nói như kiểu cô đã xin được việc rồi."
L35_1.m_Talk_VTN = L36_1
L36_1 = "不要说得好像你已经被录用了似的。"
L35_1.m_Talk_SCN = L36_1
L36_1 = "Rede nicht so, als wäre es bereits entschieden."
L35_1.m_Talk_DEU = L36_1
L36_1 = "Noie pas la peau de l'ours avant d'avoir tué le poisson, t'as même pas encore passé l'entretien."
L35_1.m_Talk_FRA = L36_1
L36_1 = {}
L37_1 = "FOOLSDAY_PART2_NODE1_EPILOGUE@336#Talk"
