L36_1.m_CharStrID = "COLLECTOR_NPC_NULL_FOOLSDAY"
L37_1 = "이력서나 준비해두라고."
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "履歴書から用意しておけ。"
L36_1.m_Talk_JPN = L37_1
L37_1 = "Talk after you’ve prepared your resume."
L36_1.m_Talk_ENG = L37_1
L37_1 = "先準備好你的履歷表吧。"
L36_1.m_Talk_TWN = L37_1
L37_1 = "เตรียมเรซูเมให้เรียบร้อยค่อยมาพูดเถอะ"
L36_1.m_Talk_THA = L37_1
L37_1 = "Hãy nói chuyện sau khi cô đã chuẩn bị CV nhé?"
L36_1.m_Talk_VTN = L37_1
L37_1 = "先准备好简历吧。"
L36_1.m_Talk_SCN = L37_1
L37_1 = "Sieh lieber zu, dass du einen Lebenslauf vorbereitest."
L36_1.m_Talk_DEU = L37_1
L37_1 = "Commence déjà par préparer ton C.V."
L36_1.m_Talk_FRA = L37_1
L37_1 = {}
